    def _perfiles_contexto_guardado(self, contexto, tipo_contexto=""):
        """Obtiene dominios fuertes del contexto anterior sin depender solo del texto.

        Esto permite distinguir un seguimiento real (por ejemplo, ``return`` después
        de funciones en Python) de una nueva pregunta corta que cambia de materia
        (por ejemplo, ``qué es una memoria RAM`` después de hablar de Python).
        """
        contexto = contexto or {}
        partes = [
            str(contexto.get("tema_base") or ""),
            str(contexto.get("consulta") or ""),
            str(contexto.get("ramo") or ""),
            str(contexto.get("coleccion") or ""),
            " ".join(str(x) for x in (contexto.get("colecciones") or []) if x),
        ]
        for r in (contexto.get("resultados") or contexto.get("locales") or [])[:6]:
            if isinstance(r, dict):
                partes.extend([
                    str(r.get("ramo") or ""),
                    str(r.get("coleccion") or ""),
                ])
        perfiles = set(self._perfil_dominio_router(" ".join(partes)))

        # Los nombres de colección/ramo son evidencia más estable que una frase corta.
        etiquetas = normalizar(" ".join(partes))
        if "python" in etiquetas:
            perfiles.add("python")
        if "docker" in etiquetas:
            perfiles.add("docker")
        if any(x in etiquetas for x in ["arquitectura", "hardware", "computadores"]):
            perfiles.add("hardware")
        if any(x in etiquetas for x in ["redes", "network"]):
            perfiles.add("redes")
        if any(x in etiquetas for x in ["ciberseguridad", "seguridad"]):
            perfiles.add("seguridad")
        if any(x in etiquetas for x in ["base de datos", "sql"]):
            perfiles.add("sql")
        if "linux" in etiquetas:
            perfiles.add("linux")
        return perfiles

    def _hay_cambio_dominio_contextual(self, pregunta, contexto, tipo_contexto=""):
        """Devuelve True solo ante un cambio de dominio suficientemente claro.

        Las continuaciones deícticas como ``dame un ejemplo`` no tienen un dominio
        propio y conservan el contexto. En cambio, una pregunta que activa un perfil
        nuevo y disjunto (Python -> hardware, Python -> Docker, etc.) vuelve al
        enrutador global para evitar el efecto de contexto pegajoso.
        """
        texto = self.corregir_seguimiento_academico_corto(pregunta) or pregunta
        texto = self.corregir_terminos_tecnicos_asr(texto)
        perfiles_nuevos = set(self._perfil_dominio_router(texto))
        if not perfiles_nuevos:
            return False
        perfiles_previos = self._perfiles_contexto_guardado(contexto, tipo_contexto)
        if not perfiles_previos:
            return False
        if perfiles_nuevos.isdisjoint(perfiles_previos):
            print(
                "CAMBIO DE TEMA DETECTADO: "
                f"contexto={sorted(perfiles_previos)} -> pregunta={sorted(perfiles_nuevos)}. "
                "Se vuelve al enrutador global."
            )
            return True
        return False

    def _terminos_codigo_clave(self, consulta):
        texto = normalizar(self.corregir_terminos_tecnicos_asr(consulta))
        tokens = set(texto.split())
        candidatos = {
            "return", "kwargs", "xargs", "elif", "def", "lambda", "yield",
            "import", "pip", "pylint", "pep8", "try", "except", "finally",
            "repl", "python3", "print", "valueerror",
        }
        encontrados = [t for t in candidatos if t in tokens]
        if re.search(r"\bpython\s+3\b", texto) and "python3" not in encontrados:
            encontrados.append("python3")
        if "value error" in texto and "valueerror" not in encontrados:
            encontrados.append("valueerror")
        return encontrados

    def _expandir_consulta_codigo(self, consulta):
        """Añade sinónimos pedagógicos solo para recuperar mejor el fragmento correcto."""
        claves = self._terminos_codigo_clave(consulta)
        extras = []
        mapa = {
            "return": "palabra clave return devolver valor resultado de una funcion",
            "kwargs": "kwargs argumentos nombrados diccionario argumentos de funcion",
            "xargs": "xargs argumentos variables multiples argumentos de funcion",
            "elif": "elif condicion if else control de flujo",
            "def": "def definir declarar funcion python",
            "lambda": "lambda funcion anonima expresion lambda",
            "yield": "yield generador devolver valores iteracion",
            "import": "import importar modulo paquete python",
            "pip": "pip instalar paquetes indice de paquetes python",
            "pylint": "pylint linter errores advertencias codigo python",
            "pep8": "pep8 guia de estilo formato codigo python",
            "try": "try excepciones manejo de errores",
            "except": "except excepciones manejo de errores",
            "finally": "finally excepciones bloque final",
            "repl": "REPL Read Eval Print Loop interprete interactivo Python terminal consola",
            "python3": "python3 terminal Python 3 REPL MacOS Linux",
            "print": "print mostrar imprimir salida pantalla consola Python",
            "valueerror": "ValueError conversion int cadena texto no numerico Python",
        }
        for clave in claves:
            extras.append(mapa.get(clave, clave))
        return (consulta + " " + " ".join(extras)).strip() if extras else consulta

    def _buscar_tecnico_lexico_local(
        self, claves, coleccion="", colecciones=None, limite=20
    ):
        """Recupera fragmentos técnicos que contienen literalmente keywords.

        Complementa al embedding cuando una sigla o token corto (REPL, python3,
        print, return...) no queda bien posicionado semánticamente. La consulta se
        hace solo sobre la SQLite local de Beta y respeta la colección técnica.
        """
        claves = [normalizar(x) for x in (claves or []) if normalizar(x)]
        if not claves:
            return []

        # LIKE se usa solo con tokens técnicos controlados internamente.
        where_tokens = " OR ".join("LOWER(f.texto) LIKE ?" for _ in claves)
        params = [f"%{x}%" for x in claves]
        sql = f"""
            SELECT
                f.id, f.pagina, f.orden, f.texto,
                d.id, d.nombre, d.ruta, d.ramo, d.modulo,
                COALESCE(d.categoria,'academica'),
                COALESCE(d.coleccion,'')
            FROM biblioteca_fragmentos f
            JOIN biblioteca_documentos d ON d.id=f.documento_id
            WHERE d.activo=1
              AND LOWER(TRIM(COALESCE(d.categoria,'academica')))='tecnica'
              AND ({where_tokens})
            ORDER BY f.id
            LIMIT ?
        """
        try:
            with self.biblioteca.conectar() as con:
                # Traemos más candidatos y luego ordenamos por relevancia REAL.
                filas = con.execute(sql, tuple(params + [max(240, int(limite) * 48)])).fetchall()
        except Exception as error:
            print("BÚSQUEDA TÉCNICA LÉXICA: no disponible:", error)
            return []

        coleccion_n = normalizar(coleccion or "")
        colecciones_n = [
            normalizar(x) for x in (colecciones or []) if normalizar(x)
        ]

        resultados = []
        for fila in filas:
            col = normalizar(fila[10] or "")
            if colecciones_n and not any(
                col == pref or col in pref or pref in col for pref in colecciones_n
            ):
                continue
            if coleccion_n and not colecciones_n:
                if not (col == coleccion_n or col in coleccion_n or coleccion_n in col):
                    continue

            contenido_n = normalizar(fila[3] or "")
            tokens = set(contenido_n.split())
            coincidencias = 0
            menciones = 0
            for clave in claves:
                ocurrencias = len(re.findall(r"\b" + re.escape(clave) + r"\b", contenido_n))
                if ocurrencias:
                    coincidencias += 1
                    menciones += ocurrencias
            if coincidencias <= 0:
                continue
            definicion_repl = bool(
                "repl" in claves and
                ("read eval print loop" in contenido_n or
                 "interprete interactivo" in contenido_n or
                 "interactivo" in contenido_n and menciones >= 2)
            )
            score_lexico = min(0.98, 0.58 + 0.14 * coincidencias
                               + min(0.10, 0.025 * max(0, menciones - 1))
                               + (0.06 if definicion_repl else 0.0))

            resultados.append({
                "fragmento_id": int(fila[0]),
                "pagina": int(fila[1]),
                "orden": int(fila[2]),
                "texto": fila[3] or "",
                "documento_id": int(fila[4]),
                "documento": fila[5] or "",
                "ruta": str(self.biblioteca.resolver_ruta_documento(
                    fila[6] or "", fila[7] or fila[10] or ""
                )),
                "ramo": fila[7] or "",
                "modulo": fila[8] or "",
                "categoria": (fila[9] or "tecnica").strip().lower(),
                "coleccion": fila[10] or "",
                "score": score_lexico,
                "score_semantico": 0.0,
                "coincidencia_lexica": coincidencias,
                "menciones_lexicas": menciones,
                "contiene_definicion_repl": definicion_repl,
                "origen_busqueda": "lexico_sqlite",
            })

        resultados.sort(
            key=lambda r: (
                int(r.get("coincidencia_lexica", 0)),
                bool(r.get("contiene_definicion_repl", False)),
                int(r.get("menciones_lexicas", 0)),
                float(r.get("score", 0)),
            ),
            reverse=True,
        )
        return resultados[:max(1, int(limite))]

    def buscar_tecnico_hibrido(
        self, consulta, limite=TECNICA_RESULTADOS, coleccion="", colecciones=None
    ):
        """Búsqueda semántica con refuerzo léxico para palabras clave de código.

        El texto original sigue siendo la pregunta que recibe Qwen. La expansión
        solo se usa para recuperar mejores fragmentos del libro. Cuando una palabra
        clave exacta aparece en un fragmento, recibe un pequeño bonus de ranking.
        """
        consulta_corregida = self.corregir_terminos_tecnicos_asr(consulta)
        consulta_busqueda = self._expandir_consulta_codigo(consulta_corregida)
        claves = self._terminos_codigo_clave(consulta_corregida)

        # v2.9.9: si el modelo semántico aún está frío y la consulta contiene
        # un token técnico inequívoco (REPL, return, python3, etc.), intentamos
        # primero SQLite. Esto permite responder desde libros locales sin forzar
        # una carga de SentenceTransformer de decenas de segundos en plena charla.
        if claves and self.biblioteca.modelo_embeddings is None:
            lexicos_tempranos = self._buscar_tecnico_lexico_local(
                claves,
                coleccion=coleccion,
                colecciones=colecciones,
                limite=max(int(limite), 5),
            )
            fuertes = [
                r for r in lexicos_tempranos
                if int(r.get("coincidencia_lexica", 0) or 0) >= 1
                and float(r.get("score", 0) or 0) >= 0.70
            ]
            if fuertes:
                print(
                    "BÚSQUEDA TÉCNICA HÍBRIDA v2.9.9: ruta léxica temprana "
                    f"claves={claves} resultados={len(fuertes)}"
                )
                return fuertes[:max(1, int(limite))]

        limite_amplio = max(int(limite) * 4, 16) if claves else int(limite)
        resultados = self.biblioteca.buscar(
            consulta_busqueda,
            limite=limite_amplio,
            categoria_preferida="tecnica",
            coleccion_preferida=coleccion if not colecciones else "",
            colecciones_preferidas=colecciones or None,
        )
        if not claves:
            return resultados[:limite]

        # v2.9.6: siglas/tokens cortos pueden perderse en el ranking semántico.
        # Complementamos con coincidencias literales de la SQLite local y fusionamos
        # por fragmento_id. Así "REPL" recupera las páginas que realmente dicen REPL.
        lexicos = self._buscar_tecnico_lexico_local(
            claves,
            coleccion=coleccion,
            colecciones=colecciones,
            limite=max(int(limite) * 3, 12),
        )

        combinados = {}
        for r in list(resultados) + list(lexicos):
            item = dict(r)
            fid = int(item.get("fragmento_id", 0) or 0)
            if not fid:
                continue
            previo = combinados.get(fid)
            if previo is None:
                combinados[fid] = item
            else:
                # Conservamos el score semántico si existía y el texto/metadatos
                # del resultado léxico si son más completos.
                sem_prev = float(previo.get("score_semantico", previo.get("score", 0)) or 0)
                sem_new = float(item.get("score_semantico", item.get("score", 0)) or 0)
                if sem_new > sem_prev:
                    base = item
                    otro = previo
                else:
                    base = previo
                    otro = item
                for k, v in otro.items():
                    if k not in base or base.get(k) in (None, ""):
                        base[k] = v
                combinados[fid] = base

        reordenados = []
        for item0 in combinados.values():
            item = dict(item0)
            sem = float(item.get("score_semantico", item.get("score", 0)) or 0)
            contenido = normalizar(
                " ".join([
                    str(item.get("texto") or ""),
                    str(item.get("documento") or ""),
                    str(item.get("modulo") or ""),
                ])
            )
            tokens_contenido = set(contenido.split())
            coincidencias = sum(
                1 for clave in claves
                if clave in tokens_contenido or clave in contenido
            )
            # Una coincidencia literal controlada pesa mucho para siglas como REPL,
            # pero el score semántico sigue desempatatando entre varios fragmentos.
            bonus = min(0.34, 0.18 * coincidencias)
            item["score_semantico"] = sem
            item["score"] = min(1.0, max(float(item.get("score", 0) or 0), sem + bonus))
            item["coincidencia_lexica"] = max(
                int(item.get("coincidencia_lexica", 0) or 0),
                coincidencias,
            )
            reordenados.append(item)

        reordenados.sort(
            key=lambda r: (
                int(r.get("coincidencia_lexica", 0) or 0),
                float(r.get("score", 0) or 0),
                float(r.get("score_semantico", 0) or 0),
            ),
            reverse=True,
        )
        if reordenados and claves:
            origen = reordenados[0].get("origen_busqueda", "semantico")
            print(
                "BÚSQUEDA TÉCNICA HÍBRIDA v2.9.6: "
                f"claves={claves} consulta='{consulta_busqueda}' "
                f"mejor_score={float(reordenados[0].get('score',0)):.3f} "
                f"origen={origen}"
            )
        return reordenados[:limite]

    def formatear_fuentes_tecnicas(self, resultados, maximo=4):
        bloques = []
        for i, r in enumerate(resultados[:maximo], 1):
            encabezado = (
                f"[LIBRO {i}] Colección: {r.get('coleccion') or 'General'} | "
                f"PDF: {r.get('documento','')} | página {r.get('pagina','')}"
            )
            texto = (r.get("texto") or "").strip()
            limite = 560 if maximo > 3 else 420
            if len(texto) > limite:
                texto = texto[:limite].rsplit(" ", 1)[0] + "..."
            bloques.append(encabezado + "\nTexto: " + texto)
        return "\n\n".join(bloques)

    def es_seguimiento_tecnico(self, pregunta):
        if self.ultimo_tipo_respuesta_terminada != "tecnico":
            return False
        if not self.ultimo_contexto_tecnico:
            return False
        if time.time() - self.ultimo_contexto_tecnico_ts > TECNICA_CONTEXTO_SEGUNDOS:
            return False
        if self._hay_cambio_dominio_contextual(
            pregunta, self.ultimo_contexto_tecnico, "tecnico"
        ):
            return False

        texto = self.corregir_seguimiento_academico_corto(pregunta)
        palabras = texto.split()
        marcadores = [
            "explicame mas", "dime mas", "cuentame mas", "profundiza",
            "profundice", "amplia", "detalla", "continua", "sigue",
            "dame un ejemplo", "ponme un ejemplo", "hazme un ejemplo",
            "otro ejemplo", "dame otro", "que significa eso", "por que",
            "como funciona eso", "cual es la diferencia", "resumelo",
            "la primera", "la segunda", "la tercera", "el primero", "el segundo",
            "el tercero", "hazme un ejercicio", "dame un ejercicio",
            "muestrame el codigo", "explicame el codigo", "paso a paso",
        ]
        if any(m in texto for m in marcadores):
            return True
        if self.ultimo_tipo_respuesta_terminada == "tecnico" and len(palabras) <= 9:
            if palabras and palabras[0] in {
                "que", "cual", "cuales", "como", "por", "explica", "explicame",
                "dime", "muestra", "muestrame", "hazme", "dame",
            }:
                return True
        return False

    def consultar_biblioteca_tecnica_async(
        self, pregunta, forzar=False, profunda_forzada=None, tokens_forzados=None
    ):
        consulta = self.limpiar_consulta_tecnica(pregunta)
        if not consulta:
            self.responder("necesito saber qué tema técnico desea revisar.", "confundida")
            return

        profunda = (
            bool(profunda_forzada)
            if profunda_forzada is not None
            else self.es_pedido_academico_profundo(pregunta)
        )
        fuentes_max = TECNICA_FUENTES_PROFUNDO if profunda else TECNICA_FUENTES_BREVE
        tokens_max = (
            int(tokens_forzados)
            if tokens_forzados is not None
            else (TECNICA_TOKENS_PROFUNDO if profunda else TECNICA_TOKENS_BREVE)
        )
        num_ctx = TECNICA_NUM_CTX_PROFUNDO if profunda else TECNICA_NUM_CTX_BREVE
        colecciones = self.inferir_colecciones_tecnicas(consulta)
        coleccion = colecciones[0] if colecciones else ""

        token = self.iniciar_proceso("biblioteca_tecnica")
        if token is None:
            self.responder("todavía estoy terminando la consulta anterior.", "pensando")
            return
        self.expresion_pensando()

        def trabajo():
            respuesta = None
            uso_streaming = False
            locales_utiles = []
            error = ""
            try:
                inicio = time.perf_counter()
                locales = self.buscar_tecnico_hibrido(
                    consulta,
                    limite=TECNICA_RESULTADOS,
                    coleccion=coleccion if len(colecciones) <= 1 else "",
                    colecciones=colecciones if len(colecciones) > 1 else None,
                )
                print(
                    f"LATENCIA BIBLIOTECA TÉCNICA: "
                    f"{time.perf_counter() - inicio:.2f} s"
                )
                locales_utiles = [
                    r for r in locales
                    if float(r.get("score", 0)) >= TECNICA_UMBRAL_MIN
                ]
                top_score = float(locales[0].get("score", 0)) if locales else 0.0

                if not locales_utiles:
                    # No inventamos que el libro cubre algo que no recuperamos.
                    respuesta = (
                        "Señor, no encontré ese tema con suficiente claridad en mi "
                        "biblioteca técnica local. Puedo explicárselo con mi conocimiento "
                        "general o buscar información actual si usted me lo pide."
                    )
                else:
                    contexto = self.formatear_fuentes_tecnicas(
                        locales_utiles, fuentes_max
                    )
                    estilo = self.preferencias_aprendidas_para_prompt()
                    instrucciones = (
                        "Eres Beta, tutora técnica personal del Señor. "
                        "Responde en español de forma clara, práctica y pedagógica. "
                        "Usa LIBROS TÉCNICOS LOCALES como fuente principal y no inventes "
                        "contenido ausente. Puedes reorganizar y explicar con tus propias "
                        "palabras. NO menciones el nombre del PDF, libro, autor, número de "
                        "página ni la palabra fuente, salvo que el Señor lo pregunte. "
                        "No uses Internet. Si el libro contiene una afirmación ligada a una versión, año o sistema operativo, "
                        "preséntala como lo que indica el material, sin convertirla en una afirmación universal actual. "
                        "Dato histórico para evitar errores: el soporte de Python 2 terminó en 2020; "
                        "Python 3 NO terminó en 2020. No asumas que macOS/Linux traen Python 2 "
                        "de forma predeterminada actualmente: depende del equipo y la configuración. "
                        "No inventes atajos de teclado ni comandos que no aparezcan en los fragmentos recuperados. "
                        "Si la pregunta pide cómo hacer algo, explica "
                        "el procedimiento directamente. Si el tema es programación, cuando sea "
                        "útil incluye un ejemplo de código corto y correcto seguido de una explicación. "
                        "No fuerces ejemplos Python en temas de redes, seguridad u otras colecciones. "
                        "Evita asteriscos y formato que suene extraño al leerlo en voz. "
                        + (
                            "Modo profundo: desarrolla el tema en unas 150 a 200 palabras. "
                            if profunda else
                            "Modo normal: explica en unas 60 a 100 palabras, priorizando lo práctico. "
                        )
                        + "Termina siempre una oración completa."
                        + (
                            f" Adapta discretamente el estilo a estas preferencias confirmadas: "
                            f"{estilo[:220]}."
                            if estilo else ""
                        )
                    )
                    contenido = (
                        f"Pregunta del Señor: {consulta}\n\n"
                        f"LIBROS TÉCNICOS LOCALES RECUPERADOS:\n{contexto}\n\n"
                        "Enseña el concepto directamente. Las referencias son internas."
                    )
                    mensajes = [
                        {"role": "system", "content": instrucciones},
                        {"role": "user", "content": contenido},
                    ]
                    if STREAMING_OLLAMA_ACTIVO:
                        respuesta = self.generar_y_hablar_ollama_streaming(
                            mensajes,
                            "tecnico",
                            token,
                            temperatura=0.10,
                            num_predict=tokens_max,
                            num_ctx=num_ctx,
                        )
                        uso_streaming = bool(respuesta)
                    else:
                        respuesta = self.enviar_ollama(
                            mensajes,
                            temperatura=0.10,
                            num_predict=tokens_max,
                            num_ctx=num_ctx,
                        )
                        if respuesta:
                            respuesta = self.limpiar_respuesta_ollama(respuesta)

                self.ultimas_fuentes_tecnicas = locales_utiles[:fuentes_max]
                self.ultimo_contexto_academico_ts = 0.0
                self.ultimo_contexto_tecnico = {
                    "tema_base": consulta,
                    "coleccion": coleccion,
                    "colecciones": colecciones,
                    "consulta": consulta,
                    "locales": locales_utiles[:fuentes_max],
                    "respuesta": respuesta or "",
                }
                self.ultimo_contexto_tecnico_ts = time.time()

                print(
                    f"BIBLIOTECA TÉCNICA: consulta='{consulta}' "
                    f"colecciones='{', '.join(colecciones) if colecciones else 'todas'}' "
                    f"top_score={top_score:.3f} locales={len(locales_utiles)}"
                )
                for i, r in enumerate(locales_utiles[:5], 1):
                    print(
                        f"  LIBRO {i}: {r.get('documento')} pág. {r.get('pagina')} "
                        f"score={r.get('score',0):.3f}"
                    )
            except Exception as exc:
                error = str(exc)
                print("ERROR BIBLIOTECA TÉCNICA:", exc)
            finally:
                self.terminar_proceso(token)

            if token != self.proceso_id:
                return
            if respuesta and not uso_streaming:
                self.root.after(
                    0,
                    lambda r=respuesta: self.responder(
                        r, "hablando", "tecnico"
                    ),
                )
            elif not respuesta:
                self.root.after(
                    0,
                    lambda: self.responder(
                        "no pude consultar la biblioteca técnica en este momento.",
                        "confundida",
                    ),
                )

        threading.Thread(target=trabajo, daemon=True).start()

    def conversar_contexto_tecnico_async(self, pregunta):
        contexto = self.ultimo_contexto_tecnico
        if not contexto:
            self.consultar_biblioteca_tecnica_async(pregunta, forzar=True)
            return

        interpretada = self.corregir_seguimiento_academico_corto(pregunta) or pregunta
        interpretada = self.corregir_terminos_tecnicos_asr(interpretada)
        profunda = self.es_pedido_academico_profundo(interpretada)
        fuentes_max = TECNICA_FUENTES_PROFUNDO if profunda else TECNICA_FUENTES_BREVE
        tokens_max = TECNICA_TOKENS_PROFUNDO if profunda else TECNICA_TOKENS_BREVE
        num_ctx = TECNICA_NUM_CTX_PROFUNDO if profunda else TECNICA_NUM_CTX_BREVE
        tema_base = (contexto.get("tema_base") or contexto.get("consulta") or "").strip()
        coleccion = (contexto.get("coleccion") or "").strip()
        colecciones = [c for c in (contexto.get("colecciones") or []) if c]
        consulta_expandida = f"{tema_base} {interpretada}".strip()

        token = self.iniciar_proceso("contexto_tecnico")
        if token is None:
            self.responder("todavía estoy terminando la respuesta anterior.", "pensando")
            return
        self.expresion_pensando()

        def trabajo():
            respuesta = None
            uso_streaming = False
            try:
                inicio = time.perf_counter()
                # La recuperación prioriza la pregunta actual. El tema base sirve
                # como contexto secundario, no como término dominante de búsqueda.
                consulta_recuperacion = (
                    f"{interpretada}. Contexto relacionado: {tema_base}"
                    if tema_base else interpretada
                )
                nuevos = self.buscar_tecnico_hibrido(
                    consulta_recuperacion,
                    limite=TECNICA_RESULTADOS,
                    coleccion=coleccion if len(colecciones) <= 1 else "",
                    colecciones=colecciones if len(colecciones) > 1 else None,
                )
                print(
                    f"LATENCIA BIBLIOTECA TÉCNICA SEGUIMIENTO: "
                    f"{time.perf_counter() - inicio:.2f} s"
                )
                utiles = [
                    r for r in nuevos
                    if float(r.get("score", 0)) >= TECNICA_UMBRAL_MIN
                ]
                fuentes = utiles[:fuentes_max] or (contexto.get("locales") or [])[:fuentes_max]
                contexto_libros = self.formatear_fuentes_tecnicas(fuentes, fuentes_max)

                instrucciones = (
                    "Eres Beta, tutora técnica personal. Responde PRINCIPALMENTE al "
                    "seguimiento actual del Señor usando los LIBROS TÉCNICOS LOCALES recuperados. "
                    "El tema anterior es contexto secundario: no vuelvas a definirlo salvo que sea "
                    "imprescindible para responder. Si el seguimiento nombra una palabra clave, "
                    "función u operador concreto (por ejemplo return), céntrate en esa pieza, su "
                    "sintaxis y su uso. Responde en español, de manera práctica. No menciones PDF, "
                    "libro, autor, páginas ni fuentes salvo que el Señor lo solicite. No inventes "
                    "sintaxis que no esté respaldada por el material local. Si pide un ejemplo o "
                    "código, entrégalo y explícalo con claridad. No uses Internet. Termina siempre "
                    "la última oración."
                )
                contenido = (
                    f"Tema base: {tema_base}\n"
                    f"Seguimiento del Señor: {interpretada}\n\n"
                    f"LIBROS TÉCNICOS LOCALES RECUPERADOS:\n{contexto_libros}"
                )
                mensajes = [
                    {"role": "system", "content": instrucciones},
                    {"role": "user", "content": contenido},
                ]
                if STREAMING_OLLAMA_ACTIVO:
                    respuesta = self.generar_y_hablar_ollama_streaming(
                        mensajes, "tecnico", token,
                        temperatura=0.10, num_predict=tokens_max, num_ctx=num_ctx,
                    )
                    uso_streaming = bool(respuesta)
                else:
                    respuesta = self.enviar_ollama(
                        mensajes, temperatura=0.10,
                        num_predict=tokens_max, num_ctx=num_ctx,
                    )
                    if respuesta:
                        respuesta = self.limpiar_respuesta_ollama(respuesta)

                self.ultimas_fuentes_tecnicas = fuentes
                self.ultimo_contexto_tecnico = {
                    "tema_base": tema_base,
                    "coleccion": coleccion,
                    "colecciones": colecciones,
                    "consulta": interpretada,
                    "locales": fuentes,
                    "respuesta": respuesta or "",
                }
                self.ultimo_contexto_tecnico_ts = time.time()
                top = float(nuevos[0].get("score", 0)) if nuevos else 0.0
                print(
                    f"BIBLIOTECA TÉCNICA SEGUIMIENTO: coleccion='{coleccion or 'todas'}' "
                    f"tema='{tema_base}' pregunta='{interpretada}' "
                    f"top_score={top:.3f} locales={len(utiles)}"
                )
            except Exception as error:
                print("ERROR SEGUIMIENTO TÉCNICO:", error)
            finally:
                self.terminar_proceso(token)

            if token != self.proceso_id:
                return
            if respuesta and not uso_streaming:
                self.root.after(
                    0,
                    lambda r=respuesta: self.responder(r, "hablando", "tecnico"),
                )
            elif not respuesta:
                self.root.after(
                    0,
                    lambda: self.responder(
                        "no pude continuar esa explicación técnica.", "confundida"
                    ),
                )

        threading.Thread(target=trabajo, daemon=True).start()

    def manejar_comando_fuentes_tecnicas(self, texto):
        texto_n = normalizar(texto)
        marcadores_especificos = [
            "muestrame las fuentes tecnicas", "muestra las fuentes tecnicas",
            "ver fuentes tecnicas", "de que libro sacaste eso",
            "de cual libro sacaste eso", "en que pagina del libro",
        ]
        generico = "de donde sacaste eso" in texto_n
        if not any(m in texto_n for m in marcadores_especificos) and not (
            generico and self.ultimo_tipo_respuesta_terminada == "tecnico"
        ):
            return False

        if not self.ultimas_fuentes_tecnicas:
            self.responder(
                "todavía no tengo referencias técnicas de una consulta reciente.",
                "confundida",
            )
            return True

        self.root.after(0, self.ventana_fuentes_tecnicas)
        self.responder(
            "le muestro el libro y las páginas que utilicé como referencia interna.",
            "feliz",
        )
        return True

    def ventana_fuentes_tecnicas(self):
        if not self.ultimas_fuentes_tecnicas:
            messagebox.showinfo(
                "Fuentes técnicas",
                "Beta todavía no tiene fuentes técnicas de una consulta reciente.",
                parent=self.root,
            )
            return

        ventana = tk.Toplevel(self.root)
        ventana.title("Referencias técnicas utilizadas por Beta")
        ventana.geometry("980x470")
        ventana.attributes("-topmost", True)

        tabla = ttk.Treeview(
            ventana,
            columns=("n", "coleccion", "documento", "pagina", "relevancia", "ruta"),
            show="headings",
        )
        for clave, titulo in [
            ("n", "#"), ("coleccion", "Colección"), ("documento", "PDF"),
            ("pagina", "Página"), ("relevancia", "Relevancia"), ("ruta", "Ruta"),
        ]:
            tabla.heading(clave, text=titulo)
        tabla.column("n", width=35, anchor="center")
        tabla.column("coleccion", width=130)
        tabla.column("documento", width=300)
        tabla.column("pagina", width=70, anchor="center")
        tabla.column("relevancia", width=90, anchor="center")
        tabla.column("ruta", width=300)
        tabla.pack(fill="both", expand=True, padx=12, pady=12)

        for i, r in enumerate(self.ultimas_fuentes_tecnicas, 1):
            tabla.insert(
                "", "end",
                values=(
                    i, r.get("coleccion") or "General",
                    r.get("documento") or "", r.get("pagina") or "",
                    f"{float(r.get('score',0)):.3f}", r.get("ruta") or "",
                ),
            )

        def abrir(_event=None):
            seleccion = tabla.selection()
            if not seleccion:
                return
            ruta = str(tabla.item(seleccion[0])["values"][5])
            try:
                os.startfile(ruta)
            except Exception:
                pass

        tabla.bind("<Double-1>", abrir)
        ttk.Button(ventana, text="Abrir PDF", command=abrir).pack(pady=(0, 12))

    def limpiar_consulta_academica(self, pregunta):
        texto = (pregunta or "").strip()
        texto = re.sub(
            r"^\s*(?:beta|veta|meta|metas|petra)[,\s:;-]*",
            "",
            texto,
            flags=re.IGNORECASE,
        )
        patrones = [
            r"^\s*busca\s+en\s+mis\s+apuntes\s+",
            r"^\s*busca\s+en\s+la\s+biblioteca\s+",
            r"^\s*que\s+dicen\s+mis\s+apuntes\s+(?:sobre\s+)?",
            r"^\s*segun\s+mis\s+apuntes[,\s]+",
            r"^\s*segun\s+mi\s+material[,\s]+",
        ]
        for patron in patrones:
            texto_nuevo = re.sub(patron, "", texto, flags=re.IGNORECASE)
            if texto_nuevo != texto:
                texto = texto_nuevo.strip()
                break
        return texto.strip(" ,.;:-") or pregunta

    def parece_consulta_academica(self, pregunta):
        texto = normalizar(pregunta)

        # Órdenes explícitas de navegación/investigación se respetan antes de RAG.
        if any(
            marca in texto
            for marca in [
                "youtube", "google chrome", "busca en google", "busca en internet",
                "investiga en internet", "investiga sobre", "ultimas noticias",
                "noticias de", "abre chrome",
            ]
        ):
            return False

        explicita = any(
            marca in texto
            for marca in [
                "mis apuntes", "mi material", "biblioteca academica",
                "biblioteca de beta", "segun el modulo", "segun mis modulos",
            ]
        )
        if explicita:
            return True

        if not self.biblioteca.tiene_contenido():
            return False

        palabras_academicas = {
            "programacion", "python", "java", "poo", "objeto", "objetos", "clase",
            "clases", "herencia", "polimorfismo", "encapsulamiento", "abstraccion",
            "algoritmo", "algoritmos", "sql", "base", "datos", "redes", "subred",
            "subnetting", "ip", "servidor", "servidores", "ciberseguridad",
            "seguridad", "perifericos", "arquitectura", "computadores", "computador",
            "procesador", "memoria", "hardware", "software", "sistema", "operativo",
            "centro", "computo", "iot", "internet", "cosas", "firewall", "vlan",
            "tcp", "udp", "dns", "dhcp", "virtualizacion", "backup", "respaldo",
            "confidencialidad", "integridad", "disponibilidad", "amenaza",
            "vulnerabilidad", "riesgo", "criptografia", "autenticacion",
        }

        tokens = set(texto.split())
        if tokens & palabras_academicas:
            return True

        metadatos = self.biblioteca.palabras_metadatos()
        if len(tokens & metadatos) >= 1:
            return True

        return False

    def formatear_fuentes_academicas(self, resultados, maximo=4):
        bloques = []
        for i, r in enumerate(resultados[:maximo], 1):
            encabezado = (
                f"[APUNTE {i}] Ramo: {r.get('ramo') or 'Sin ramo'} | "
                f"Módulo: {r.get('modulo') or 'Sin módulo'} | "
                f"PDF: {r.get('documento','')} | página {r.get('pagina','')}"
            )
            texto = (r.get("texto") or "").strip()
            limite_texto = 360 if maximo <= ACADEMICO_FUENTES_BREVE else 560
            if len(texto) > limite_texto:
                texto = texto[:limite_texto].rsplit(" ", 1)[0] + "..."
            bloques.append(encabezado + "\nTexto: " + texto)
        return "\n\n".join(bloques)

    def limpiar_wake_academico(self, pregunta):
        """Quita alias de activación para analizar una continuación académica corta."""
        texto = normalizar(pregunta)
        palabras = texto.split()
        activaciones = {"beta", "veta", "meta", "metas", "petra"}
        # Whisper/Vosk puede dejar el alias al principio de la frase.
        while palabras and palabras[0] in activaciones:
            palabras.pop(0)
        return " ".join(palabras).strip()

    def corregir_seguimiento_academico_corto(self, pregunta):
        """Corrige solo órdenes académicas cortas con errores obvios de ASR.

        No pretende corregir dictado libre. Se activa únicamente cuando existe
        contexto académico y la frase es breve. Así evitamos transformar palabras
        normales del Señor por coincidencias accidentales.
        """
        texto = self.limpiar_wake_academico(pregunta)
        palabras = texto.split()
        if not palabras or len(palabras) > 10:
            return texto

        objetivos = {
            "profundiza": 0.72,
            "profundice": 0.76,
            "amplia": 0.76,
            "detalla": 0.76,
            "continua": 0.77,
            "resume": 0.78,
        }

        corregidas = []
        cambios = []
        for palabra in palabras:
            mejor = palabra
            mejor_score = 0.0
            mejor_objetivo = None
            if len(palabra) >= 5:
                for objetivo, umbral in objetivos.items():
                    score = difflib.SequenceMatcher(None, palabra, objetivo).ratio()
                    if score >= umbral and score > mejor_score:
                        mejor_score = score
                        mejor_objetivo = objetivo
            if mejor_objetivo and mejor_objetivo != palabra:
                mejor = mejor_objetivo
                cambios.append(f"{palabra}->{mejor_objetivo} ({mejor_score:.2f})")
            corregidas.append(mejor)

        corregido = " ".join(corregidas).strip()
        if cambios:
            print("SEGUIMIENTO ACADÉMICO: corrección ASR:", ", ".join(cambios))
            print(f"SEGUIMIENTO ACADÉMICO: interpretando '{texto}' como '{corregido}'")
        return corregido

    def es_pedido_academico_profundo(self, pregunta):
        texto = self.corregir_seguimiento_academico_corto(pregunta)
        marcadores = [
            "profundiza", "profundice", "mas a fondo", "en profundidad",
            "en detalle", "detalladamente", "explicacion completa",
            "explicame completo", "explicamelo completo", "desarrolla el tema",
            "desarrollame", "amplia la explicacion", "amplia el tema",
            "amplia", "detalla", "respuesta larga", "todos los detalles",
            "paso a paso completo",
        ]
        return any(m in texto for m in marcadores)

    def es_seguimiento_academico(self, pregunta):
        if not self.ultimo_contexto_academico:
            return False
        if time.time() - self.ultimo_contexto_academico_ts > BIBLIOTECA_CONTEXTO_SEGUNDOS:
            return False
        if self._hay_cambio_dominio_contextual(
            pregunta, self.ultimo_contexto_academico, "academico"
        ):
            return False

        texto = self.corregir_seguimiento_academico_corto(pregunta)
        marcadores = [
            "explicame mas", "dime mas", "cuentame mas", "profundiza",
            "profundice", "amplia", "detalla", "continua", "sigue",
            "dame un ejemplo", "ponme un ejemplo", "hazme un ejemplo",
            "otro ejemplo", "dame otro", "que significa eso", "por que",
            "como funciona eso", "y eso", "y despues", "cual es la diferencia",
            "puedes explicarlo mejor", "resumelo", "resume", "hazme un resumen",
            "preguntame sobre eso", "cuales son las tres", "cuales son los tres",
            "cuales son esas tres", "cuales son esas partes", "menciona las tres",
            "las tres partes", "los tres elementos", "esas partes", "esos elementos",
            "la primera", "la segunda", "la tercera", "el primero", "el segundo",
            "el tercero", "a que se refiere", "que quiere decir",
        ]
        if any(m in texto for m in marcadores):
            return True

        palabras = texto.split()
        referencias = {
            "eso", "esa", "ese", "esas", "esos", "esto", "estas", "estos",
            "primera", "segunda", "tercera", "primero", "segundo", "tercero",
            "partes", "elementos", "caracteristicas", "pasos", "tipos",
            "ejemplo", "ejemplos", "diferencia", "diferencias",
        }
        if len(palabras) <= 11 and referencias.intersection(palabras):
            return True

        # Si Daniela acaba de terminar una respuesta académica, aceptamos también
        # interrogaciones de continuación muy cortas. Las rutas de clima, Windows,
        # YouTube, memoria, etc. se evalúan antes de llegar aquí, por lo que esas
        # órdenes explícitas conservan prioridad.
        if self.ultimo_tipo_respuesta_terminada == "academico" and len(palabras) <= 8:
            inicios = {
                "que", "cual", "cuales", "como", "cuando", "donde", "por",
                "explica", "explicame", "dime", "menciona", "describe",
            }
            if palabras and palabras[0] in inicios:
                return True

        return False

    def consultar_biblioteca_async(
        self,
        pregunta,
        forzar=False,
        forzar_solo_local=False,
        decision=None,
    ):
        consulta = self.limpiar_consulta_academica(pregunta)
        if not consulta:
            self.responder("necesito saber qué desea consultar en sus apuntes.", "confundida")
            return

        respuesta_profunda = self.es_pedido_academico_profundo(pregunta)
        limite_fuentes_respuesta = (
            ACADEMICO_FUENTES_PROFUNDO if respuesta_profunda else ACADEMICO_FUENTES_BREVE
        )
        max_tokens_respuesta = (
            ACADEMICO_TOKENS_PROFUNDO if respuesta_profunda else ACADEMICO_TOKENS_BREVE
        )

        token = self.iniciar_proceso("biblioteca_academica")
        if token is None:
            self.responder("todavía estoy terminando la consulta anterior.", "pensando")
            return

        self.expresion_pensando()

        def trabajo():
            respuesta = None
            uso_streaming = False
            locales = []
            web = []
            error = ""
            try:
                inicio = time.perf_counter()
                # v2.8.3: una ruta académica solo puede recuperar documentos
                # clasificados como académicos. Si el router ya identificó un
                # ramo, lo usamos también como preferencia para evitar que un
                # libro técnico con una mención incidental contamine el prompt.
                ramo_decision = (decision or {}).get("ramo", "") if decision else ""
                locales = self.biblioteca.buscar(
                    consulta,
                    limite=BIBLIOTECA_RESULTADOS,
                    ramo_preferido=ramo_decision,
                    categoria_preferida="academica",
                )
                print(
                    f"LATENCIA BIBLIOTECA: {time.perf_counter() - inicio:.2f} s"
                )
                if decision:
                    print(
                        "FUENTES ACADÉMICAS ESTRICTAS: "
                        f"categoria='academica' ramo='{ramo_decision or 'todos'}'"
                    )

                locales_utiles = [
                    r for r in locales if float(r.get("score", 0)) >= BIBLIOTECA_UMBRAL_MIN
                ]
                top_score = float(locales[0].get("score", 0)) if locales else 0.0
                local_fuerte = (
                    top_score >= BIBLIOTECA_UMBRAL_FUERTE
                    or len([r for r in locales if r.get("score", 0) >= 0.33]) >= 2
                )

                texto_n = normalizar(pregunta)
                pide_web = any(
                    m in texto_n
                    for m in [
                        "complementa con internet", "complementalo con internet",
                        "ademas busca en internet", "tambien busca en internet",
                    ]
                )
                pide_solo_local = forzar_solo_local or any(
                    m in texto_n
                    for m in [
                        "solo mis apuntes", "solo en mis apuntes",
                        "sin internet", "no uses internet",
                    ]
                )

                modo = "solo_local" if pide_solo_local else self.modo_biblioteca_academica

                # v2.8.3: si el enrutador inteligente ya encontró evidencia
                # académica alta (o media respaldada por varios fragmentos
                # locales), no salimos a Internet automáticamente. Una petición
                # explícita como "complementa con Internet" siempre conserva
                # prioridad. Las consultas manuales sin decisión del router
                # mantienen la configuración histórica de la biblioteca.
                decision_ruta = (decision or {}).get("ruta", "") if decision else ""
                decision_confianza = (decision or {}).get("confianza", "") if decision else ""
                try:
                    decision_score_a = float((decision or {}).get("score_academica", 0) or 0)
                except Exception:
                    decision_score_a = 0.0

                evidencia_local_suficiente = bool(
                    decision_ruta == "academica"
                    and (
                        decision_confianza == "alta"
                        or (decision_confianza == "media" and local_fuerte)
                    )
                    and decision_score_a > 0
                )

                if pide_solo_local:
                    usar_web = False
                elif pide_web:
                    usar_web = True
                elif evidencia_local_suficiente:
                    usar_web = False
                    print(
                        "INTERNET ACADÉMICO: omitido por evidencia local suficiente "
                        f"(confianza={decision_confianza}, scoreA={decision_score_a:.3f})."
                    )
                else:
                    usar_web = (
                        modo == "siempre"
                        or (modo == "si_falta" and not local_fuerte)
                    )

                if usar_web:
                    try:
                        inicio_web = time.perf_counter()
                        web = self.buscar_internet_ddgs(consulta)[:3]
                        print(
                            f"LATENCIA COMPLEMENTO WEB ACADÉMICO: "
                            f"{time.perf_counter() - inicio_web:.2f} s"
                        )
                    except Exception as web_error:
                        print("BIBLIOTECA: complemento web no disponible:", web_error)

                if not locales_utiles and not web:
                    respuesta = (
                        "Señor, no encontré información suficientemente relacionada "
                        "en sus apuntes"
                    )
                    if modo != "solo_local":
                        respuesta += " ni pude obtener un complemento útil de Internet"
                    respuesta += "."
                else:
                    contexto_local = self.formatear_fuentes_academicas(locales_utiles, limite_fuentes_respuesta)
                    contexto_web = self.formatear_resultados_web(web[:3]) if web else ""

                    estilo_aprendido = self.preferencias_aprendidas_para_prompt()
                    instrucciones = (
                        "Eres Beta, tutora académica del Señor. Responde solo en español y para voz. "
                        "Prioriza APUNTES LOCALES; no inventes ni atribuyas a los apuntes datos ausentes. "
                        "Si usas Internet, di claramente que es complemento externo. "
                        "Corrige solo errores OCR obvios y parafrasea texto dañado. "
                        "Sin Markdown, tablas, asteriscos, URLs ni razonamiento interno. "
                        + (
                            "Modo profundo: explica de forma pedagógica en unas 130 a 170 palabras. "
                            if respuesta_profunda
                            else "Modo breve: responde directamente en 1 a 3 frases y unas 40 a 55 palabras. "
                        )
                        + "Empieza por la respuesta útil. Termina siempre una oración completa; "
                          "no abras una idea nueva si no podrás cerrarla dentro del límite. "
                          "Puedes dar ejemplos propios, identificándolos como ejemplos."
                        + (f" Adapta discretamente el estilo a estas preferencias confirmadas: {estilo_aprendido[:220]}." if estilo_aprendido else "")
                    )

                    contenido = (
                        f"Pregunta del Señor: {consulta}\n\n"
                        f"APUNTES LOCALES RECUPERADOS:\n"
                        f"{contexto_local or 'No hubo fragmentos locales suficientemente relevantes.'}\n\n"
                    )
                    if contexto_web:
                        contenido += (
                            "COMPLEMENTO EXTERNO DE INTERNET:\n"
                            + contexto_web
                            + "\n\n"
                        )
                    contenido += (
                        "Responde ahora. Si aporta valor, menciona solo un PDF y una página principal."
                    )

                    mensajes_academicos = [
                        {"role": "system", "content": instrucciones},
                        {"role": "user", "content": contenido},
                    ]
                    if STREAMING_OLLAMA_ACTIVO:
                        respuesta = self.generar_y_hablar_ollama_streaming(
                            mensajes_academicos,
                            "academico",
                            token,
                            temperatura=0.12,
                            num_predict=max_tokens_respuesta,
                            num_ctx=(ACADEMICO_NUM_CTX_PROFUNDO if respuesta_profunda else ACADEMICO_NUM_CTX_BREVE),
                        )
                        uso_streaming = bool(respuesta)
                    else:
                        respuesta = self.enviar_ollama(
                            mensajes_academicos,
                            temperatura=0.12,
                            num_predict=max_tokens_respuesta,
                            num_ctx=(ACADEMICO_NUM_CTX_PROFUNDO if respuesta_profunda else ACADEMICO_NUM_CTX_BREVE),
                        )
                        if respuesta:
                            respuesta = self.limpiar_respuesta_ollama(respuesta)

                self.ultimas_fuentes_academicas = locales_utiles[:limite_fuentes_respuesta]
                self.ultimo_contexto_tecnico_ts = 0.0
                if web:
                    self.ultimas_fuentes_web = web
                ramo_base = ((decision or {}).get("ramo") or "").strip() if decision else ""
                if not ramo_base and locales_utiles:
                    ramo_base = (locales_utiles[0].get("ramo") or "").strip()
                self.ultimo_contexto_academico = {
                    # tema_base no se concatena indefinidamente: sirve como ancla
                    # para cada pregunta de seguimiento y evita deriva semántica.
                    "tema_base": consulta,
                    "ramo_base": ramo_base,
                    "consulta": consulta,
                    "ultima_consulta": consulta,
                    "locales": locales_utiles[:limite_fuentes_respuesta],
                    "web": web[:3],
                    "respuesta": respuesta or "",
                }
                self.ultimo_contexto_academico_ts = time.time()
                if ramo_base or consulta:
                    self.registrar_exposicion_academica(
                        ramo_base or "General",
                        self.inferir_tema_academico(consulta, ramo_base),
                        "Consulta académica basada en apuntes",
                    )

                print(
                    "MODO TUTOR ACADÉMICO:",
                    "PROFUNDO" if respuesta_profunda else "BREVE",
                )
                print(
                    f"BIBLIOTECA ACADÉMICA ESTRICTA: consulta='{consulta}' "
                    f"ramo='{ramo_base or 'todos'}' top_score={top_score:.3f} "
                    f"locales={len(locales_utiles)} web={len(web)}"
                )
                for i, r in enumerate(locales_utiles[:5], 1):
                    print(
                        f"  APUNTE {i}: {r.get('documento')} pág. {r.get('pagina')} "
                        f"score={r.get('score',0):.3f}"
                    )

            except Exception as exc:
                error = str(exc)
                print("ERROR BIBLIOTECA ACADÉMICA:", exc)
            finally:
                self.terminar_proceso(token)

            if token != self.proceso_id:
                return

            if respuesta and not uso_streaming:
                self.root.after(0, lambda r=respuesta: self.responder(r, "hablando", "academico"))
            elif not respuesta:
                if "pip install" in error:
                    mensaje = (
                        "para estudiar sus PDF me faltan componentes locales. "
                        "Instale PyMuPDF, Sentence Transformers y NumPy y vuelva a intentarlo."
                    )
                else:
                    mensaje = "no pude consultar la biblioteca académica en este momento."
                self.root.after(0, lambda m=mensaje: self.responder(m, "confundida"))

        threading.Thread(target=trabajo, daemon=True).start()

    def conversar_contexto_academico_async(self, pregunta):
        contexto = self.ultimo_contexto_academico
        if not contexto:
            self.consultar_biblioteca_async(pregunta, forzar=True)
            return

        # Normalizamos únicamente comandos cortos de seguimiento. Por ejemplo,
        # si Whisper entrega "perfumdiza", Beta lo interpreta como "profundiza"
        # y mantiene la consulta dentro de los apuntes locales.
        pregunta_interpretada = self.corregir_seguimiento_academico_corto(pregunta)
        if not pregunta_interpretada:
            pregunta_interpretada = pregunta

        respuesta_profunda = self.es_pedido_academico_profundo(pregunta_interpretada)
        limite_fuentes = (
            ACADEMICO_FUENTES_PROFUNDO if respuesta_profunda else ACADEMICO_FUENTES_BREVE
        )
        max_tokens = (
            ACADEMICO_TOKENS_PROFUNDO if respuesta_profunda else ACADEMICO_TOKENS_BREVE
        )

        token = self.iniciar_proceso("contexto_academico")
        if token is None:
            self.responder("todavía estoy terminando la respuesta anterior.", "pensando")
            return

        self.expresion_pensando()

        def trabajo():
            respuesta = None
            uso_streaming = False
            try:
                # v2.5.4: TODA continuación académica vuelve a consultar la biblioteca.
                # Usamos un tema base estable + la pregunta actual, en vez de concatenar
                # todas las preguntas anteriores; así evitamos deriva semántica.
                tema_base = (
                    contexto.get("tema_base")
                    or contexto.get("consulta")
                    or ""
                ).strip()
                consulta_expandida = f"{tema_base} {pregunta_interpretada}".strip()
                ramo_base = (contexto.get("ramo_base") or "").strip()
                inicio_busqueda = time.perf_counter()
                nuevos = self.biblioteca.buscar(
                    consulta_expandida,
                    limite=BIBLIOTECA_RESULTADOS,
                    ramo_preferido=ramo_base,
                    categoria_preferida="academica",
                )
                print(
                    f"LATENCIA BIBLIOTECA SEGUIMIENTO: "
                    f"{time.perf_counter() - inicio_busqueda:.2f} s"
                )
                nuevos_utiles = [
                    r for r in nuevos
                    if float(r.get("score", 0)) >= BIBLIOTECA_UMBRAL_MIN
                ]
                top_seguimiento = float(nuevos[0].get("score", 0)) if nuevos else 0.0
                print(
                    f"BIBLIOTECA SEGUIMIENTO: ramo='{ramo_base or 'todos'}' "
                    f"tema='{tema_base}' pregunta='{pregunta_interpretada}' "
                    f"top_score={top_seguimiento:.3f} locales={len(nuevos_utiles)}"
                )
                for i, r in enumerate(nuevos_utiles[:3], 1):
                    print(
                        f"  SEGUIMIENTO {i}: {r.get('documento')} pág. {r.get('pagina')} "
                        f"score={r.get('score',0):.3f}"
                    )

                locales = nuevos_utiles[:limite_fuentes] or (contexto.get("locales") or [])[:limite_fuentes]
                web = contexto.get("web") or []
                fuentes_locales = self.formatear_fuentes_academicas(locales, limite_fuentes)
                fuentes_web = self.formatear_resultados_web(web[:3]) if web else ""

                estilo_aprendido = self.preferencias_aprendidas_para_prompt()
                instrucciones = (
                    "Eres Beta, tutora académica del Señor. Continúa el tema usando primero los "
                    "APUNTES RECUPERADOS PARA ESTA PREGUNTA. No inventes ni extrapoles como si fuera "
                    "contenido institucional. Responde solo en español y para voz, sin Markdown. "
                    "Corrige solo OCR obvio. "
                    + (
                        "Modo profundo: desarrolla en unas 130 a 170 palabras. "
                        if respuesta_profunda
                        else "Modo breve: responde en 1 a 3 frases y unas 40 a 55 palabras. "
                    )
                    + "Termina siempre una oración completa y no abras una idea que no puedas cerrar."
                    + (f" Adapta discretamente el estilo a estas preferencias confirmadas: {estilo_aprendido[:220]}." if estilo_aprendido else "")
                )

                mensajes = [
                    {"role": "system", "content": instrucciones},
                    {
                        "role": "user",
                        "content": (
                            f"Tema base: {tema_base}\n"
                            f"Respuesta anterior (contexto breve): {contexto.get('respuesta','')[:420]}\n\n"
                            f"APUNTES RECUPERADOS PARA ESTA PREGUNTA:\n{fuentes_locales}\n\n"
                            f"INTERNET (solo si ya existía como complemento):\n{fuentes_web}\n\n"
                            f"Pregunta de seguimiento interpretada: {pregunta_interpretada}"
                        ),
                    },
                ]
                if STREAMING_OLLAMA_ACTIVO:
                    respuesta = self.generar_y_hablar_ollama_streaming(
                        mensajes,
                        "academico",
                        token,
                        temperatura=0.12,
                        num_predict=max_tokens,
                        num_ctx=(ACADEMICO_NUM_CTX_PROFUNDO if respuesta_profunda else ACADEMICO_NUM_CTX_BREVE),
                    )
                    uso_streaming = bool(respuesta)
                else:
                    respuesta = self.enviar_ollama(
                        mensajes,
                        temperatura=0.12,
                        num_predict=max_tokens,
                        num_ctx=(ACADEMICO_NUM_CTX_PROFUNDO if respuesta_profunda else ACADEMICO_NUM_CTX_BREVE),
                    )
                    if respuesta:
                        respuesta = self.limpiar_respuesta_ollama(respuesta)
                if respuesta:
                    contexto["respuesta"] = respuesta
                    contexto["locales"] = locales
                    contexto["tema_base"] = tema_base
                    contexto["ramo_base"] = ramo_base or (
                        (locales[0].get("ramo") or "").strip() if locales else ""
                    )
                    contexto["ultima_consulta"] = consulta_expandida
                    # consulta conserva el tema base para compatibilidad con el resto de Beta.
                    contexto["consulta"] = tema_base
                    self.ultimo_contexto_academico_ts = time.time()
                    self.ultimas_fuentes_academicas = locales
                    ramo_progreso = contexto.get("ramo_base") or ramo_base or "General"
                    tema_progreso = self.inferir_tema_academico(pregunta_interpretada, ramo_progreso)
                    if normalizar(tema_progreso) in {"profundiza", "profundice", "dame un ejemplo", "ejemplo"}:
                        tema_progreso = self.inferir_tema_academico(tema_base, ramo_progreso)
                    self.registrar_exposicion_academica(
                        ramo_progreso, tema_progreso, "Seguimiento académico basado en apuntes"
                    )
            except Exception as error:
                print("ERROR CONTEXTO ACADÉMICO:", error)
            finally:
                self.terminar_proceso(token)

            if token != self.proceso_id:
                return
            if respuesta and not uso_streaming:
                self.root.after(0, lambda r=respuesta: self.responder(r, "hablando", "academico"))
            elif not respuesta:
                self.root.after(
                    0,
                    lambda: self.responder(
                        "no pude continuar esa explicación académica.", "confundida"
                    ),
                )

        threading.Thread(target=trabajo, daemon=True).start()

    def manejar_comando_fuentes_academicas(self, texto):
        texto = normalizar(texto)
        if (
            "de donde sacaste eso" in texto
            and self.ultimo_tipo_respuesta_terminada == "tecnico"
        ):
            return False
        marcadores = [
            "muestrame las fuentes academicas",
            "muestra las fuentes academicas",
            "ver fuentes academicas",
            "fuentes de mis apuntes",
            "de que apunte sacaste eso",
            "de donde sacaste eso",
        ]
        if not any(m in texto for m in marcadores):
            return False

        if not self.ultimas_fuentes_academicas:
            self.responder(
                "todavía no tengo fuentes académicas de una consulta reciente.",
                "confundida",
            )
            return True

        self.root.after(0, self.ventana_fuentes_academicas)
        self.responder(
            "le muestro los documentos y páginas que utilicé.",
            "feliz",
        )
        return True

    def ventana_fuentes_academicas(self):
        if not self.ultimas_fuentes_academicas:
            messagebox.showinfo(
                "Fuentes académicas",
                "Beta todavía no tiene fuentes académicas de una consulta reciente.",
                parent=self.root,
            )
            return

        ventana = tk.Toplevel(self.root)
        ventana.title("Fuentes académicas utilizadas por Beta")
        ventana.geometry("1050x500")
        ventana.attributes("-topmost", True)

        ttk.Label(
            ventana,
            text=(
                "Estas son las páginas de sus PDF que Beta recuperó para la última respuesta. "
                "Doble clic para abrir el documento."
            ),
            wraplength=990,
        ).pack(anchor="w", padx=12, pady=(12, 8))

        tabla = ttk.Treeview(
            ventana,
            columns=("n", "ramo", "modulo", "documento", "pagina", "relevancia", "ruta"),
            show="headings",
        )
        for clave, titulo in [
            ("n", "#"),
            ("ramo", "Ramo"),
            ("modulo", "Módulo"),
            ("documento", "PDF"),
            ("pagina", "Página"),
            ("relevancia", "Relevancia"),
            ("ruta", "Ruta"),
        ]:
            tabla.heading(clave, text=titulo)

        tabla.column("n", width=35, anchor="center")
        tabla.column("ramo", width=180)
        tabla.column("modulo", width=110)
        tabla.column("documento", width=300)
        tabla.column("pagina", width=65, anchor="center")
        tabla.column("relevancia", width=85, anchor="center")
        tabla.column("ruta", width=250)
        tabla.pack(fill="both", expand=True, padx=12, pady=(0, 10))

        for i, r in enumerate(self.ultimas_fuentes_academicas, 1):
            tabla.insert(
                "",
                "end",
                values=(
                    i,
                    r.get("ramo", ""),
                    r.get("modulo", ""),
                    r.get("documento", ""),
                    r.get("pagina", ""),
                    f"{r.get('score',0):.3f}",
                    r.get("ruta", ""),
                ),
            )

        def abrir(_event=None):
            seleccion = tabla.selection()
            if not seleccion:
                return
            valores = tabla.item(seleccion[0]).get("values", [])
            if len(valores) >= 7:
                ruta = str(valores[6])
                if Path(ruta).exists():
                    try:
                        os.startfile(ruta)
                    except Exception as error:
                        messagebox.showerror(
                            "Fuentes académicas",
                            f"No pude abrir el PDF:\n{error}",
                            parent=ventana,
                        )

        tabla.bind("<Double-1>", abrir)
        ttk.Button(
            ventana,
            text="Abrir PDF seleccionado",
            command=abrir,
        ).pack(pady=(0, 12))

    def enviar_ollama(
        self, mensajes, temperatura=0.18, num_predict=240, num_ctx=None, formato_json=False,
        timeout=None,
    ):
        datos = {
            "model": OLLAMA_MODEL,
            "messages": mensajes,
            "stream": False,
            "options": {
                "temperature": temperatura,
                "top_p": 0.80,
                "repeat_penalty": 1.08,
                "num_predict": num_predict,
                "num_ctx": int(num_ctx or OLLAMA_NUM_CTX),
            },
            "keep_alive": OLLAMA_KEEP_ALIVE,
        }
        if formato_json:
            # Ollama fuerza una salida JSON válida sin cambiar el comportamiento de
            # las demás consultas de Beta, porque esta opción se usa solo cuando se pide.
            datos["format"] = "json"

        def hacer_peticion(payload):
            cuerpo = json.dumps(payload, ensure_ascii=False).encode("utf-8")
            solicitud = urllib.request.Request(
                OLLAMA_URL,
                data=cuerpo,
                headers={"Content-Type": "application/json; charset=utf-8"},
                method="POST",
            )

            with urllib.request.urlopen(
                solicitud, timeout=float(timeout or OLLAMA_TIMEOUT)
            ) as respuesta_http:
                contenido = respuesta_http.read().decode("utf-8")

            resultado = json.loads(contenido)

            # Solo usamos el contenido final devuelto por el modelo Instruct.
            mensaje = resultado.get("message", {})
            return mensaje.get("content", "").strip()

        try:
            return hacer_peticion(datos)

        except urllib.error.HTTPError as error:
            print("ERROR HTTP OLLAMA:", error)
            try:
                detalle = error.read().decode("utf-8", errors="replace")
                if detalle:
                    print("DETALLE OLLAMA:", detalle)
            except Exception:
                pass
            return None

        except urllib.error.URLError as error:
            print("ERROR CON OLLAMA:", error)
            return None

        except Exception as error:
            print("ERROR CONSULTANDO OLLAMA:", error)
            return None

    def extraer_fragmentos_streaming(self, buffer, forzar=False):
        """Separa texto incremental en frases naturales para la voz.

        El objetivo no es trocear cada token, sino entregar a Daniela unidades
        suficientemente largas para sonar fluidas y suficientemente cortas para
        empezar a hablar antes de que Qwen termine toda la respuesta.
        """
        texto = (buffer or "").replace("\r", " ")
        listos = []

        while texto.strip():
            corte = None
            for coincidencia in re.finditer(r'(?<=[.!?])(?:["”»])?\s+', texto):
                candidato = texto[:coincidencia.end()].strip()
                if len(candidato) >= STREAMING_MIN_CARACTERES_FRASE:
                    corte = coincidencia.end()
                    break

            # En versiones anteriores permitíamos cortar en comas para ganar algunos
            # segundos. Eso podía dejar la última locución suspendida si Qwen agotaba
            # el límite después de ese corte. v2.5.3 prioriza frases completas.
            if (
                STREAMING_CORTE_INTERMEDIO
                and corte is None
                and len(texto) >= STREAMING_CORTE_LARGO
            ):
                limite = min(len(texto), STREAMING_CORTE_LARGO)
                zona = texto[:limite]
                candidatos = [zona.rfind(", "), zona.rfind("; "), zona.rfind(": ")]
                pos = max(candidatos)
                if pos >= 90:
                    corte = pos + 1

            if corte is None:
                break

            fragmento = texto[:corte].strip()
            texto = texto[corte:].lstrip()
            if fragmento:
                listos.append(fragmento)

        if forzar and texto.strip():
            listos.append(texto.strip())
            texto = ""

        return listos, texto

    def enviar_ollama_streaming(
        self,
        mensajes,
        temperatura=0.16,
        num_predict=180,
        on_fragment=None,
        token_proceso=None,
        num_ctx=None,
    ):
        """Consulta Ollama por NDJSON y entrega frases a medida que se generan."""
        datos = {
            "model": OLLAMA_MODEL,
            "messages": mensajes,
            "stream": True,
            "options": {
                "temperature": temperatura,
                "top_p": 0.80,
                "repeat_penalty": 1.08,
                "num_predict": num_predict,
                "num_ctx": int(num_ctx or OLLAMA_NUM_CTX),
            },
            "keep_alive": OLLAMA_KEEP_ALIVE,
        }

        cuerpo = json.dumps(datos, ensure_ascii=False).encode("utf-8")
        solicitud = urllib.request.Request(
            OLLAMA_URL,
            data=cuerpo,
            headers={"Content-Type": "application/json; charset=utf-8"},
            method="POST",
        )

        texto_total = ""
        buffer = ""
        inicio = time.perf_counter()
        primer_token = False

        try:
            with urllib.request.urlopen(solicitud, timeout=OLLAMA_TIMEOUT) as respuesta_http:
                for linea in respuesta_http:
                    if token_proceso is not None and token_proceso != self.proceso_id:
                        print("STREAMING OLLAMA: respuesta cancelada por cambio de proceso.")
                        return None

                    linea = linea.decode("utf-8", errors="replace").strip()
                    if not linea:
                        continue

                    try:
                        evento = json.loads(linea)
                    except json.JSONDecodeError:
                        continue

                    pieza = ((evento.get("message") or {}).get("content") or "")
                    if pieza:
                        if not primer_token:
                            primer_token = True
                            print(
                                f"LATENCIA OLLAMA HASTA PRIMER TOKEN: "
                                f"{time.perf_counter() - inicio:.2f} s"
                            )
                        texto_total += pieza
                        buffer += pieza
                        fragmentos, buffer = self.extraer_fragmentos_streaming(buffer)
                        if on_fragment:
                            for fragmento in fragmentos:
                                on_fragment(fragmento)

                    if evento.get("done"):
                        break

            # Cierre seguro: emitimos únicamente oraciones completas. Si Qwen alcanza
            # num_predict a mitad de una idea, la cola incompleta NO se manda a Daniela.
            fragmentos, resto = self.extraer_fragmentos_streaming(buffer, forzar=False)
            if on_fragment:
                for fragmento in fragmentos:
                    on_fragment(fragmento)

            resto = (resto or "").strip()
            if resto:
                if re.search(r'[.!?][\"”»]?\s*$', resto):
                    if on_fragment:
                        on_fragment(resto)
                elif STREAMING_DESCARTAR_COLA_INCOMPLETA:
                    print(
                        "CIERRE STREAMING SEGURO: cola incompleta descartada para no "
                        f"cortar una oración ({len(resto)} caracteres)."
                    )
                else:
                    if on_fragment:
                        on_fragment(resto.rstrip(" ,;:") + ".")

            print(f"LATENCIA OLLAMA GENERACIÓN COMPLETA: {time.perf_counter() - inicio:.2f} s")
            return texto_total.strip()

        except urllib.error.HTTPError as error:
            print("ERROR HTTP OLLAMA STREAMING:", error)
            try:
                detalle = error.read().decode("utf-8", errors="replace")
                if detalle:
                    print("DETALLE OLLAMA STREAMING:", detalle)
            except Exception:
                pass
            return None
        except urllib.error.URLError as error:
            print("ERROR CON OLLAMA STREAMING:", error)
            return None
        except Exception as error:
            print("ERROR CONSULTANDO OLLAMA STREAMING:", error)
            return None

    def generar_wav_daniela_streaming(self, texto):
        """Sintetiza un fragmento sin reproducirlo todavía.

        En streaming, un hilo puede preparar el siguiente WAV mientras otro hilo
        reproduce el anterior. Así se reducen las pausas entre frases.
        """
        texto_voz = self.preparar_texto_para_voz(texto)
        if not texto_voz or not PIPER_MODELO.exists():
            return None, texto_voz

        ruta_wav = None
        try:
            fd, nombre_wav = tempfile.mkstemp(prefix="beta_stream_", suffix=".wav")
            os.close(fd)
            ruta_wav = Path(nombre_wav)

            if self.piper_listo and self.piper_voice is not None:
                inicio = time.perf_counter()
                with self.piper_lock:
                    with wave.open(str(ruta_wav), "wb") as wav_file:
                        self.piper_voice.synthesize_wav(texto_voz, wav_file)
                print(
                    f"LATENCIA PIPER STREAM (síntesis): "
                    f"{time.perf_counter() - inicio:.2f} s"
                )
            else:
                inicio = time.perf_counter()
                comando = [
                    sys.executable, "-m", "piper",
                    "-m", str(PIPER_MODELO),
                    "-f", str(ruta_wav),
                    "--", texto_voz,
                ]
                resultado = subprocess.run(
                    comando,
                    capture_output=True,
                    text=True,
                    encoding="utf-8",
                    errors="replace",
                    creationflags=subprocess.CREATE_NO_WINDOW,
                    check=False,
                )
                print(
                    f"LATENCIA PIPER STREAM (CLI): "
                    f"{time.perf_counter() - inicio:.2f} s"
                )
                if resultado.returncode != 0:
                    if resultado.stderr.strip():
                        print("ERROR PIPER STREAM:", resultado.stderr.strip())
                    ruta_wav.unlink(missing_ok=True)
                    return None, texto_voz

            if not ruta_wav.exists() or ruta_wav.stat().st_size < 100:
                ruta_wav.unlink(missing_ok=True)
                return None, texto_voz

            return ruta_wav, texto_voz
        except Exception as error:
            print("ERROR SINTETIZANDO PIPER STREAM:", error)
            if ruta_wav is not None:
                try:
                    ruta_wav.unlink(missing_ok=True)
                except Exception:
                    pass
            return None, texto_voz

    def reproducir_wav_daniela_streaming(self, ruta_wav, texto_respaldo=""):
        """Reproduce un WAV ya sintetizado y sincroniza la boca."""
        if ruta_wav is None:
            if texto_respaldo:
                self.reproducir_voz_windows_respaldo(texto_respaldo)
                return True
            return False

        try:
            intervalo_ms = 45
            niveles = self.analizar_wav_para_boca(ruta_wav, intervalo_ms)
            evento_visual_listo = threading.Event()
            try:
                self.root.after(
                    0,
                    lambda: self.preparar_sincronizacion_boca(
                        niveles,
                        intervalo_ms,
                        evento_visual_listo,
                    ),
                )
                evento_visual_listo.wait(timeout=0.40)
            except Exception:
                pass

            winsound.PlaySound(None, winsound.SND_PURGE)
            winsound.PlaySound(str(ruta_wav), winsound.SND_FILENAME)
            try:
                self.root.after(0, self.detener_sincronizacion_boca)
            except Exception:
                pass
            return True
        except Exception as error:
            print("ERROR REPRODUCIENDO WAV STREAM:", error)
            if texto_respaldo:
                self.reproducir_voz_windows_respaldo(texto_respaldo)
                return True
            return False
        finally:
            try:
                ruta_wav.unlink(missing_ok=True)
            except Exception:
                pass

    def iniciar_pipeline_respuesta_streaming(self, tipo_contexto="general", expresion_final="hablando"):
        """Crea el pipeline Qwen -> Piper -> audio para una sola respuesta."""
        self.respuesta_actual_id += 1
        respuesta_id = self.respuesta_actual_id
        self.respuesta_tipo_por_id[respuesta_id] = tipo_contexto or "general"

        sesion = {
            "id": respuesta_id,
            "tipo": tipo_contexto or "general",
            "expresion_final": expresion_final,
            "cola_texto": queue.Queue(),
            "cola_wav": queue.Queue(),
            "partes": [],
            "primer_fragmento": True,
            "texto_final": "",
            "cancelar_finalizacion": False,
            "inicio_peticion": self.ultima_frase_inicio or time.perf_counter(),
        }

        # Mientras Qwen todavía genera la primera frase, el micrófono sigue activo
        # para que el Señor pueda decir "Beta, deja de pensar" y cancelar.
        # self.hablando pasa a True justo cuando empieza el primer audio.
        try:
            self.root.after(0, lambda: self.cambiar_expresion("pensando"))
        except Exception:
            pass

        def sintetizador():
            while True:
                fragmento = sesion["cola_texto"].get()
                if fragmento is None:
                    break
                ruta, texto_voz = self.generar_wav_daniela_streaming(fragmento)
                sesion["cola_wav"].put((ruta, texto_voz))
            sesion["cola_wav"].put(None)

        def reproductor():
            primer_audio = True
            while True:
                item = sesion["cola_wav"].get()
                if item is None:
                    break
                ruta, texto_voz = item
                if primer_audio:
                    primer_audio = False
                    self.hablando = True
                    self.activar_mirada_frontal_voz()
                    inicio_peticion = sesion.get("inicio_peticion")
                    if inicio_peticion:
                        print(
                            f"LATENCIA HASTA PRIMER AUDIO: "
                            f"{time.perf_counter() - inicio_peticion:.2f} s"
                        )
                self.reproducir_wav_daniela_streaming(ruta, texto_voz)

            self.hablando = False
            self.desactivar_mirada_frontal_voz()
            if sesion["cancelar_finalizacion"]:
                return

            texto_final = (sesion.get("texto_final") or " ".join(sesion["partes"])).strip()
            if texto_final:
                try:
                    self.root.after(
                        0,
                        lambda t=texto_final, sid=respuesta_id, exp=expresion_final: self.finalizar_respuesta_streaming(
                            t, sid, exp
                        ),
                    )
                except tk.TclError:
                    pass

        threading.Thread(target=sintetizador, daemon=True).start()
        threading.Thread(target=reproductor, daemon=True).start()
        return sesion

    def _sanear_afirmaciones_python_oral(self, fragmento, tipo_contexto=""):
        """Barrera mínima frente a dos errores históricos observados en Qwen.

        Solo interviene en fragmentos técnicos sobre Python; la intervención
        queda registrada en consola. No reescribe respuestas académicas de otras
        disciplinas ni convierte contenidos antiguos en hechos actuales.
        """
        frase = (fragmento or "").strip()
        if (tipo_contexto or "") != "tecnico":
            return frase
        n = normalizar(frase)
        python3 = bool(re.search(r"\b(?:python3|python 3|version 3)\b", n))
        if (python3 and "2020" in n
                and re.search(r"\b(?:mantenida|mantenido|termino|finalizo|soporte|"
                              r"dejo|abandonada|descontinuada)\b", n)
                and not re.search(r"\b(?:python2|python 2|version 2)\b", n)):
            print("CONTROL HISTÓRICO v2.9.13: corregida referencia errónea Python 3/2020.")
            return (
                "Python 3 continúa vigente. La fecha de 2020 corresponde al "
                "fin del soporte oficial de Python 2."
            )
        if (re.search(r"\b(?:macos|linux)\b", n)
                and re.search(r"\b(?:python2|python 2|version 2)\b", n)
                and re.search(r"\b(?:por defecto|predeterminada|preinstalada|"
                              r"viene instalada|esta instalada)\b", n)):
            print("CONTROL HISTÓRICO v2.9.13: eliminada generalización macOS/Linux Python 2.")
            return (
                "La versión de Python disponible depende del sistema y de cómo "
                "esté configurado. Conviene comprobar el intérprete instalado "
                "antes de ejecutar los ejemplos."
            )
        if (
            re.search(r"\b(?:siempre|obligatoriamente)\b.{0,45}\b(?:usar|usa|debes usar|utilizar)\b", n)
            and (python3 or "python" in n or len(n.split()) <= 10)
        ):
            print("CONTROL HISTÓRICO v2.9.13: eliminada recomendación absoluta de comando Python.")
            return (
                "Use el comando que corresponda al intérprete de Python 3 instalado "
                "en su sistema, por ejemplo python o python3 según la configuración."
            )
        return frase

    def encolar_fragmento_streaming(self, sesion, fragmento):
        fragmento = self.limpiar_respuesta_ollama((fragmento or "").strip())
        fragmento = self._sanear_afirmaciones_python_oral(
            fragmento, sesion.get("tipo", "")
        )
        if not fragmento:
            return

        if sesion.get("primer_fragmento"):
            sesion["primer_fragmento"] = False
            n = normalizar(fragmento)
            primeras = " ".join(n.split()[:6])
            if "senor" not in primeras:
                fragmento = (
                    "Señor, " + fragmento[0].lower() + fragmento[1:]
                    if len(fragmento) > 1
                    else "Señor, " + fragmento
                )
            inicio_peticion = sesion.get("inicio_peticion")
            if inicio_peticion:
                print(
                    f"LATENCIA HASTA PRIMERA FRASE LISTA: "
                    f"{time.perf_counter() - inicio_peticion:.2f} s"
                )

        sesion["partes"].append(fragmento)
        self._aula_mostrar_texto_async(
            fragmento, sesion.get("tipo", "general"), desde_streaming=True
        )
        sesion["cola_texto"].put(fragmento)

    def cerrar_pipeline_respuesta_streaming(self, sesion, cancelar=False):
        sesion["cancelar_finalizacion"] = bool(cancelar)
        sesion["texto_final"] = " ".join(sesion.get("partes") or []).strip()
        inicio_peticion = sesion.get("inicio_peticion")
        if inicio_peticion:
            print(
                f"LATENCIA HASTA GENERACIÓN COMPLETA: "
                f"{time.perf_counter() - inicio_peticion:.2f} s"
            )
        # Una vez terminada la generación bloqueamos el micrófono mientras Piper
        # termina de preparar/reproducir los fragmentos pendientes.
        if not cancelar and sesion.get("partes"):
            self.hablando = True
        self.ultima_frase_inicio = 0.0
        sesion["cola_texto"].put(None)

    def finalizar_respuesta_streaming(self, texto, respuesta_id, expresion_final):
        """Guarda y cierra una respuesta que ya fue pronunciada por el pipeline."""
        texto = (texto or "").strip()
        if not texto:
            return

        print("RESPUESTA FINAL DE BETA [STREAMING]:", texto)
        # v3.2.1: recuperar el contexto ANTES de finalizar_respuesta(), que lo elimina
        # del mapa. v3.1.2 referenciaba una variable inexistente y podía lanzar NameError.
        tipo_contexto = self.respuesta_tipo_por_id.get(respuesta_id, "general")
        # El chat de proyectos se persiste en su propio manifiesto.
        # No se mezcla con memoria inteligente ni resúmenes globales de Beta.
        if tipo_contexto != "proyecto":
            self.memoria.guardar_conversacion("Beta", texto)
            self.ultima_respuesta_beta = texto
            self.actualizar_contexto_turno("Beta", texto)
            self.programar_memoria_inteligente(self.ultimo_mensaje_usuario, texto)

        if "?" in texto and self.modo_escucha == "conversacion":
            self.renovar_modo_conversacion()

        self.finalizar_respuesta(respuesta_id, expresion_final)

    def generar_y_hablar_ollama_streaming(
        self,
        mensajes,
        tipo_contexto,
        token_proceso,
        temperatura,
        num_predict,
        num_ctx=None,
    ):
        """Genera y habla en paralelo. Devuelve el texto completo ya encolado."""
        sesion = self.iniciar_pipeline_respuesta_streaming(tipo_contexto, "hablando")
        respuesta = self.enviar_ollama_streaming(
            mensajes,
            temperatura=temperatura,
            num_predict=num_predict,
            on_fragment=lambda frag: self.encolar_fragmento_streaming(sesion, frag),
            token_proceso=token_proceso,
            num_ctx=num_ctx,
        )

        if not respuesta or not sesion.get("partes"):
            self.cerrar_pipeline_respuesta_streaming(sesion, cancelar=True)
            return None

        self.cerrar_pipeline_respuesta_streaming(sesion, cancelar=False)
        return sesion.get("texto_final") or " ".join(sesion.get("partes") or [])

    def calentar_ollama_en_segundo_plano(self):
        """Carga Qwen en memoria antes de la primera conversación real."""
        def trabajo():
            inicio = time.perf_counter()
            try:
                datos = {
                    "model": OLLAMA_MODEL,
                    "messages": [
                        {"role": "system", "content": "Responde solo en español."},
                        {"role": "user", "content": "Responde únicamente: listo"},
                    ],
                    "stream": False,
                    "options": {"temperature": 0, "num_predict": 4, "num_ctx": ACADEMICO_NUM_CTX_BREVE},
                    "keep_alive": OLLAMA_KEEP_ALIVE,
                }
                cuerpo = json.dumps(datos, ensure_ascii=False).encode("utf-8")
                solicitud = urllib.request.Request(
                    OLLAMA_URL, data=cuerpo,
                    headers={"Content-Type": "application/json; charset=utf-8"},
                    method="POST",
                )
                with urllib.request.urlopen(solicitud, timeout=30) as respuesta_http:
                    respuesta_http.read()
                print(f"OLLAMA PRECALENTADO en {time.perf_counter() - inicio:.2f} s")
            except Exception as error:
                print("OLLAMA: no se pudo precalentar (no es fatal):", error)

        threading.Thread(target=trabajo, daemon=True).start()

    def limpiar_respuesta_ollama(self, texto):
        if not texto:
            return ""

        # Eliminar bloques de pensamiento etiquetados.
        texto = re.sub(
            r"<think>.*?</think>",
            "",
            texto,
            flags=re.DOTALL | re.IGNORECASE,
        )
        texto = re.sub(
            r"<analysis>.*?</analysis>",
            "",
            texto,
            flags=re.DOTALL | re.IGNORECASE,
        )
        texto = texto.replace("<think>", "").replace("</think>", "")
        texto = texto.replace("<analysis>", "").replace("</analysis>", "")

        lineas = [linea.strip() for linea in texto.splitlines() if linea.strip()]
        filtradas = []

        prefijos_internos = (
            "we need",
            "the user",
            "i need",
            "i should",
            "let me",
            "thinking",
            "analysis:",
            "reasoning:",
            "assistant should",
            "the answer",
            "final answer:",
            "response:",
        )

        for linea in lineas:
            linea_minuscula = linea.lower()
            if any(linea_minuscula.startswith(p) for p in prefijos_internos):
                continue
            filtradas.append(linea)

        texto = "\n".join(filtradas)
        texto = re.sub(r"\n{3,}", "\n\n", texto)
        texto = texto.strip().strip('"')

        return texto

    def puntuar_idioma(self, texto):
        """Devuelve (puntos_espanol, puntos_ingles) usando palabras funcionales."""
        texto_normal = normalizar(texto)
        palabras = texto_normal.split()

        palabras_espanol = {
            "el", "la", "los", "las", "un", "una", "unos", "unas", "de", "del",
            "que", "y", "o", "en", "con", "sin", "por", "para", "como", "porque",
            "es", "son", "soy", "eres", "esta", "estas", "estoy", "hay", "tiene",
            "puede", "puedo", "podemos", "ser", "si", "no", "pero", "tambien", "muy",
            "mas", "menos", "cuando", "donde", "quien", "cual", "su", "sus", "mi",
            "mis", "tu", "tus", "le", "lo", "se", "me", "te", "ya", "hoy", "jefe", "señor", "senor",
            "bien", "gracias", "claro", "creo", "recuerdo", "respuesta", "ayudar", "hacer",
            "esto", "eso", "este", "esta", "aqui", "algo", "todo", "cada", "desde",
        }

        palabras_ingles = {
            "the", "and", "you", "your", "are", "is", "was", "were", "this", "that",
            "with", "from", "have", "has", "had", "can", "could", "would", "should",
            "will", "what", "when", "where", "why", "how", "about", "because", "but",
            "not", "for", "into", "let", "think", "thinking", "answer", "response", "user",
            "assistant", "need", "needs", "make", "sure", "always", "only", "spanish",
            "english", "provide", "given", "context", "memory", "memories", "system", "prompt",
            "message", "reply", "final", "here", "there", "some", "more", "also", "then",
            "now", "dont", "doesnt", "did", "do", "does", "it", "its", "we", "they",
            "them", "our", "of", "to", "in", "on", "at", "as", "be", "been", "being",
            "if", "or", "so", "just", "really", "know", "want", "like", "good", "hello",
            "thanks", "please", "tell", "remember", "today", "computer", "local", "model",
        }

        puntos_es = sum(1 for p in palabras if p in palabras_espanol)
        puntos_en = sum(1 for p in palabras if p in palabras_ingles)

        frases_ingles = (
            "the user",
            "let me",
            "we need",
            "i need",
            "i think",
            "in english",
            "final answer",
            "the answer",
            "you can",
            "i can",
            "here is",
            "here are",
        )

        for frase in frases_ingles:
            if frase in texto_normal:
                puntos_en += 4

        return puntos_es, puntos_en

    def respuesta_tiene_demasiado_ingles(self, texto):
        if not texto:
            return False

        puntos_es, puntos_en = self.puntuar_idioma(texto)

        # Dos o más señales inglesas ya son sospechosas si no hay dominio claro del español.
        if puntos_en >= 2 and puntos_en >= max(2, puntos_es * 0.45):
            return True

        # Cuatro señales inglesas se consideran mezcla aunque haya bastante español.
        if puntos_en >= 4:
            return True

        return False

    def corregir_a_espanol(self, texto):
        """Intenta hasta dos veces traducir/reformular sin reutilizar historial."""
        texto_actual = texto

        for intento in range(2):
            mensajes = [
                {
                    "role": "system",
                    "content": (
                        "Eres un traductor y corrector profesional de español. "
                        "Devuelve exclusivamente una versión completamente en español natural del texto. "
                        "No expliques la traducción, no hagas comentarios, no añadas notas y no uses inglés. "
                        "Conserva únicamente nombres propios de marcas y tecnologías como Windows, Python, "
                        "Chrome, Ollama, Qwen, SQL o Visual Studio Code. "
                        "La salida será leída en voz alta, por lo que debe contener solo la respuesta final en español."
                    ),
                },
                {
                    "role": "user",
                    "content": (
                        "TRADUCE Y REESCRIBE COMPLETAMENTE EN ESPAÑOL EL SIGUIENTE TEXTO:\n\n"
                        + texto_actual
                        + "\n\nSALIDA: solamente el texto final en español."
                    ),
                },
            ]

            respuesta = self.enviar_ollama(
                mensajes,
                temperatura=0.0,
                num_predict=260,
            )

            if not respuesta:
                return None

            respuesta = self.limpiar_respuesta_ollama(respuesta)
            print(f"CORRECCIÓN ESPAÑOL INTENTO {intento + 1}:", respuesta)

            if not self.respuesta_tiene_demasiado_ingles(respuesta):
                return respuesta

            texto_actual = respuesta

        return None

    def regenerar_espanol_sin_historial(self, pregunta):
        """Genera desde cero una respuesta breve en español, sin recuerdos ni historial."""
        mensajes = [
            {
                "role": "system",
                "content": (
                    "Tu nombre es Beta y hablas con el Señor. "
                    "Responde EXCLUSIVAMENTE EN ESPAÑOL. Está prohibido escribir frases en inglés. "
                    "No muestres razonamiento ni análisis. Responde de forma breve, natural y útil. "
                    "Conserva en inglés únicamente nombres propios de tecnologías o marcas."
                ),
            },
            {
                "role": "user",
                "content": pregunta + "\n\nRespuesta final exclusivamente en español:",
            },
        ]

        respuesta = self.enviar_ollama(
            mensajes,
            temperatura=0.0,
            num_predict=200,
        )

        if not respuesta:
            return None

        return self.limpiar_respuesta_ollama(respuesta)

    def conversar_ollama_async(self, pregunta):
        token = self.iniciar_proceso("ollama")
        if token is None:
            self.responder(
                "todavía estoy terminando la respuesta anterior. Espere un momento y vuelva a preguntarme.",
                "pensando",
            )
            return

        self.expresion_pensando()

        def trabajo():
            respuesta = None
            uso_streaming = False
            try:
                if STREAMING_OLLAMA_ACTIVO:
                    sistema = self.construir_prompt_sistema(pregunta)
                    mensajes = [{"role": "system", "content": sistema}]
                    mensajes.extend(self.preparar_historial_ollama(pregunta)[-4:])
                    mensajes.append(
                        {
                            "role": "user",
                            "content": (
                                pregunta
                                + "\n\nResponde únicamente en español. Para conversación oral, "
                                  "da primero la respuesta directa y normalmente usa entre 2 y 4 frases. "
                                  "No uses Markdown salvo que sea imprescindible."
                            ),
                        }
                    )
                    respuesta = self.generar_y_hablar_ollama_streaming(
                        mensajes,
                        "general",
                        token,
                        temperatura=0.20,
                        num_predict=OLLAMA_NUM_PREDICT,
                    )
                    uso_streaming = bool(respuesta)
                else:
                    respuesta = self.consultar_ollama(pregunta)
            except Exception as error:
                print("ERROR HILO OLLAMA:", error)
            finally:
                self.terminar_proceso(token)

            # Si el watchdog ya invalidó esta operación, ignorar respuesta tardía.
            if token != self.proceso_id:
                return

            if respuesta and not uso_streaming:
                self.root.after(0, lambda r=respuesta: self.responder(r, "hablando"))
            elif not respuesta:
                self.root.after(
                    0,
                    lambda: self.responder(
                        "no pude obtener una respuesta de mi modelo local. Revise que Ollama esté iniciado.",
                        "confundida",
                    ),
                )

        threading.Thread(target=trabajo, daemon=True).start()

    # ======================================================
    # TAMAÑO / ARRASTRE / TOPMOST
    # ======================================================

    def cambiar_tamano_rueda(self, event):
        self.registrar_actividad()
        nuevo = self.tamano_beta + PASO_TAMANO if event.delta > 0 else self.tamano_beta - PASO_TAMANO
        self.ajustar_tamano(nuevo)

    def aumentar_tamano(self):
        self.ajustar_tamano(self.tamano_beta + PASO_TAMANO)

    def disminuir_tamano(self):
        self.ajustar_tamano(self.tamano_beta - PASO_TAMANO)

    def tamano_normal(self):
        self.ajustar_tamano(TAMANO_INICIAL)

    def ajustar_tamano(self, nuevo_tamano):
        nuevo_tamano = max(TAMANO_MINIMO, min(TAMANO_MAXIMO, int(nuevo_tamano)))
        if nuevo_tamano == self.tamano_beta:
            return

        centro_x = self.root.winfo_x() + self.tamano_beta / 2
        centro_y = self.root.winfo_y() + self.tamano_beta / 2
        self.tamano_beta = nuevo_tamano

        nueva_x = int(centro_x - nuevo_tamano / 2)
        nueva_y = int(centro_y - nuevo_tamano / 2)
        pantalla_ancho = self.root.winfo_screenwidth()
        pantalla_alto = self.root.winfo_screenheight()

        nueva_x = max(0, min(nueva_x, pantalla_ancho - nuevo_tamano))
        nueva_y = max(0, min(nueva_y, pantalla_alto - nuevo_tamano))

        self.root.geometry(
            f"{nuevo_tamano}x{nuevo_tamano}+{nueva_x}+{nueva_y}"
        )
        self.memoria.cambiar_estado("tamano_beta", nuevo_tamano)
        self.root.after(20, self.redibujar_beta)

    def iniciar_arrastre(self, event):
        self.arrastre_x = event.x
        self.arrastre_y = event.y
        self.registrar_actividad()

    def arrastrar_beta(self, event):
        nueva_x = self.root.winfo_x() + event.x - self.arrastre_x
        nueva_y = self.root.winfo_y() + event.y - self.arrastre_y
        self.root.geometry(f"+{nueva_x}+{nueva_y}")
        self.registrar_actividad()

    def guardar_posicion(self, event=None):
        try:
            self.memoria.cambiar_estado("pos_x", self.root.winfo_x())
            self.memoria.cambiar_estado("pos_y", self.root.winfo_y())
        except Exception:
            pass

    def mantener_siempre_visible(self):
        try:
            self.root.attributes("-topmost", True)
            self.root.update_idletasks()
            hwnd = self.root.winfo_id()
            HWND_TOPMOST = -1
            SWP_NOSIZE = 0x0001
            SWP_NOMOVE = 0x0002
            SWP_NOACTIVATE = 0x0010

            ctypes.windll.user32.SetWindowPos(
                hwnd,
                HWND_TOPMOST,
                0,
                0,
                0,
                0,
                SWP_NOSIZE | SWP_NOMOVE | SWP_NOACTIVATE,
            )
        except Exception:
            pass

        try:
            self.root.after(1000, self.mantener_siempre_visible)
        except tk.TclError:
            pass

    # ======================================================
    # ACTIVIDAD / IMPACIENCIA
    # ======================================================

    def registrar_actividad(self):
        self.ultimo_movimiento_mouse = time.time()
        self.impaciente = False

    def vigilar_inactividad(self):
        try:
            posicion_actual = (
                self.root.winfo_pointerx(),
                self.root.winfo_pointery(),
            )

            if posicion_actual != self.ultima_posicion_mouse:
                self.ultima_posicion_mouse = posicion_actual
                self.ultimo_movimiento_mouse = time.time()

                if self.impaciente:
                    self.impaciente = False
                    if not self.hablando and not self.procesando:
                        self.expresion_sorprendida()
                        self.root.after(700, self.volver_despues_sorpresa)

            tiempo_inactivo = time.time() - self.ultimo_movimiento_mouse

            if (
                tiempo_inactivo >= TIEMPO_IMPACIENCIA
                and not self.impaciente
                and not self.hablando
                and not self.procesando
                and not self.esperando_orden
                and self.expresion_actual
                not in {"pensando", "confundida", "molesta", "sorprendida"}
            ):
                self.impaciente = True
                self.expresion_impaciente()

        except Exception:
            pass

        try:
            self.root.after(500, self.vigilar_inactividad)
        except tk.TclError:
            pass

    def volver_despues_sorpresa(self):
        if self.expresion_actual != "sorprendida":
            return
        if self.escuchando:
            self.expresion_escuchando()
        else:
            self.expresion_normal()

    # ======================================================
    # INICIO / VOZ VOSK
    # ======================================================

    def obtener_saludo_horario(self):
        """Devuelve un saludo acorde a la hora local del computador.

        05:00 a 11:59  -> Buenos días
        12:00 a 19:59  -> Buenas tardes
        20:00 a 04:59  -> Buenas noches
        """
        hora = datetime.now().hour

        if 5 <= hora < 12:
            return "Buenos días, Señor"
        elif 12 <= hora < 20:
            return "Buenas tardes, Señor"
        else:
            return "Buenas noches, Señor"

    def extraer_clima_para_informe_inicio(self, texto_clima):
        """Extrae ciudad, temperatura y condición del texto que ya genera obtener_clima().

        Se mantiene una única fuente meteorológica dentro de Beta: el informe de
        inicio reutiliza obtener_clima() y su caché, en vez de abrir una segunda
        consulta independiente.
        """
        texto_clima = (texto_clima or "").strip()
        if not texto_clima:
            return None

        patron = re.search(
            r"^en\s+(.+?)\s+hay\s+(.+?)\s+grados,\s+con\s+([^,.]+)",
            texto_clima,
            flags=re.IGNORECASE,
        )
        if not patron:
            return None

        ubicacion_texto = patron.group(1).strip()
        temperatura = patron.group(2).strip()
        condicion = patron.group(3).strip()

        # Para la locución preferimos el nombre corto guardado por el geocodificador
        # (por ejemplo "Santiago") y no "Santiago, Región Metropolitana...".
        ciudad = (self.memoria.obtener_estado("clima_nombre", "") or "").strip()
        if not ciudad:
            ciudad = (self.memoria.obtener_estado("ciudad_clima", "") or "").strip()
        if not ciudad:
            ciudad = ubicacion_texto.split(",", 1)[0].strip()

        if not ciudad or not temperatura or temperatura.lower() == "sin dato":
            return None

        return {
            "ciudad": ciudad,
            "temperatura": temperatura,
            "condicion": condicion or "condiciones meteorológicas variables",
        }

    def construir_informe_inicio(self):
        """Construye el saludo dinámico con hora local y clima actual.

        Si Internet falla, intenta reutilizar la última lectura meteorológica
        almacenada. Beta nunca queda bloqueada por el clima: como último recurso
        informa la hora y continúa el inicio normalmente.
        """
        datos_clima = None
        error_clima = None

        try:
            texto_clima, error_clima = self.obtener_clima()
            if texto_clima:
                datos_clima = self.extraer_clima_para_informe_inicio(texto_clima)

            # Si la actualización falló, una lectura anterior sigue siendo más útil
            # que omitir por completo el clima. Se identifica en consola como caché.
            if datos_clima is None:
                cache_anterior = (
                    self.memoria.obtener_estado("clima_cache_texto", "") or ""
                ).strip()
                if cache_anterior:
                    datos_clima = self.extraer_clima_para_informe_inicio(cache_anterior)
                    if datos_clima:
                        print("INFORME DE INICIO: usando última lectura meteorológica disponible.")
        except Exception as error:
            error_clima = str(error)
            print("ERROR PREPARANDO CLIMA DEL INFORME DE INICIO:", error)

        # La hora se toma justo antes de construir la frase, para que no quede
        # desfasada si la consulta meteorológica tardó algunos segundos.
        ahora = datetime.now()
        saludo = self.obtener_saludo_horario()
        hora_texto = ahora.strftime("%H:%M")

        if datos_clima:
            print(
                "INFORME DE INICIO: "
                f"{datos_clima['ciudad']} | {datos_clima['temperatura']} °C | "
                f"{datos_clima['condicion']}"
            )
            return (
                f"{saludo}. Le informo que son las {hora_texto} horas. "
                f"En estos momentos, la ciudad de {datos_clima['ciudad']} registra "
                f"una temperatura de {datos_clima['temperatura']} grados centígrados, "
                f"con condiciones de {datos_clima['condicion']}. "
                "Nos encontramos listos para comenzar."
            )

        if error_clima:
            print("INFORME DE INICIO: clima no disponible:", error_clima)
        else:
            print("INFORME DE INICIO: no hay una ciudad meteorológica configurada.")

        return (
            f"{saludo}. Le informo que son las {hora_texto} horas. "
            "En estos momentos no pude actualizar las condiciones meteorológicas. "
            "Nos encontramos listos para comenzar."
        )

    def emitir_informe_inicio(self, mensaje):
        self.informe_inicio_en_curso = True
        self.responder(mensaje, "feliz", tipo_contexto="inicio")

        # Respaldo de seguridad: normalmente la escucha se activa al terminar
        # Daniela. Si por una falla de audio no llegara ese callback, Beta no
        # quedará muda para siempre.
        try:
            self.root.after(45000, self.iniciar_escucha_si_necesario)
        except tk.TclError:
            pass

    def iniciar_escucha_si_necesario(self):
        if not self.escuchando and not self.hablando:
            self.iniciar_escucha()

    def iniciar_beta(self):
        # El clima puede requerir una consulta de red de algunos segundos. Se
        # prepara fuera del hilo de Tk para que la esfera nunca se congele.
        def trabajo_inicio():
            mensaje_inicio = self.construir_informe_inicio()
            try:
                self.root.after(
                    0,
                    lambda mensaje=mensaje_inicio: self.emitir_informe_inicio(mensaje),
                )
            except tk.TclError:
                pass

        threading.Thread(target=trabajo_inicio, daemon=True).start()

    # ======================================================
    # RECONOCIMIENTO DE HABLANTE / HUELLAS VOCALES
    # ======================================================

    def cargar_modelo_hablante(self):
        if not USAR_RECONOCIMIENTO_HABLANTE:
            return
        if self.hablante_listo or self.hablante_cargando:
            return

        self.hablante_cargando = True
        try:
            from speechbrain.inference.speaker import EncoderClassifier
            from speechbrain.utils.fetching import LocalStrategy

            CARPETA_HABLANTE.mkdir(parents=True, exist_ok=True)
            archivo_local = CARPETA_HABLANTE / "hyperparams.yaml"

            print()
            print("==============================")
            print("PREPARANDO IDENTIDAD DE VOZ")
            if not archivo_local.exists():
                print("Primera vez: descargando modelo ECAPA-TDNN.")
                print("Modo Windows: se copiarán los archivos sin crear enlaces simbólicos.")
                print("Después funcionará localmente.")
            else:
                print("Modelo ECAPA-TDNN encontrado localmente.")
            print("==============================")

            # SpeechBrain usa SYMLINK por defecto. En Windows eso puede fallar
            # con WinError 1314 si no está activo el Modo desarrollador.
            # COPY_SKIP_CACHE fuerza archivos normales en la carpeta de Beta.
            self.modelo_hablante = EncoderClassifier.from_hparams(
                source=HABLANTE_REPO,
                savedir=str(CARPETA_HABLANTE),
                run_opts={"device": "cpu"},
                local_strategy=LocalStrategy.COPY_SKIP_CACHE,
            )
            self.hablante_listo = True
            self.hablante_error = ""
            print("IDENTIDAD DE VOZ LISTA")
            print("Voces autorizadas:", self.memoria.cantidad_voces_autorizadas())
            print()

        except ImportError as error:
            self.hablante_error = (
                "Falta SpeechBrain/PyTorch. Instale los paquetes indicados."
            )
            print("RECONOCIMIENTO DE HABLANTE NO DISPONIBLE:", self.hablante_error)
            print("Detalle:", error)
        except Exception as error:
            self.hablante_error = str(error)
            print("ERROR CARGANDO MODELO DE HABLANTE:", error)
        finally:
            self.hablante_cargando = False

    # ======================================================
    # PRIVACIDAD / MODOS DE ESCUCHA
    # ======================================================

    def _wake_candidatos_vosk(self):
        # "meta/metas" se conservan SOLO como candidatos de Vosk para poder
        # enviar la frase a Whisper. Nunca bastan por sí solos para activar Beta
        # en modo estricto, porque son palabras demasiado comunes en español.
        return ("beta", "veta", "petra", "meta", "metas")

    def _wake_estrictos(self):
        return ("beta", "veta", "petra")

    def _wake_en_inicio(self, texto_normal, incluir_ambiguos=False):
        palabras = (texto_normal or "").split()
        if not palabras:
            return None
        permitidos = self._wake_candidatos_vosk() if incluir_ambiguos else self._wake_estrictos()
        # Forma normal: "Beta, ...". También permitimos "Hola Beta...",
        # "Oye Beta..." y "Hey Beta..." sin aceptar la palabra en cualquier
        # posición de una conversación ambiental.
        if palabras[0] in permitidos:
            return palabras[0]
        if len(palabras) >= 2 and palabras[0] in {"hola", "oye", "hey"} and palabras[1] in permitidos:
            return palabras[1]
        # Despedida natural: "gracias Beta". Solo para frases cortas.
        if len(palabras) <= 5 and palabras[-1] in permitidos and any(
            p in palabras for p in ("gracias", "agradezco")
        ):
            return palabras[-1]
        return None

    def _wake_ambiguo_comando_seguro(self, texto_normal):
        """Recupera Meta/metas como Beta solo ante una orden directa y breve.

        La capa de audio ya filtró la frase y validó la voz autorizada cuando
        existen perfiles. No promovemos "meta" en conversación libre: exigimos
        que aparezca al inicio y que el cuerpo coincida con una orden típica.
        """
        t = normalizar(texto_normal or "")
        wake = self._wake_en_inicio(t, incluir_ambiguos=True)
        if wake not in {"meta", "metas"}:
            return None
        palabras = t.split()
        try:
            indice = palabras.index(wake)
        except ValueError:
            return None
        cuerpo = " ".join(palabras[indice + 1:]).strip()
        if not cuerpo or len(cuerpo.split()) > 18:
            return None
        arranques = (
            "ponme ", "pon un ", "pon una ", "dame ", "quiero ",
            "explicame ", "que es ", "cuando digo ", "quise decir ",
            "siguiente ejercicio", "otro ejercicio", "continua ",
            "continuemos ", "sigamos ", "abre ", "busca ", "reproduce ",
        )
        if cuerpo in {"gracias", "despierta"} or cuerpo.startswith(arranques):
            return wake
        return None

    def _orden_despertar_silencio(self, texto_normal):
        t = texto_normal or ""
        wake = self._wake_en_inicio(t, incluir_ambiguos=False)
        if not wake:
            return False
        return any(frase in t for frase in (
            "despierta", "despertar", "reactiva", "reanuda escucha",
            "reanuda la escucha", "vuelve a escuchar", "sal del silencio",
        ))

    def _actualizar_expiracion_modo_conversacion(self):
        if self.modo_escucha != "conversacion":
            return
        if self.modo_conversacion_hasta and time.time() > self.modo_conversacion_hasta:
            self.modo_escucha = "estricto"
            self.modo_conversacion_hasta = 0.0
            self.hablante_sesion_conversacion = ""
            self.ultima_autenticacion_fuerte_ts = 0.0
            self.esperando_orden = False
            try:
                if hasattr(self, "var_modo_escucha"):
                    self.var_modo_escucha.set("estricto")
            except Exception:
                pass
            print("MODO CONVERSACIÓN: cerrado por 60 s de silencio. Vuelve a modo estricto.")

    def renovar_modo_conversacion(self):
        if self.modo_escucha == "conversacion":
            self.modo_conversacion_hasta = time.time() + TIEMPO_MODO_CONVERSACION_SILENCIO

    def establecer_modo_escucha(self, modo, anunciar=False, requiere_autenticacion=False):
        modo = (modo or "").strip().lower()
        if modo not in {"estricto", "conversacion", "silencio"}:
            return False

        self.modo_escucha = modo
        self.esperando_orden = False
        self.tiempo_limite_orden = 0.0

        if modo == "conversacion":
            # Si existen voces autorizadas y el cambio vino por voz, la sesión
            # solo queda confiable cuando hubo autenticación fuerte reciente.
            voces_registradas = self.memoria.cantidad_voces_autorizadas() > 0
            autenticacion_reciente = (
                bool(self.hablante_actual)
                and self.ultima_autenticacion_fuerte_ts > 0
                and (time.time() - self.ultima_autenticacion_fuerte_ts) <= 12
            )
            if requiere_autenticacion and voces_registradas and not autenticacion_reciente:
                self.modo_escucha = "estricto"
                self.modo_conversacion_hasta = 0.0
                self.hablante_sesion_conversacion = ""
                try:
                    if hasattr(self, "var_modo_escucha"):
                        self.var_modo_escucha.set("estricto")
                except Exception:
                    pass
                print("PRIVACIDAD: modo conversación rechazado; faltó autenticación fuerte reciente.")
                if anunciar:
                    self.responder(
                        "no pude confirmar suficientemente su identidad para abrir una conversación libre. "
                        "Repita Beta, activa modo conversación.",
                        "confundida",
                        tipo_contexto="general",
                    )
                return False

            self.modo_conversacion_hasta = time.time() + TIEMPO_MODO_CONVERSACION_SILENCIO
            if self.hablante_actual:
                self.hablante_sesion_conversacion = self.hablante_actual
                print(f"MODO CONVERSACIÓN: sesión vinculada a {self.hablante_sesion_conversacion}.")
            else:
                self.hablante_sesion_conversacion = ""
            respuesta = (
                "modo conversación activado. Durante el próximo minuto puede continuar "
                "hablándome sin repetir mi nombre; el tiempo se renueva con cada intervención."
            )
            print("MODO DE ESCUCHA: CONVERSACIÓN (60 s renovables).")
        elif modo == "silencio":
            self.modo_conversacion_hasta = 0.0
            self.hablante_sesion_conversacion = ""
            self.ultima_autenticacion_fuerte_ts = 0.0
            respuesta = (
                "modo silencio activado. Ignoraré las conversaciones y solo reaccionaré "
                "si dice Beta, despierta."
            )
            print("MODO DE ESCUCHA: SILENCIO. Solo 'Beta, despierta' puede reactivarme.")
        else:
            self.modo_conversacion_hasta = 0.0
            self.hablante_sesion_conversacion = ""
            self.ultima_autenticacion_fuerte_ts = 0.0
            respuesta = (
                "modo estricto activado. Solo responderé cuando diga mi nombre y la voz sea autorizada."
            )
            print("MODO DE ESCUCHA: ESTRICTO. Wake word + voz autorizada.")

        try:
            if hasattr(self, "var_modo_escucha"):
                self.var_modo_escucha.set(modo)
        except Exception:
            pass

        if anunciar:
            self.responder(respuesta, "normal", tipo_contexto="general")
        return True

    def cambiar_modo_escucha_menu(self):
        try:
            modo = self.var_modo_escucha.get()
        except Exception:
            modo = "estricto"
        self.establecer_modo_escucha(modo, anunciar=True)

    def frase_candidata_para_beta_vosk(self, texto_vosk):
        """Filtro barato ANTES de biometría y Whisper.

        En estricto, una charla ambiental sin wake word se descarta aquí.
        En silencio, ni siquiera se verifica la voz salvo ante un posible
        "Beta, despierta". En conversación, sí se valida cada intervención.
        """
        self._actualizar_expiracion_modo_conversacion()
        t = normalizar(texto_vosk)
        ahora = time.time()

        if self.modo_escucha == "conversacion":
            return ahora <= self.modo_conversacion_hasta

        if self.pregunta_curiosa_pendiente and ahora <= self.pregunta_curiosa_hasta:
            # Beta acaba de formular una pregunta explícita. Permitimos UNA
            # respuesta sin wake word, pero la biometría sigue siendo obligatoria.
            return True

        if self.evaluacion_academica_pendiente and ahora <= self.evaluacion_academica_hasta:
            return True

        if self.tutor_python_pendiente and (
            self.tutor_python_hasta <= 0.0 or ahora <= self.tutor_python_hasta
        ):
            # Una pregunta explícita de la tutora Python habilita una única
            # respuesta natural, manteniendo la biometría obligatoria.
            return True

        if self.esperando_orden and ahora <= self.tiempo_limite_orden:
            return True

        # Si Beta acaba de ofrecer coincidencias reales, una respuesta breve
        # como "uno", "dos" o "ninguna" es una continuación explícita.
        # Sigue pasando por biometría, pero no exige repetir el wake word.
        if getattr(self, "atlas_opciones_pendientes", None):
            limite = float(getattr(self, "atlas_opciones_hasta", 0.0) or 0.0)
            if not limite or ahora <= limite:
                if re.fullmatch(r"(?:el |la )?(?:1|2|3|4|5|6|uno|dos|tres|cuatro|cinco|seis|primero|primera|segundo|segunda|tercero|tercera|cuarto|cuarta|quinto|quinta|sexto|sexta)|(?:cancela|ninguna|ninguno|dejalo)", t):
                    return True

        # v3.5.2: una confirmación explícita de una operación sensible habilita
        # una sola respuesta corta sin repetir el wake word. La biometría sigue
        # siendo obligatoria en la capa de audio.
        if getattr(self, "atlas_confirmacion_pendiente", None):
            limite = float(getattr(self, "atlas_confirmacion_hasta", 0.0) or 0.0)
            if limite and ahora > limite:
                self.atlas_confirmacion_pendiente = None
            elif re.fullmatch(r"(?:si|sí|confirmo|confirma|de acuerdo|hazlo|adelante|acepto|no|cancela|cancelar|dejalo|déjalo)", t):
                return True

        wake = self._wake_en_inicio(t, incluir_ambiguos=True)
        if self.modo_escucha == "silencio":
            if not wake:
                return False
            return any(p in t for p in (
                "despierta", "despertar", "reactiva", "reanuda", "escucha", "silencio"
            ))

        return wake is not None

    def activacion_vosk_ambigua(self, texto_vosk):
        t = normalizar(texto_vosk)
        wake = self._wake_en_inicio(t, incluir_ambiguos=True)
        return wake in {"meta", "metas"}

    def vaciar_cola_audio_pendiente(self):
        """Descarta audio atrasado acumulado mientras Whisper estaba calculando."""
        if not AUDIO_VACIAR_COLA_TRAS_WHISPER:
            return 0
        descartados = 0
        try:
            while True:
                self.audio_queue.get_nowait()
                descartados += 1
        except queue.Empty:
            pass
        except Exception:
            pass
        if descartados:
            print(f"AUDIO: descartados {descartados} bloque(s) atrasados tras Whisper.")
        return descartados

    def transcripcion_asr_sospechosa(self, texto_vosk, texto_whisper):
        """Filtro conservador para alucinaciones típicas de Whisper/TV.

        Solo bloquea boilerplate corto o una expansión extrema desde una frase
        Vosk de 1-2 palabras a una transcripción no relacionada. No corrige dictado
        normal ni órdenes largas.
        """
        if not ASR_FILTRAR_BOILERPLATE:
            return False
        v = normalizar(texto_vosk)
        w = normalizar(texto_whisper)
        if not w:
            return False

        boilerplate = (
            "suscribete", "suscribete al canal", "gracias por ver",
            "gracias por mirar", "dale like", "activa la campana",
            "subtitulos", "subtitulos en espanol", "subtitulos realizados por",
            "nos vemos en el proximo video", "gracias por su atencion",
        )
        if len(w.split()) <= 6 and any(w == b or w.startswith(b + " ") for b in boilerplate):
            return True

        pv = v.split()
        pw = w.split()
        if len(pv) <= 2 and len(pw) >= 4:
            ratio = difflib.SequenceMatcher(None, v, w).ratio()
            if ratio < 0.22:
                return True
        return False

    def cambiar_reconocimiento_hablante(self):
        activo = bool(self.var_reconocimiento_hablante.get())
        cantidad_voces = self.memoria.cantidad_voces_autorizadas()

        if activo and cantidad_voces == 0:
            messagebox.showwarning(
                "Beta - Identidad de voz",
                "Primero registre al menos una voz autorizada.",
                parent=self.root,
            )
            self.var_reconocimiento_hablante.set(False)
            return

        # En v2.5.4, si hay voces registradas el modo privado exige biometría.
        # Evita que un clic accidental deje 'estricto' como solo wake word.
        if (
            not activo
            and cantidad_voces > 0
            and HABLANTE_BIOMETRIA_PRIVACIDAD_OBLIGATORIA
        ):
            messagebox.showwarning(
                "Beta - Privacidad",
                "Hay voces autorizadas registradas. Para conservar el modo privado, "
                "la verificación biométrica permanecerá activada.",
                parent=self.root,
            )
            self.var_reconocimiento_hablante.set(True)
            activo = True

        self.reconocimiento_hablante_activo = activo
        self.memoria.cambiar_estado("reconocimiento_hablante", "1" if activo else "0")

        if activo and not self.hablante_listo and not self.hablante_cargando:
            threading.Thread(target=self.cargar_modelo_hablante, daemon=True).start()

    def _pcm_a_16k(self, audio_pcm, frecuencia):
        try:
            import numpy as np
        except ImportError:
            return None

        if not audio_pcm:
            return None

        audio = np.frombuffer(audio_pcm, dtype=np.int16).astype(np.float32) / 32768.0
        if audio.size < 100:
            return None

        absoluto = np.abs(audio)
        p90 = float(np.percentile(absoluto, 90)) if absoluto.size else 0.0
        umbral = max(0.004, p90 * 0.12)
        indices = np.where(absoluto >= umbral)[0]
        if indices.size:
            margen = int(float(frecuencia) * 0.15)
            inicio = max(0, int(indices[0]) - margen)
            fin = min(audio.size, int(indices[-1]) + margen)
            audio = audio[inicio:fin]

        if frecuencia != HABLANTE_FRECUENCIA and audio.size > 1:
            duracion = audio.size / float(frecuencia)
            nueva_cantidad = max(1, int(duracion * HABLANTE_FRECUENCIA))
            x_origen = np.linspace(0.0, duracion, num=audio.size, endpoint=False)
            x_destino = np.linspace(0.0, duracion, num=nueva_cantidad, endpoint=False)
            audio = np.interp(x_destino, x_origen, audio).astype(np.float32)

        return audio

    def extraer_embedding_hablante(self, audio_pcm, frecuencia):
        if not self.hablante_listo or self.modelo_hablante is None:
            return None

        try:
            import numpy as np
            import torch

            audio = self._pcm_a_16k(audio_pcm, frecuencia)
            if audio is None or audio.size == 0:
                return None

            duracion = audio.size / float(HABLANTE_FRECUENCIA)
            if duracion < HABLANTE_MIN_SEGUNDOS:
                print(f"IDENTIDAD: audio demasiado corto ({duracion:.2f} s)")
                return None

            tensor = torch.from_numpy(audio).float().unsqueeze(0)
            with torch.no_grad():
                emb = self.modelo_hablante.encode_batch(tensor, normalize=True)

            vector = emb.squeeze().detach().cpu().numpy().astype(np.float32)
            norma = float(np.linalg.norm(vector))
            if norma <= 1e-8:
                return None
            return vector / norma

        except Exception as error:
            print("ERROR EXTRAER HUELLA VOCAL:", error)
            return None

    def es_seguimiento_corto_seguro(self, texto_vosk):
        """Permite una tolerancia biométrica limitada SOLO en conversación.

        Las frases breves dan embeddings más inestables. Para no volver a hacer
        permisivo el modo estricto, solo consideramos seguimiento contextual
        frases de hasta unas pocas palabras, sin wake word y sin órdenes de
        sistema/privacidad potencialmente sensibles.
        """
        t = normalizar(texto_vosk or "")
        palabras = t.split()
        if not palabras or len(palabras) > HABLANTE_MAX_PALABRAS_SEGUIMIENTO_CORTO:
            return False
        if self._wake_en_inicio(t, incluir_ambiguos=False) is not None:
            return False

        bloqueadas = {
            "abre", "abrir", "cierra", "cerrar", "apaga", "apagar",
            "reinicia", "reiniciar", "elimina", "eliminar", "borra", "borrar",
            "ejecuta", "ejecutar", "descarga", "descargar", "instala", "instalar",
            "registra", "registrar", "silencio", "despierta", "modo",
            "chrome", "youtube", "correo", "envia", "enviar", "archivo",
        }
        if any(p in bloqueadas for p in palabras):
            return False

        inicios_seguros = (
            "dame " , "dime " , "explica", "explicame", "profundiza",
            "continua", "sigue", "por que", "porque", "como " ,
            "cual " , "cuales " , "que " , "y " , "otro " , "otra " ,
            "repite", "resume", "resumelo", "un ejemplo", "otro ejemplo",
            "gracias", "muchas gracias", "perfecto", "entendido", "de acuerdo",
        )
        return any(t.startswith(pref) for pref in inicios_seguros) or t in {
            "profundiza", "continua", "sigue", "por que", "como",
            "cual", "cuales", "que significa", "otro ejemplo", "resumelo",
            "gracias", "gracias beta", "muchas gracias", "perfecto", "entendido",
            "de acuerdo", "ok", "esta bien",
        }

    def identificar_hablante(self, audio_pcm, frecuencia, texto_vosk=""):
        voces = self.memoria.listar_voces_autorizadas(solo_activas=True)
        if not voces:
            # Sin perfiles de voz no hay contra qué verificar. El wake word sigue
            # siendo obligatorio en modo estricto.
            return True, ""

        # Consolidación v2.5.4: una base con voces registradas nunca debe saltarse
        # biometría por un flag persistente antiguo o desactivado accidentalmente.
        if not self.reconocimiento_hablante_activo:
            if HABLANTE_BIOMETRIA_PRIVACIDAD_OBLIGATORIA:
                print("PRIVACIDAD: biometría obligatoria restaurada para esta sesión.")
                self.reconocimiento_hablante_activo = True
                self.memoria.cambiar_estado("reconocimiento_hablante", "1")
            else:
                return True, ""

        if not self.hablante_listo:
            if not self.hablante_cargando:
                threading.Thread(target=self.cargar_modelo_hablante, daemon=True).start()
            print("IDENTIDAD: modelo todavía no disponible; frase ignorada por seguridad.")
            return False, ""

        try:
            import numpy as np
            actual = self.extraer_embedding_hablante(audio_pcm, frecuencia)
            if actual is None:
                print("IDENTIDAD: no se pudo obtener huella; frase ignorada.")
                return False, ""

            mejor_nombre = ""
            mejor_score = -1.0

            for _id, nombre, embedding, _muestras, _fecha, _activo in voces:
                if not embedding:
                    continue
                referencia = np.asarray(embedding, dtype=np.float32)
                if referencia.size != actual.size:
                    continue
                norma = float(np.linalg.norm(referencia))
                if norma <= 1e-8:
                    continue
                referencia = referencia / norma
                score = float(np.dot(actual, referencia))
                if score > mejor_score:
                    mejor_score = score
                    mejor_nombre = nombre

            ahora = time.time()
            umbral_aplicado = self.umbral_hablante
            seguimiento_contextual = False

            # v2.5.2: ECAPA es muy fiable con frases normales, pero una frase de
            # uno a cuatro segundos puede bajar mucho de score aun siendo la
            # misma persona. Solo durante un modo conversación EXPLÍCITO, abierto
            # por una autenticación fuerte reciente, permitimos un umbral más
            # bajo para seguimientos benignos y cortos.
            sesion_confiable = (
                self.modo_escucha == "conversacion"
                and ahora <= self.modo_conversacion_hasta
                and bool(self.hablante_sesion_conversacion)
                and (ahora - self.ultima_autenticacion_fuerte_ts)
                    <= HABLANTE_SESION_CONFIABLE_SEGUNDOS
            )
            if (
                sesion_confiable
                and mejor_nombre
                and mejor_nombre.casefold() == self.hablante_sesion_conversacion.casefold()
                and self.es_seguimiento_corto_seguro(texto_vosk)
            ):
                umbral_aplicado = min(
                    self.umbral_hablante, HABLANTE_UMBRAL_SEGUIMIENTO_CORTO
                )
                seguimiento_contextual = True

            print(
                f"IDENTIDAD DE VOZ: mejor={mejor_nombre or 'desconocido'} "
                f"score={mejor_score:.3f} umbral={umbral_aplicado:.3f}"
                + (" (seguimiento corto seguro)" if seguimiento_contextual else "")
            )

            if mejor_nombre and mejor_score >= umbral_aplicado:
                self.hablante_actual = mejor_nombre
                if mejor_score >= self.umbral_hablante:
                    self.ultima_autenticacion_fuerte_ts = ahora
                    if self.modo_escucha == "conversacion":
                        self.hablante_sesion_conversacion = mejor_nombre
                elif seguimiento_contextual:
                    print(
                        "IDENTIDAD: seguimiento corto aceptado por sesión autenticada; "
                        "no renueva la autenticación fuerte."
                    )
                return True, mejor_nombre

            self.hablante_actual = ""
            return False, ""

        except Exception as error:
            print("ERROR IDENTIFICANDO HABLANTE:", error)
            return False, ""

    def ventana_registrar_voz(self):
        if self.registrando_voz:
            return

        ventana = tk.Toplevel(self.root)
        ventana.title("Registrar voz autorizada")
        ventana.geometry("500x360")
        ventana.attributes("-topmost", True)

        ttk.Label(
            ventana,
            text="Registrar una voz autorizada",
            font=("Segoe UI", 13, "bold"),
        ).pack(pady=(18, 8))

        ttk.Label(
            ventana,
            text=(
                "La huella de voz se guardará localmente en beta.db.\n"
                "Las grabaciones temporales se descartan después del registro.\n"
                "Registre a otras personas solo con su consentimiento."
            ),
            justify="center",
            wraplength=440,
        ).pack(padx=20, pady=(0, 15))

        marco = ttk.Frame(ventana)
        marco.pack(fill="x", padx=25)
        ttk.Label(marco, text="Nombre:").pack(side="left")
        entrada_nombre = ttk.Entry(marco)
        entrada_nombre.pack(side="left", fill="x", expand=True, padx=(8, 0))

        estado = ttk.Label(
            ventana,
            text="Se grabarán 3 muestras de 4 segundos.",
            justify="center",
        )
        estado.pack(pady=25)

        boton = ttk.Button(ventana, text="Grabar mi voz")
        boton.pack(pady=8)

        def actualizar_estado(texto_estado):
            if ventana.winfo_exists():
                estado.configure(text=texto_estado)

        def terminar_registro(exito, mensaje):
            self.registrando_voz = False
            if ventana.winfo_exists():
                boton.configure(state="normal")
                actualizar_estado(mensaje)
            if exito:
                self.reconocimiento_hablante_activo = True
                self.memoria.cambiar_estado("reconocimiento_hablante", "1")
                try:
                    self.var_reconocimiento_hablante.set(True)
                except Exception:
                    pass
                messagebox.showinfo(
                    "Beta - Identidad de voz",
                    mensaje,
                    parent=ventana if ventana.winfo_exists() else self.root,
                )
            else:
                messagebox.showerror(
                    "Beta - Identidad de voz",
                    mensaje,
                    parent=ventana if ventana.winfo_exists() else self.root,
                )

        def worker(nombre):
            try:
                import numpy as np
                import sounddevice as sd

                if not self.hablante_listo:
                    self.cargar_modelo_hablante()
                if not self.hablante_listo:
                    raise RuntimeError(
                        self.hablante_error or "No se pudo cargar el modelo de identidad de voz."
                    )

                self.escuchando = False
                time.sleep(0.8)
                while not self.audio_queue.empty():
                    try:
                        self.audio_queue.get_nowait()
                    except Exception:
                        break

                embeddings = []
                for indice in range(HABLANTE_MUESTRAS_REGISTRO):
                    self.root.after(
                        0,
                        lambda i=indice: actualizar_estado(
                            f"Muestra {i + 1} de {HABLANTE_MUESTRAS_REGISTRO}: "
                            "hable de forma natural durante 4 segundos..."
                        ),
                    )
                    grabacion = sd.rec(
                        int(HABLANTE_SEGUNDOS_MUESTRA * HABLANTE_FRECUENCIA),
                        samplerate=HABLANTE_FRECUENCIA,
                        channels=1,
                        dtype="int16",
                    )
                    sd.wait()
                    pcm = grabacion.reshape(-1).tobytes()
                    emb = self.extraer_embedding_hablante(pcm, HABLANTE_FRECUENCIA)
                    if emb is not None:
                        embeddings.append(emb)
                    time.sleep(0.4)

                if len(embeddings) < 2:
                    raise RuntimeError(
                        "No obtuve suficiente voz clara. Intente nuevamente hablando cerca del micrófono."
                    )

                promedio = np.mean(np.stack(embeddings), axis=0)
                norma = float(np.linalg.norm(promedio))
                if norma <= 1e-8:
                    raise RuntimeError("No pude crear la huella vocal.")
                promedio = (promedio / norma).astype(np.float32)

                if not self.memoria.guardar_voz_autorizada(
                    nombre, promedio.tolist(), len(embeddings)
                ):
                    raise RuntimeError("No pude guardar la huella vocal en beta.db.")

                self.root.after(
                    0,
                    lambda: terminar_registro(
                        True,
                        f"Voz de {nombre} registrada correctamente. Beta ya puede reconocerla.",
                    ),
                )

            except Exception as error:
                self.root.after(
                    0,
                    lambda e=str(error): terminar_registro(False, e),
                )
            finally:
                if not self.escuchando:
                    self.root.after(800, self.iniciar_escucha)

        def iniciar_registro():
            nombre = entrada_nombre.get().strip()
            if not nombre:
                messagebox.showwarning(
                    "Beta", "Escriba el nombre de la persona.", parent=ventana
                )
                return
            if self.registrando_voz:
                return

            self.registrando_voz = True
            boton.configure(state="disabled")
            actualizar_estado("Preparando el micrófono y el modelo de voz...")
            threading.Thread(target=worker, args=(nombre,), daemon=True).start()

        boton.configure(command=iniciar_registro)

    def ventana_administrar_voces(self):
        ventana = tk.Toplevel(self.root)
        ventana.title("Voces autorizadas")
        ventana.geometry("620x480")
        ventana.attributes("-topmost", True)

        ttk.Label(
            ventana,
            text="Voces autorizadas para hablar con Beta",
            font=("Segoe UI", 12, "bold"),
        ).pack(anchor="w", padx=15, pady=(15, 8))

        columnas = ("nombre", "muestras", "fecha")
        tabla = ttk.Treeview(ventana, columns=columnas, show="headings", height=9)
        tabla.heading("nombre", text="Nombre")
        tabla.heading("muestras", text="Muestras")
        tabla.heading("fecha", text="Registrada")
        tabla.column("nombre", width=220)
        tabla.column("muestras", width=80, anchor="center")
        tabla.column("fecha", width=190)
        tabla.pack(fill="both", expand=True, padx=15, pady=5)

        def recargar():
            for item in tabla.get_children():
                tabla.delete(item)
            for voz_id, nombre, _emb, muestras, fecha, _activo in self.memoria.listar_voces_autorizadas(False):
                tabla.insert(
                    "", "end", iid=str(voz_id), values=(nombre, muestras, fecha)
                )

        def eliminar():
            seleccion = tabla.selection()
            if not seleccion:
                return
            voz_id = int(seleccion[0])
            valores = tabla.item(seleccion[0], "values")
            nombre = valores[0] if valores else "esta voz"
            if not messagebox.askyesno(
                "Beta",
                f"¿Eliminar la autorización de voz de {nombre}?",
                parent=ventana,
            ):
                return
            self.memoria.eliminar_voz_autorizada(voz_id)
            recargar()
            if self.memoria.cantidad_voces_autorizadas() == 0:
                self.reconocimiento_hablante_activo = False
                self.memoria.cambiar_estado("reconocimiento_hablante", "0")
                try:
                    self.var_reconocimiento_hablante.set(False)
                except Exception:
                    pass

        marco_botones = ttk.Frame(ventana)
        marco_botones.pack(fill="x", padx=15, pady=(4, 8))
        ttk.Button(
            marco_botones,
            text="Registrar otra voz",
            command=self.ventana_registrar_voz,
        ).pack(side="left")
        ttk.Button(
            marco_botones,
            text="Eliminar seleccionada",
            command=eliminar,
        ).pack(side="left", padx=8)

        marco_umbral = ttk.LabelFrame(ventana, text="Nivel de seguridad")
        marco_umbral.pack(fill="x", padx=15, pady=(4, 10))
        variable_umbral = tk.DoubleVar(value=float(self.umbral_hablante))
        etiqueta_umbral = ttk.Label(
            marco_umbral,
            text=f"Umbral: {self.umbral_hablante:.2f}  (más alto = más estricto)",
        )
        etiqueta_umbral.pack(anchor="w", padx=10, pady=(7, 2))

        def cambiar_umbral(valor):
            try:
                nuevo = max(0.30, min(0.75, float(valor)))
            except Exception:
                return
            self.umbral_hablante = nuevo
            self.memoria.cambiar_estado("umbral_hablante", f"{nuevo:.3f}")
            etiqueta_umbral.configure(
                text=f"Umbral: {nuevo:.2f}  (más alto = más estricto)"
            )

        ttk.Scale(
            marco_umbral,
            from_=0.30,
            to=0.75,
            variable=variable_umbral,
            command=cambiar_umbral,
        ).pack(fill="x", padx=10, pady=(0, 8))

        ttk.Label(
            ventana,
            text=(
                "La huella vocal es biométrica y se guarda localmente. "
                "No es una contraseña infalible: una grabación o una voz sintética "
                "podrían intentar imitar al usuario. Para acciones sensibles conviene "
                "mantener confirmaciones adicionales."
            ),
            wraplength=580,
            justify="left",
        ).pack(fill="x", padx=15, pady=(0, 12))

        recargar()

    def iniciar_escucha(self):
        # Protección contra dobles hilos de micrófono. El informe de inicio y su
        # respaldo pueden intentar activar la escucha casi al mismo tiempo.
        if self.escuchando:
            return

        modelo = buscar_modelo_vosk()

        if modelo is None:
            print("ERROR: Modelo Vosk no encontrado:", CARPETA_MODELO)
            self.expresion_confundida()
            return

        self.modelo_vosk = modelo
        self.escuchando = True
        self.expresion_escuchando()

        # Whisper se carga en segundo plano. Mientras termina de cargar,
        # Beta puede seguir funcionando con Vosk como respaldo.
        if USAR_WHISPER:
            threading.Thread(
                target=self.cargar_modelo_whisper,
                daemon=True,
            ).start()

        threading.Thread(
            target=self.escuchar_microfono,
            daemon=True,
        ).start()

    def cargar_modelo_whisper(self):
        if self.whisper_listo or self.whisper_cargando:
            return

        self.whisper_cargando = True

        try:
            from faster_whisper import WhisperModel

            CARPETA_WHISPER.mkdir(parents=True, exist_ok=True)

            # Si el modelo ya está descargado dentro del proyecto, se usa
            # exclusivamente desde disco. En el primer inicio se descarga
            # una sola vez y después ya no necesita Internet.
            archivo_modelo = CARPETA_WHISPER / "model.bin"

            if not archivo_modelo.exists():
                print()
                print("==============================")
                print("PREPARANDO WHISPER PARA BETA")
                print("Primera instalación: descargando el modelo", WHISPER_MODEL)
                print("Esto ocurre una sola vez. Después funciona localmente.")
                print("==============================")
                print()

                try:
                    from huggingface_hub import snapshot_download

                    snapshot_download(
                        repo_id=WHISPER_REPO,
                        local_dir=str(CARPETA_WHISPER),
                    )
                except Exception as error_descarga:
                    raise RuntimeError(
                        "No pude descargar el modelo Whisper. "
                        "Compruebe Internet durante esta primera instalación. "
                        f"Detalle: {error_descarga}"
                    )

            self.modelo_whisper = WhisperModel(
                str(CARPETA_WHISPER),
                device=WHISPER_DEVICE,
                compute_type=WHISPER_COMPUTE_TYPE,
            )

            self.whisper_listo = True
            self.whisper_error = ""

            print()
            print("==============================")
            print("WHISPER LISTO")
            print("Modelo:", WHISPER_MODEL)
            print("Idioma forzado: español")
            print("Modo: Vosk detecta wake word + voz autorizada; Whisper entiende el dictado")
            print("Curiosidad/evaluación/tutora Python: una pregunta explícita de Beta habilita una sola respuesta natural con voz autorizada")
            print("==============================")
            print()

        except ImportError:
            self.whisper_error = (
                "Falta faster-whisper. Ejecute: pip install faster-whisper"
            )
            print(self.whisper_error)
            print("Beta continuará usando Vosk hasta que lo instale.")

        except Exception as error:
            self.whisper_error = str(error)
            print("ERROR CARGANDO WHISPER:", error)
            print("Beta continuará usando Vosk como respaldo.")

        finally:
            self.whisper_cargando = False

    def debe_mejorar_con_whisper(self, texto_vosk):
        texto_normal = normalizar(texto_vosk)
        ahora = time.time()
        self._actualizar_expiracion_modo_conversacion()

        if self.modo_escucha == "conversacion" and ahora <= self.modo_conversacion_hasta:
            return True

        if self.pregunta_curiosa_pendiente and ahora <= self.pregunta_curiosa_hasta:
            return True

        if self.evaluacion_academica_pendiente and ahora <= self.evaluacion_academica_hasta:
            return True

        if self.tutor_python_pendiente and (
            self.tutor_python_hasta <= 0.0 or ahora <= self.tutor_python_hasta
        ):
            return True

        if self.esperando_orden and ahora <= self.tiempo_limite_orden:
            return True

        # En estricto/silencio solo llegamos a Whisper si Vosk detectó un posible
        # wake word al inicio. Esto evita transcribir conversaciones ambientales.
        return self._wake_en_inicio(texto_normal, incluir_ambiguos=True) is not None

    def transcribir_con_whisper(self, audio_pcm, frecuencia):
        if not self.whisper_listo or self.modelo_whisper is None:
            return ""

        if not audio_pcm:
            return ""

        ruta_temporal = None
        self.transcribiendo_whisper = True

        try:
            with tempfile.NamedTemporaryFile(
                suffix=".wav",
                delete=False,
            ) as temporal:
                ruta_temporal = temporal.name

            with wave.open(ruta_temporal, "wb") as wav:
                wav.setnchannels(1)
                wav.setsampwidth(2)
                wav.setframerate(int(frecuencia))
                wav.writeframes(audio_pcm)

            artistas_spotify = ", ".join(self.spotify_vocabulario[:12])
            extra_spotify = (
                " Spotify se pronuncia habitualmente como espótifai; si oye "
                "espotifai, spotifai, espotifay, es potifai o una variante fonética "
                "muy cercana, transcriba la palabra como Spotify. "
            )
            if artistas_spotify:
                extra_spotify += (
                    "Artistas frecuentes del usuario en Spotify: "
                    + artistas_spotify
                    + ". "
                )
            prompt = (
                "Conversación en español de Chile. "
                "El asistente se llama Beta y el usuario es el Señor. "
                "Términos frecuentes: Beta, Spotify, Python, SQL, Windows, Chrome, "
                "Ollama, Qwen, informática, programación, servidor, redes, REPL, PEP8, "
                "Pylint, variables, strings, funciones, listas, tuplas, diccionarios, "
                "clases, herencia, polimorfismo, excepciones, módulos, kwargs, xargs, lambda, "
                "return, def, elif, import, try, except, finally, async, await, Docker, Docker Compose. "
                "En programación Python, si oye algo parecido a 'retur', 'retun' o 'ritern', "
                "transcriba el término como return. "
                + extra_spotify +
                "Transcribe exactamente lo que dice el usuario en español, "
                "normalizando únicamente nombres propios conocidos como Spotify."
            )

            inicio_whisper = time.perf_counter()
            segmentos, info = self.modelo_whisper.transcribe(
                ruta_temporal,
                language=WHISPER_LANGUAGE,
                beam_size=WHISPER_BEAM_SIZE,
                best_of=1,
                temperature=0.0,
                vad_filter=False,
                condition_on_previous_text=False,
                without_timestamps=True,
                initial_prompt=prompt,
            )

            partes = []
            for segmento in segmentos:
                parte = (segmento.text or "").strip()
                if parte:
                    partes.append(parte)

            texto = " ".join(partes).strip()
            texto = re.sub(r"\s+", " ", texto).strip()
            texto = self.corregir_terminos_tecnicos_asr(texto)
            print(f"LATENCIA WHISPER: {time.perf_counter() - inicio_whisper:.2f} s")

            return texto

        except Exception as error:
            print("ERROR TRANSCRIBIENDO CON WHISPER:", error)
            return ""

        finally:
            self.transcribiendo_whisper = False
            if ruta_temporal:
                try:
                    os.remove(ruta_temporal)
                except Exception:
                    pass

    def es_comando_rapido_vosk(self, texto_vosk):
        """
        Para órdenes simples y bien reconocidas evitamos una segunda pasada por
        Whisper. Si Vosk no reconoce claramente la intención, Whisper sigue
        siendo el respaldo preciso.
        """
        # Spotify puede llegar como "espotifai"/"spotifai" por su pronunciación.
        t = self._spotify_normalizar_aliases(texto_vosk)
        palabras = set(t.split())

        # Consultas locales/directas que no necesitan análisis lingüístico complejo.
        if palabras & {"temperatura", "clima", "pronostico"}:
            return True
        if "tiempo" in palabras and palabras & {"dime", "esta", "hace", "actual", "manana", "siguiente"}:
            return True
        if "hora" in palabras:
            return True
        if ("hijos" in palabras or "hijo" in palabras or "hija" in palabras) and (
            "nombre" in palabras or "nombres" in palabras or "llaman" in palabras
        ):
            return True
        if palabras & {"calculadora", "explorador"}:
            return True
        # Spotify: si hay artista o búsqueda usamos Whisper para preservar
        # nombres propios. Abrir/pausar/reanudar sin consulta puede ser directo.
        if "spotify" in palabras:
            if palabras & {"busca", "buscar", "buscame", "reproduce", "reproducir", "pon", "toca", "musica", "cancion", "artista"}:
                return False
            return True
        if (palabras & {"reproduce", "pon", "toca"}) and "musica" in palabras:
            return False

        # Órdenes de YouTube con artista/tema usan Whisper para conservar
        # correctamente nombres propios como "Luli Pampín". Abrir YouTube sin
        # una búsqueda puede resolverse directamente con Vosk.
        if palabras & {"youtube", "yutube", "yutu"}:
            if palabras & {
                "busca", "buscar", "buscame", "reproduce", "reproducir",
                "reproduzca", "pon", "poner", "toca", "coloca", "video", "videos",
            }:
                return False
            return True

        # Abrir Chrome sin más es rápido. Si además hay una búsqueda, usamos
        # Whisper para conservar con precisión el tema dictado por el Señor.
        if "chrome" in palabras:
            if palabras & {"busca", "buscar", "buscame", "google", "internet", "imagenes", "fotos"}:
                return False
            return True
        if "bloc" in palabras and "notas" in palabras:
            return True
        if palabras & {"pendientes", "objetivos"}:
            return True
        if "nombre" in palabras and ("beta" in palabras or "veta" in palabras or "meta" in palabras or "metas" in palabras or "petra" in palabras):
            return True
        return False

    def escuchar_microfono(self):
        try:
            import sounddevice as sd
            from vosk import Model, KaldiRecognizer
        except ImportError:
            print("Faltan Vosk o sounddevice. Ejecute: pip install vosk sounddevice")
            self.root.after(0, self.expresion_confundida)
            return

        try:
            modelo = Model(str(self.modelo_vosk))
            dispositivo = sd.query_devices(kind="input")
            frecuencia = int(dispositivo["default_samplerate"])
            self.frecuencia_microfono = frecuencia

            print()
            print("==============================")
            print("BETA ESTÁ ESCUCHANDO")
            print("Micrófono:", dispositivo["name"])
            print("Frecuencia:", frecuencia)
            print("Reconocimiento rápido: Vosk")
            print("Dictado preciso: Faster-Whisper" if USAR_WHISPER else "Dictado preciso: desactivado")
            print("Modo de escucha: ESTRICTO (wake word + voz autorizada)" if self.modo_escucha == "estricto" else f"Modo de escucha: {self.modo_escucha.upper()}")
            print("==============================")
            print()

            reconocedor = KaldiRecognizer(modelo, frecuencia)
            audio_frase = bytearray()

            def callback(indata, frames, time_info, status):
                if status:
                    # La impresión dentro del callback de PortAudio puede
                    # producir más retrasos. Acumular el diagnóstico y emitirlo
                    # desde el consumidor, sin esconder las pérdidas reales.
                    self.audio_estado_eventos += 1
                    self.audio_estado_ultimo = str(status)

                if self.escuchando and not self.hablando and not self.transcribiendo_whisper:
                    bloque = bytes(indata)
                    try:
                        self.audio_queue.put_nowait(bloque)
                    except queue.Full:
                        # Nunca bloqueamos el callback de PortAudio. Si el consumidor
                        # se atrasó, descartamos primero el bloque más antiguo.
                        try:
                            self.audio_queue.get_nowait()
                        except queue.Empty:
                            pass
                        try:
                            self.audio_queue.put_nowait(bloque)
                        except queue.Full:
                            pass

            with sd.RawInputStream(
                samplerate=frecuencia,
                blocksize=4000,
                dtype="int16",
                channels=1,
                callback=callback,
            ):
                while self.escuchando:
                    ahora_audio = time.time()
                    if (self.audio_estado_eventos
                            and ahora_audio - self.audio_estado_ultimo_informe_ts >= 30):
                        print(
                            f"AUDIO: {self.audio_estado_eventos} advertencia(s) de PortAudio; "
                            f"última={self.audio_estado_ultimo}"
                        )
                        self.audio_estado_ultimo_informe_ts = ahora_audio
                        self.audio_estado_eventos = 0
                    try:
                        datos = self.audio_queue.get(timeout=0.5)
                    except queue.Empty:
                        continue

                    if self.hablando:
                        audio_frase.clear()
                        continue

                    audio_frase.extend(datos)

                    if reconocedor.AcceptWaveform(datos):
                        resultado = json.loads(reconocedor.Result())
                        texto_vosk = resultado.get("text", "").strip()
                        audio_actual = bytes(audio_frase)
                        audio_frase.clear()

                        if not texto_vosk:
                            continue

                        print("VOSK DETECTÓ:", texto_vosk)

                        # PRIVACIDAD v2.5.2: descartamos aquí cualquier conversación
                        # ambiental que no sea candidata a estar dirigida a Beta.
                        # Así ni Whisper ni la biometría trabajan sobre charlas ajenas.
                        if not self.frase_candidata_para_beta_vosk(texto_vosk):
                            if self.modo_escucha == "silencio":
                                print("MODO SILENCIO: frase ignorada.")
                            else:
                                print("MODO ESTRICTO: frase ambiental sin wake word; ignorada.")
                            continue

                        # Solo después del filtro de wake word verificamos la voz.
                        # En v2.5.4 la existencia de voces autorizadas vuelve esta
                        # verificación obligatoria, aunque un estado antiguo diga lo contrario.
                        debe_validar_voz = (
                            USAR_RECONOCIMIENTO_HABLANTE
                            and self.memoria.cantidad_voces_autorizadas() > 0
                        )
                        if debe_validar_voz:
                            autorizado, nombre_hablante = self.identificar_hablante(
                                audio_actual, frecuencia, texto_vosk
                            )
                            if not autorizado:
                                print("VOZ NO AUTORIZADA: frase ignorada.")
                                self.root.after(0, self.expresion_confundida)
                                continue
                            if nombre_hablante:
                                print("VOZ AUTORIZADA:", nombre_hablante)

                        texto_final = texto_vosk

                        # "meta/metas" son alias demasiado ambiguos para saltarse
                        # Whisper en modo estricto. Si Vosk oyó uno de ellos,
                        # obligamos a Whisper a confirmar y preferimos que la
                        # transcripción final contenga "Beta".
                        rapido_vosk = self.es_comando_rapido_vosk(texto_vosk)
                        if self.modo_escucha != "conversacion" and self.activacion_vosk_ambigua(texto_vosk):
                            rapido_vosk = False

                        if rapido_vosk:
                            print("MODO RÁPIDO: comando directo; se omite Whisper.")

                        # Vosk decide si la frase es candidata. Solo entonces usamos
                        # Whisper, evitando consumir CPU con conversaciones ambientales.
                        if USAR_WHISPER and self.debe_mejorar_con_whisper(texto_vosk) and not rapido_vosk:
                            if self.whisper_cargando and not self.whisper_listo:
                                print(
                                    f"WHISPER: cargando; esperaré hasta {WHISPER_ESPERA_ARRANQUE_SEGUNDOS} s "
                                    "para no responder con una transcripción Vosk dudosa."
                                )
                                limite_whisper = time.time() + WHISPER_ESPERA_ARRANQUE_SEGUNDOS
                                self.transcribiendo_whisper = True
                                try:
                                    while (
                                        self.whisper_cargando
                                        and not self.whisper_listo
                                        and time.time() < limite_whisper
                                    ):
                                        time.sleep(0.10)
                                finally:
                                    self.transcribiendo_whisper = False
                                if self.whisper_listo:
                                    print("WHISPER: listo tras espera de arranque; reanalizando la misma frase.")

                            if self.whisper_listo:
                                self.root.after(0, self.expresion_pensando)
                                texto_whisper = self.transcribir_con_whisper(
                                    audio_actual,
                                    frecuencia,
                                )

                                if texto_whisper:
                                    print("WHISPER ENTENDIÓ:", texto_whisper)
                                    if self.transcripcion_asr_sospechosa(texto_vosk, texto_whisper):
                                        vosk_norm_tutor = normalizar(texto_vosk)
                                        cierre_tutor = bool(
                                            self.tutor_python_pendiente
                                            and any(frase in vosk_norm_tutor for frase in [
                                                "listo", "completo", "respuesta completa",
                                                "he terminado", "termine", "eso es todo",
                                            ])
                                        )
                                        if cierre_tutor:
                                            # La voz ya fue autenticada y Vosk oyó un comando corto
                                            # inequívoco de cierre. Si Whisper alucina "suscríbete" u
                                            # otro boilerplate, conservar Vosk es más seguro que perder
                                            # la intención y dejar la respuesta abierta.
                                            texto_final = texto_vosk
                                            print(
                                                "ASR TUTORA: cierre recuperado desde Vosk; "
                                                f"Whisper sospechoso='{texto_whisper}'."
                                            )
                                        else:
                                            print(
                                                "ASR FILTRO: transcripción sospechosa/boilerplate ignorada "
                                                f"(Vosk='{texto_vosk}' | Whisper='{texto_whisper}')."
                                            )
                                            # Conservamos una ventana abierta tras 'Beta' sola;
                                            # el usuario puede repetir la orden sin reactivar el wake.
                                            self.vaciar_cola_audio_pendiente()
                                            continue
                                    else:
                                        texto_final = texto_whisper

                                    # Si Vosk oyó claramente la palabra de
                                    # activación pero Whisper omitió solo ese
                                    # nombre, conservamos la activación.
                                    vosk_normal = normalizar(texto_vosk)
                                    whisper_normal = normalizar(texto_final)
                                    activaciones_fuertes = ("beta", "veta", "petra")
                                    vosk_tiene_beta_fuerte = self._wake_en_inicio(
                                        vosk_normal, incluir_ambiguos=False
                                    ) is not None
                                    whisper_tiene_beta_fuerte = self._wake_en_inicio(
                                        whisper_normal, incluir_ambiguos=False
                                    ) is not None

                                    # Solo restauramos el wake word si Vosk oyó una
                                    # variante fuerte. Nunca convertimos "meta/metas"
                                    # en Beta automáticamente: eso era una fuente de
                                    # activaciones durante conversaciones normales.
                                    if (
                                        vosk_tiene_beta_fuerte
                                        and not whisper_tiene_beta_fuerte
                                        and self.modo_escucha != "conversacion"
                                        and not self.esperando_orden
                                    ):
                                        texto_final = "Beta " + texto_final

                                    # v2.9.7: conserva conceptos técnicos cortos
                                    # que Whisper puede omitir por completo.
                                    texto_final = self._fusionar_asr_tecnico_python(
                                        texto_vosk, texto_final
                                    )
                                    texto_final = self._fusionar_asr_modo_estudio(
                                        texto_vosk, texto_final
                                    )
                            elif self.whisper_cargando:
                                print("WHISPER: sigue cargando tras la espera; usando Vosk temporalmente.")
                            elif self.whisper_error:
                                print("WHISPER NO DISPONIBLE:", self.whisper_error)

                        # Whisper tarda varios segundos en CPU y durante ese tiempo
                        # pueden acumularse bloques viejos de la misma frase. Los quitamos
                        # antes de volver al ciclo de escucha para evitar dobles órdenes.
                        if USAR_WHISPER and not rapido_vosk:
                            self.vaciar_cola_audio_pendiente()

                        print("BETA ENTENDIÓ FINALMENTE:", texto_final)
                        self._encolar_texto_reconocido(texto_final)

        except Exception as error:
            print("ERROR MICRÓFONO:", error)
            self.root.after(0, self.expresion_confundida)

    def aprender_de_frase_natural(self, frase):
        if self.memoria.obtener_estado("modo_aprendizaje_natural", "1") != "1":
            return False

        original = (frase or "").strip()
        texto = normalizar(original)
        if not texto or len(texto.split()) < 3:
            return False

        # Evitar guardar preguntas como hechos.
        if texto.startswith((
            "que ", "como ", "cual ", "quien ", "cuando ", "donde ",
            "por que ", "puedes ", "podrias ", "me puedes ",
        )):
            return False

        patrones = [
            ("me gusta ", "preferencia", 2),
            ("me encanta ", "preferencia", 2),
            ("prefiero ", "preferencia", 2),
            ("no me gusta ", "preferencia", 2),
            ("estoy estudiando ", "aprendizaje", 2),
            ("estoy aprendiendo ", "aprendizaje", 2),
            ("estoy practicando ", "aprendizaje", 2),
            ("quiero aprender ", "objetivo", 3),
            ("mi objetivo es ", "objetivo", 3),
            ("mi meta es ", "objetivo", 3),
            ("tengo pendiente ", "pendiente", 3),
            ("tenemos pendiente ", "pendiente", 3),
            ("mañana quiero ", "pendiente", 2),
            ("manana quiero ", "pendiente", 2),
            ("mi proyecto es ", "proyecto", 2),
            ("estoy construyendo ", "proyecto", 2),
            ("estoy desarrollando ", "proyecto", 2),
        ]

        for patron, tipo, importancia in patrones:
            if texto.startswith(patron):
                guardado = self.memoria.guardar_recuerdo(
                    original,
                    importancia=importancia,
                    tipo=tipo,
                )
                if guardado:
                    print(f"APRENDIZAJE NATURAL [{tipo}]: {original}")
                return guardado

        return False

    # ======================================================
    # MEMORIA INTELIGENTE / CONTEXTO CONVERSACIONAL
    # ======================================================

    def es_dato_sensible_para_no_guardar(self, texto):
        """Evita memorizar automáticamente credenciales o secretos evidentes.

        Los recuerdos explícitos mediante "recuerda que..." siguen bajo control
        del Señor; esta protección se aplica al aprendizaje automático.
        """
        t = normalizar(texto)
        patrones = [
            "contrasena", "password", "clave bancaria", "pin bancario",
            "codigo de seguridad", "cvv", "numero de tarjeta", "token de acceso",
            "api key", "clave api", "frase semilla", "seed phrase",
        ]
        return any(p in t for p in patrones)

    def es_mensaje_memorizable(self, texto):
        """Filtra comandos/ruido y deja pasar conversación personal útil."""
        original = (texto or "").strip()
        t = normalizar(original)
        if not t or len(t.split()) < MEMORIA_INTELIGENTE_MIN_PALABRAS:
            return False
        if self.es_dato_sensible_para_no_guardar(original):
            return False

        # v3.2.1: abrir/cerrar el Aula o cambiar de proyecto son acciones operativas, no preferencias.
        if any(x in t for x in ("modo estudio", "el estudio")) and any(x in t for x in ("activa", "activar", "abre", "abrir", "abrimos", "abremos", "termina", "cerrar", "cierra")):
            return False
        if any(x in t for x in ("nuevo proyecto", "abre proyecto", "abrir proyecto", "carga archivo", "agrega archivo", "agregar archivo")):
            return False

        # v2.9.1: las órdenes de la tutora (y sus deformaciones de ASR) no son
        # preferencias personales. Evita recuerdos como "El Señor mencionó unme...".
        if getattr(self, "tutor_python_tema_actual", ""):
            palabras_tutor = set(t.split())
            if (
                "ejercicio" in palabras_tutor
                or "ejercicios" in palabras_tutor
                or "pista" in palabras_tutor
                or "solucion" in palabras_tutor
                or "solución" in original.lower()
                or "codigo" in palabras_tutor and "python" in palabras_tutor
                or "como voy en python" in t
                or "continuemos donde quedamos" in t
                or "continua donde quedamos" in t
                or ("python" in palabras_tutor and any(x in t for x in [
                    "quiero estudiar", "quiero aprende estudiar",
                    "quiero aprender", "quiero practicar", "vamos a estudiar"
                ]))
            ):
                return False

        # Preguntas puras normalmente consultan información; no son un hecho nuevo.
        interrogativos = (
            "que ", "como ", "cual ", "quien ", "cuando ", "donde ",
            "por que ", "puedes ", "podrias ", "me puedes ", "cuanto ",
        )
        if t.startswith(interrogativos):
            return False

        # Comandos operativos no deben convertirse en recuerdos personales.
        # Quitamos primero el wake word para que "Beta, genera..." también quede filtrado.
        t_operativo = re.sub(r"^(?:beta|veta|meta|better)\s+", "", t).strip()
        try:
            t_operativo = self._atlas_normalizar_orden_operativa(t_operativo)
        except Exception:
            pass
        comandos = (
            "abre ", "abrir ", "busca ", "buscar ", "reproduce ", "pon ",
            "crea ", "crear ", "borra ", "elimina ", "mueve ", "copia ",
            "renombra ", "ejecuta ", "inicia ", "apaga ", "reinicia ",
            "investiga ", "averigua ", "explicame ", "explica ", "define ",
            "defineme ", "dame ", "entregame ", "hablame ", "cuentame ",
            "resumeme ", "resume ", "muestrame ", "ensename ", "preguntame ",
            "compara ", "describeme ", "aclarame ", "ayudame ",
            "agrega ", "agregar ", "agregara ", "guarda ", "guardar ",
            "genera ", "generar ", "redacta ", "redactar ", "trabaja ", "trabajemos ",
            "incorpora ", "incorporar ", "termina ", "cierra ",
            "minimiza ", "minimizar ", "maximiza ", "maximizar ",
            "restaura ", "restaurar ", "pausa", "reanuda", "continua ",
            "entra a ", "entra en ", "vuelve a ", "volver a ",
            "dime la temperatura", "dime el clima", "dime el tiempo",
            "dime el estado", "estado de ", "estado del ", "estado de atlas",
            "muestrame las fuentes", "abre la primera fuente",
        )
        if t_operativo.startswith(comandos):
            return False

        # v3.5.2: navegación/gestión de carpetas y archivos es contexto operativo,
        # incluso si la frase contiene "quiero". Evita recuerdos falsos como
        # "El Señor quiere hacer la carpeta Primer Semestre" por errores de ASR.
        if any(obj in t_operativo for obj in ("carpeta", "archivo", "documento")) and any(
            verbo in t_operativo for verbo in (
                "abre", "abrir", "ubica", "ubicar", "localiza", "buscar", "busca",
                "revisa", "revisar", "muestra", "mostrar", "muestrame", "entra",
                "cierra", "cerrar", "minimiza", "maximiza", "quiero que", "hagas", "haz"
            )
        ):
            return False

        # v3.5.2: un recordatorio/agenda es una tarea programada, no memoria
        # personal. Evita que frases como "necesito que me avises..." terminen
        # además como recuerdos o pendientes inferidos por Qwen.
        if any(x in t_operativo for x in (
            "recuerdame", "recordatorio", "avisame", "avisa me",
            "me avises", "me recuerdes", "calendario", "agenda",
            "que me tienes que recordar", "quien me tiene que recordar"
        )):
            return False
        # Navegación web y consultas de sistema son acciones/contexto operativo,
        # nunca hechos personales que la memoria inteligente deba inferir.
        if any(x in t_operativo for x in ("youtube", "google", "chrome")) and any(
            v in t_operativo for v in ("abre", "busca", "buscar", "entra", "ve a")
        ):
            return False
        if "temperatura" in t_operativo and any(x in self._orq_normalizar_hardware_contextual(t_operativo) for x in ("cpu", "gpu", "procesador", "computador", "atlas")):
            return False

        # Las órdenes de tutoría describen una consulta, no una preferencia personal.
        # No guardamos "según mis apuntes...", "dame un ejemplo" o "profundiza"
        # como si fueran hechos sobre el Señor.
        if any(m in t for m in (
            "segun mis apuntes", "en base a mis apuntes", "busca en mis apuntes",
            "dame un ejemplo", "otro ejemplo", "profundiza", "explicame mas",
            "hablame sobre", "puedes hablarme sobre", "consulta mis apuntes",
        )):
            return False

        # Afirmaciones en primera persona y datos relacionales suelen ser útiles.
        indicadores = [
            "yo ", "mi ", "mis ", "me ", "estoy ", "tengo ", "quiero ",
            "prefiero ", "trabajo ", "estudio ", "aprendo ", "vivo ",
            "mi esposa", "mi hijo", "mi hija", "mis hijos", "mi perro",
            "mi gato", "mis gatos", "me gusta", "me encanta", "no me gusta",
            "mi objetivo", "mi meta", "mi proyecto", "tengo pendiente",
        ]
        return any(ind in (t + " ") for ind in indicadores)

    def programar_memoria_inteligente(self, mensaje_usuario, respuesta_beta=""):
        if not self.modo_memoria_inteligente:
            return
        if time.time() - getattr(self, "ultima_respuesta_curiosa_ts", 0.0) < 3.0:
            return
        mensaje_usuario = (mensaje_usuario or "").strip()
        if not self.es_mensaje_memorizable(mensaje_usuario):
            return

        self.turnos_desde_resumen += 1
        self.memoria.cambiar_estado("turnos_desde_resumen", self.turnos_desde_resumen)
        self.cola_memoria_inteligente.put(
            {
                "usuario": mensaje_usuario,
                "beta": (respuesta_beta or "").strip(),
                "ts": time.time(),
            }
        )

    def worker_memoria_inteligente(self):
        """Analiza conversación en baja prioridad sin retrasar la respuesta principal."""
        while True:
            try:
                item = self.cola_memoria_inteligente.get()
            except Exception:
                time.sleep(1)
                continue

            try:
                # Esperar a que el Señor deje de hablar y Beta termine la respuesta.
                # Si llega otra intervención, el contador vuelve a empezar de forma natural.
                while True:
                    inactividad = time.time() - self.ultima_interaccion_voz
                    conversacion_activa = (
                        self.modo_escucha == "conversacion"
                        and time.time() <= self.modo_conversacion_hasta
                    )
                    es_curiosidad = bool(item.get("pregunta_curiosa"))
                    espera_objetivo = 8 if es_curiosidad else MEMORIA_INTELIGENTE_ESPERA
                    # Las respuestas a preguntas curiosas son explícitas y pueden
                    # consolidarse antes; el resto espera a que termine la sesión.
                    if (
                        inactividad >= espera_objetivo
                        and not self.hablando
                        and not self.procesando
                        and (es_curiosidad or not conversacion_activa)
                    ):
                        break
                    time.sleep(1.0)

                with self.memoria_inteligente_lock:
                    self.analizar_turno_para_memoria(item)
                    if self.turnos_desde_resumen >= RESUMEN_CONVERSACION_CADA_TURNOS:
                        self.crear_resumen_conversacion_inteligente()
            except Exception as error:
                print("ERROR MEMORIA INTELIGENTE:", error)
            finally:
                try:
                    self.cola_memoria_inteligente.task_done()
                except Exception:
                    pass

    def extraer_json_de_texto(self, texto):
        if not texto:
            return None
        limpio = texto.strip()
        limpio = re.sub(r"^```(?:json)?\s*", "", limpio, flags=re.IGNORECASE)
        limpio = re.sub(r"\s*```$", "", limpio)
        inicio = limpio.find("{")
        fin = limpio.rfind("}")
        if inicio == -1 or fin == -1 or fin <= inicio:
            return None
        try:
            return json.loads(limpio[inicio:fin + 1])
        except Exception:
            return None

    def analizar_turno_para_memoria(self, item):
        usuario = (item.get("usuario") or "").strip()
        respuesta_beta = (item.get("beta") or "").strip()
        pregunta_curiosa = (item.get("pregunta_curiosa") or "").strip()
        tema_curioso = (item.get("tema_curioso") or "").strip()
        if not usuario:
            return

        contexto_usuario = usuario
        if pregunta_curiosa:
            contexto_usuario = (
                f"PREGUNTA QUE BETA HIZO AL SEÑOR:\n{pregunta_curiosa}\n\n"
                f"RESPUESTA EXPLÍCITA DEL SEÑOR:\n{usuario}"
            )

        mensajes = [
            {
                "role": "system",
                "content": (
                    "Eres el módulo local de memoria de Beta. Analiza SOLO lo que el usuario afirma explícitamente. "
                    "No inventes, no deduzcas datos no dichos y no conviertas preguntas, órdenes de explicación "
                    "o solicitudes académicas en hechos personales. "
                    "Nunca escribas que el Señor entendió, aprendió o comprendió algo salvo que él lo haya afirmado "
                    "de forma explícita con frases como 'entendí', 'aprendí' o 'ya comprendí'. "
                    "No guardes contraseñas, PIN, tokens, números de tarjeta ni secretos de acceso. "
                    "Devuelve SOLO JSON válido con esta forma: "
                    '{"tema":"tema breve","resumen_turno":"una frase breve","recuerdos":['
                    '{"contenido":"hecho autosuficiente","tipo":"dato|persona|preferencia|aprendizaje|objetivo|pendiente|proyecto",'
                    '"importancia":1,"confianza":0.0}]}. '
                    "Usa importancia 1 a 3. Confianza debe ser 0 a 1. "
                    "Si no hay nada útil para memoria a largo plazo, recuerdos debe ser []. "
                    "Escribe los recuerdos en español y preferentemente como 'El Señor...' para que sean autosuficientes."
                ),
            },
            {
                "role": "user",
                "content": (
                    f"{contexto_usuario}\n\n"
                    "Extrae recuerdos únicamente de lo que el Señor respondió o afirmó explícitamente. "
                    "La pregunta de Beta solo aporta contexto y nunca debe convertirse por sí sola en un recuerdo."
                ),
            },
        ]

        inicio = time.perf_counter()
        respuesta = self.enviar_ollama(mensajes, temperatura=0.05, num_predict=220)
        if not respuesta:
            return
        datos = self.extraer_json_de_texto(self.limpiar_respuesta_ollama(respuesta))
        if not isinstance(datos, dict):
            print("MEMORIA INTELIGENTE: JSON no interpretable; se omite el turno.")
            return

        tema = str(datos.get("tema") or "").strip()
        resumen_turno = str(datos.get("resumen_turno") or "").strip()
        recuerdos = datos.get("recuerdos") or []
        guardados = 0

        tipos_validos = {
            "dato", "persona", "preferencia", "aprendizaje",
            "objetivo", "pendiente", "proyecto",
        }

        if isinstance(recuerdos, list):
            for candidato in recuerdos[:4]:
                if not isinstance(candidato, dict):
                    continue
                contenido = str(candidato.get("contenido") or "").strip()
                tipo = normalizar(str(candidato.get("tipo") or "dato")) or "dato"
                if tipo not in tipos_validos:
                    tipo = "dato"
                try:
                    importancia = max(1, min(3, int(candidato.get("importancia", 1))))
                except Exception:
                    importancia = 1
                try:
                    confianza = float(candidato.get("confianza", 0.8))
                except Exception:
                    confianza = 0.8

                # Exigimos una confianza razonable y una frase que tenga contenido real.
                if confianza < 0.72 or len(normalizar(contenido).split()) < 4:
                    continue
                if self.es_dato_sensible_para_no_guardar(contenido):
                    continue

                nuevo = self.memoria.guardar_recuerdo(
                    contenido,
                    importancia=importancia,
                    tipo=tipo,
                    fuente="curiosidad_usuario" if pregunta_curiosa else "conversacion_ia",
                    confianza=confianza,
                    tema=tema or tema_curioso,
                )
                if nuevo:
                    guardados += 1
                    print(f"MEMORIA INTELIGENTE [{tipo}] + {contenido}")

        if tema:
            self.contexto_tema = tema
            self.contexto_actualizado_ts = time.time()
            self.memoria.cambiar_estado("contexto_tema", tema)
        if resumen_turno:
            self.contexto_resumen = resumen_turno
            self.memoria.cambiar_estado("contexto_resumen", resumen_turno)

        print(
            f"MEMORIA INTELIGENTE: {guardados} recuerdo(s) nuevo(s) "
            f"en {time.perf_counter() - inicio:.2f} s. Tema: {tema or 'sin tema'}"
        )

    def crear_resumen_conversacion_inteligente(self):
        # v2.9.13: resumimos SOLO la sesión viva. Usar historial_reciente() aquí
        # podía mezclar una conversación antigua con Python y guardar un resumen
        # contaminado que luego reaparecía en el prompt de continuidad.
        historial = list(self.contexto_turnos[-8:])
        if len(historial) < 6:
            print("RESUMEN DE CONVERSACIÓN: sesión actual demasiado corta; se omite.")
            return

        lineas = []
        for autor, mensaje in historial:
            # Limitar cada línea mantiene rápido el contexto para Qwen.
            lineas.append(f"{autor}: {mensaje[:500]}")
        transcripcion = "\n".join(lineas)

        mensajes = [
            {
                "role": "system",
                "content": (
                    "Resume una conversación entre el Señor y Beta para memoria de largo plazo. "
                    "Conserva hechos explícitos, temas, decisiones, objetivos, avances y pendientes. "
                    "No inventes. No copies saludos ni órdenes operativas irrelevantes. "
                    "Devuelve SOLO JSON válido: "
                    '{"tema":"tema principal","resumen":"resumen de 2 a 4 frases"}.'
                ),
            },
            {"role": "user", "content": transcripcion},
        ]
        respuesta = self.enviar_ollama(mensajes, temperatura=0.08, num_predict=180)
        datos = self.extraer_json_de_texto(self.limpiar_respuesta_ollama(respuesta or ""))
        if not isinstance(datos, dict):
            return

        tema = str(datos.get("tema") or self.contexto_tema or "").strip()
        resumen = str(datos.get("resumen") or "").strip()
        if resumen:
            if self.memoria.guardar_resumen_conversacion(
                resumen,
                tema=tema,
                turnos=self.turnos_desde_resumen,
            ):
                print("RESUMEN DE CONVERSACIÓN GUARDADO:", resumen[:180])
            self.contexto_resumen = resumen
            self.contexto_tema = tema
            self.memoria.cambiar_estado("contexto_resumen", resumen)
            self.memoria.cambiar_estado("contexto_tema", tema)

        self.turnos_desde_resumen = 0
        self.memoria.cambiar_estado("turnos_desde_resumen", "0")

    def debe_hacer_pregunta_seguimiento(self, mensaje):
        if not self.preguntas_seguimiento:
            return False
        t = normalizar(mensaje)
        if not t or len(t.split()) < 4:
            return False
        if "?" in (mensaje or ""):
            return False
        if t.startswith((
            "abre ", "busca ", "reproduce ", "pon ", "crea ", "borra ",
            "dime ", "investiga ", "averigua ", "recuerda ", "aprende ",
        )):
            return False
        return self.es_mensaje_memorizable(mensaje)

    def actualizar_contexto_turno(self, autor, mensaje):
        mensaje = (mensaje or "").strip()
        if not mensaje:
            return
        self.contexto_turnos.append((autor, mensaje))
        self.contexto_turnos = self.contexto_turnos[-8:]
        self.contexto_actualizado_ts = time.time()

    def _reiniciar_contador_curiosidad_si_corresponde(self):
        hoy = datetime.now().strftime("%Y-%m-%d")
        fecha = self.memoria.obtener_estado("curiosidad_fecha_contador", "") or ""
        if fecha != hoy:
            self.memoria.cambiar_estado("curiosidad_fecha_contador", hoy)
            self.memoria.cambiar_estado("curiosidad_preguntas_hoy", "0")

    def preguntas_curiosas_hoy(self):
        self._reiniciar_contador_curiosidad_si_corresponde()
        try:
            return int(self.memoria.obtener_estado("curiosidad_preguntas_hoy", "0") or 0)
        except Exception:
            return 0

    def incrementar_preguntas_curiosas_hoy(self):
        n = self.preguntas_curiosas_hoy() + 1
        self.memoria.cambiar_estado("curiosidad_preguntas_hoy", str(n))
        return n

    def cancelar_pregunta_curiosa(self, motivo=""):
        if self.pregunta_curiosa_pendiente and motivo:
            print(f"CURIOSIDAD: pregunta pendiente cerrada ({motivo}).")
        self.pregunta_curiosa_pendiente = None
        self.pregunta_curiosa_id = 0
        self.pregunta_curiosa_hasta = 0.0
        self.pregunta_curiosa_tema = ""
        self.pregunta_curiosa_tipo = "dato"

    def pregunta_curiosa_es_segura(self, pregunta):
        t = normalizar(pregunta)
        prohibidos = [
            "contrasena", "password", "pin", "tarjeta", "cvv", "rut", "documento de identidad",
            "direccion exacta", "cuenta bancaria", "sueldo", "ingresos", "deuda", "salud", "diagnostico",
            "enfermedad", "medicamento", "religion", "partido politico", "orientacion sexual", "vida sexual",
        ]
        if any(p in t for p in prohibidos):
            return False
        return 5 <= len(t.split()) <= 35 and "?" in pregunta

    def procesar_respuesta_curiosa(self, respuesta):
        respuesta = (respuesta or "").strip()
        if not self.pregunta_curiosa_pendiente or not respuesta:
            return

        pregunta = self.pregunta_curiosa_pendiente
        pregunta_id = self.pregunta_curiosa_id
        tema = self.pregunta_curiosa_tema
        self.cancelar_pregunta_curiosa()
        self.ultima_interaccion_voz = time.time()
        self.memoria.guardar_conversacion("Señor", respuesta)
        self.ultimo_mensaje_usuario = respuesta
        self.actualizar_contexto_turno("Señor", respuesta)
        self.memoria.marcar_pregunta_curiosa_respondida(pregunta_id, respuesta)
        self.ultima_respuesta_curiosa_ts = time.time()

        if self.es_dato_sensible_para_no_guardar(respuesta):
            self.responder(
                "entiendo. Por privacidad no guardaré esa respuesta en mi memoria automática.",
                "normal",
                tipo_contexto="curiosidad",
            )
            return

        self.cola_memoria_inteligente.put({
            "usuario": respuesta,
            "beta": "",
            "pregunta_curiosa": pregunta,
            "tema_curioso": tema,
            "ts": time.time(),
        })
        print(f"CURIOSIDAD: respuesta recibida para '{pregunta[:90]}'. Se consolidará en memoria.")
        self.responder(
            "entiendo, Señor. Gracias por contármelo; lo tendré en cuenta para conocerlo mejor.",
            "feliz",
            tipo_contexto="curiosidad",
        )

    def responder_aprendizajes_curiosos(self):
        recuerdos = self.memoria.recuerdos_por_fuente("curiosidad_usuario", limite=7)
        if not recuerdos:
            self.responder(
                "todavía no he consolidado recuerdos nacidos de mis propias preguntas. Podemos empezar cuando quiera.",
                "normal",
            )
            return
        textos = []
        for r in recuerdos:
            contenido = (r[1] or "").strip().rstrip(".")
            if contenido and contenido not in textos:
                textos.append(contenido)
        self.responder(
            "por nuestras conversaciones he aprendido que " + "; ".join(textos[:6]) + ".",
            "feliz",
        )

    def generar_pregunta_curiosa_async(self, forzada=False):
        if not forzada and not self.modo_curioso:
            return
        if self.pregunta_curiosa_pendiente and time.time() <= self.pregunta_curiosa_hasta:
            return
        if not forzada and self.preguntas_curiosas_hoy() >= CURIOSIDAD_MAX_PREGUNTAS_DIA:
            return
        if self.hablando or self.procesando or self.modo_escucha == "silencio":
            return

        token = self.iniciar_proceso("curiosidad")
        if token is None:
            return

        recuerdos = self.memoria.recuerdos_para_iniciativa(10)
        historial = self.memoria.ultimas_preguntas_curiosas(18)
        memoria_texto = "\n".join(f"- {r[1]}" for r in recuerdos[:8]) or "- Aún conozco pocas cosas."
        previas_texto = "\n".join(f"- {r[1]}" for r in historial[:12]) or "- Ninguna todavía."

        def trabajo():
            pregunta = ""
            tema = "conocer al Señor"
            tipo = "dato"
            try:
                mensajes = [
                    {
                        "role": "system",
                        "content": (
                            "Eres Beta. Tu objetivo es conocer gradualmente al Señor como una compañera curiosa, "
                            "sin invadir su privacidad. Haz UNA sola pregunta breve, natural y abierta. "
                            "Temas permitidos: estudios, informática, formas de aprender, proyectos, hobbies, "
                            "gustos culturales, rutinas de estudio, preferencias sobre cómo ayudarlo y metas. "
                            "No preguntes por salud, religión, política, finanzas, contraseñas, documentos, dirección exacta, "
                            "sexualidad ni otros datos sensibles. No repitas algo que ya esté en los recuerdos ni preguntas previas. "
                            "La pregunta debe invitar a responder con una frase, no solo sí/no. "
                            "Devuelve SOLO JSON: {\"pregunta\":\"... ?\",\"tema\":\"...\","
                            "\"tipo\":\"dato|preferencia|aprendizaje|objetivo|proyecto\"}."
                        ),
                    },
                    {
                        "role": "user",
                        "content": f"RECUERDOS YA CONOCIDOS:\n{memoria_texto}\n\nPREGUNTAS YA HECHAS:\n{previas_texto}",
                    },
                ]
                r = self.enviar_ollama(mensajes, temperatura=0.45, num_predict=100)
                datos = self.extraer_json_de_texto(self.limpiar_respuesta_ollama(r or ""))
                if isinstance(datos, dict):
                    pregunta = str(datos.get("pregunta") or "").strip()
                    tema = str(datos.get("tema") or tema).strip()
                    tipo = normalizar(str(datos.get("tipo") or tipo)) or "dato"
                if tipo not in {"dato", "preferencia", "aprendizaje", "objetivo", "proyecto"}:
                    tipo = "dato"
                if not self.pregunta_curiosa_es_segura(pregunta):
                    pregunta = "Señor, me dio curiosidad: ¿qué parte de la informática disfruta más aprender y qué es lo que le atrae de ella?"
                    tema = "intereses de informática"
                    tipo = "preferencia"
            except Exception as error:
                print("ERROR CURIOSIDAD:", error)
                pregunta = "Señor, me dio curiosidad: ¿qué parte de la informática disfruta más aprender y qué es lo que le atrae de ella?"
                tema = "intereses de informática"
                tipo = "preferencia"
            finally:
                self.terminar_proceso(token)

            if token != self.proceso_id or not pregunta:
                return

            def anunciar():
                self.pregunta_curiosa_pendiente = pregunta
                self.pregunta_curiosa_tema = tema
                self.pregunta_curiosa_tipo = tipo
                self.pregunta_curiosa_id = self.memoria.registrar_pregunta_curiosa(pregunta, tema, tipo)
                self.pregunta_curiosa_hasta = time.time() + CURIOSIDAD_RESPUESTA_SEGUNDOS
                self.interacciones_desde_curiosidad = 0
                self.proxima_pregunta_curiosa_ts = time.time() + random.randint(
                    CURIOSIDAD_MIN_SEGUNDOS, CURIOSIDAD_MAX_SEGUNDOS
                )
                self.incrementar_preguntas_curiosas_hoy()
                print(f"CURIOSIDAD: pregunta abierta por {CURIOSIDAD_RESPUESTA_SEGUNDOS} s | tema={tema}")
                self.responder(pregunta, "feliz", tipo_contexto="curiosidad")

            self.root.after(0, anunciar)

        threading.Thread(target=trabajo, daemon=True).start()

    def vigilar_curiosidad(self):
        try:
            ahora = time.time()
            hora = datetime.now().hour
            if self.pregunta_curiosa_pendiente and ahora > self.pregunta_curiosa_hasta:
                self.cancelar_pregunta_curiosa("sin respuesta")

            actividad_reciente = ahora - self.ultima_interaccion_voz <= 8 * 60
            condiciones = (
                self.modo_curioso
                and CURIOSIDAD_HORA_INICIO <= hora < CURIOSIDAD_HORA_FIN
                and ahora >= self.proxima_pregunta_curiosa_ts
                and self.interacciones_desde_curiosidad >= CURIOSIDAD_MIN_INTERACCIONES
                and self.preguntas_curiosas_hoy() < CURIOSIDAD_MAX_PREGUNTAS_DIA
                and actividad_reciente
                and not self.pregunta_curiosa_pendiente
                and not self.hablando
                and not self.procesando
                and not self.esperando_orden
                and self.modo_escucha != "silencio"
            )
            if condiciones:
                self.generar_pregunta_curiosa_async(forzada=False)
        except Exception as error:
            print("ERROR VIGILANDO CURIOSIDAD:", error)
        finally:
            self.root.after(60000, self.vigilar_curiosidad)

    def responder_pendientes(self):
        pendientes = self.memoria.recuerdos_por_tipo("pendiente", limite=6)
        if not pendientes:
            self.responder("no tengo pendientes guardados en mi memoria.", "normal")
            return

        textos = [p[1].strip().rstrip(".") for p in pendientes if p[1].strip()]
        if len(textos) == 1:
            respuesta = "tiene pendiente: " + textos[0] + "."
        else:
            respuesta = "tiene pendientes: " + "; ".join(textos) + "."
        self.responder(respuesta, "feliz")

    def responder_memoria_familiar(self, texto):
        """Ruta rápida para preguntas por los hijos, sin mezclar otros familiares."""
        patrones_hijos = [
            "nombre de mis hijos", "nombres de mis hijos", "como se llaman mis hijos",
            "como llaman mis hijos", "quienes son mis hijos", "quien son mis hijos",
        ]
        if not any(p in texto for p in patrones_hijos):
            return False

        candidatos = []
        ids = set()
        for consulta in ["mis hijos", "hijos se llaman", "hijo", "hija", "nombre hijos"]:
            for recuerdo in self.memoria.buscar_recuerdos(consulta, limite=10):
                contenido_norm = recuerdo[2] or ""
                # Regla estricta: una respuesta sobre hijos no puede provenir de
                # recuerdos que solo hablen de esposa, mascota u otra relación.
                if not re.search(r"\b(?:hijo|hijos|hija|hijas)\b", contenido_norm):
                    continue
                if recuerdo[0] not in ids:
                    ids.add(recuerdo[0])
                    candidatos.append(recuerdo)

        if not candidatos:
            self.responder(
                "no tengo guardados claramente los nombres de sus hijos. Puede enseñármelos diciendo: Beta, recuerda que mis hijos se llaman...",
                "confundida",
            )
            return True

        candidatos.sort(key=lambda r: (r[4], r[0]), reverse=True)
        textos = []
        for r in candidatos[:4]:
            contenido = r[1].strip().rstrip(".")
            if contenido and contenido not in textos:
                textos.append(contenido)

        if textos:
            self.responder("recuerdo que " + "; ".join(textos) + ".", "feliz")
        else:
            self.responder("no encontré los nombres de sus hijos en mi memoria.", "confundida")
        return True

    def responder_aprendizajes_directos(self):
        aprendizajes = self.memoria.recuerdos_por_tipo("aprendizaje", limite=6)
        if not aprendizajes:
            self.responder("todavía no tengo aprendizajes suyos guardados en mi memoria.", "normal")
            return
        textos = [r[1].strip().rstrip(".") for r in aprendizajes if r[1].strip()]
        self.responder("recuerdo que " + "; ".join(textos) + ".", "feliz")

    def responder_objetivos_directos(self):
        objetivos = self.memoria.recuerdos_por_tipo("objetivo", limite=6)
        if not objetivos:
            self.responder("todavía no tengo objetivos suyos guardados en mi memoria.", "normal")
            return
        textos = [r[1].strip().rstrip(".") for r in objetivos if r[1].strip()]
        self.responder("sus objetivos guardados son: " + "; ".join(textos) + ".", "feliz")

    # ======================================================
    # ENTREGA ORDENADA ASR -> CEREBRO v2.9.12
    # ======================================================

    def _encolar_texto_reconocido(self, texto):
        texto = (texto or "").strip()
        if not texto:
            return
        self.asr_secuencia_texto += 1
        item = (self.asr_secuencia_texto, texto, time.time())
        try:
            self.cola_textos_reconocidos.put_nowait(item)
        except queue.Full:
            try:
                viejo = self.cola_textos_reconocidos.get_nowait()
                print(f"ASR->CEREBRO: cola llena; descartando entrada antigua #{viejo[0]}.")
            except queue.Empty:
                pass
            try:
                self.cola_textos_reconocidos.put_nowait(item)
            except queue.Full:
                print("ASR->CEREBRO: no pude encolar una transcripción por saturación.")

    def _drenar_cola_textos_reconocidos(self):
        procesados = 0
        try:
            while procesados < 8:
                secuencia, texto, ts = self.cola_textos_reconocidos.get_nowait()
                print(f"ASR->CEREBRO: procesando #{secuencia}: {texto}")
                self.procesar_voz(texto)
                procesados += 1
        except queue.Empty:
            pass
        except Exception as error:
            print("ASR->CEREBRO: error procesando cola:", error)
        try:
            self.root.after(40, self._drenar_cola_textos_reconocidos)
        except tk.TclError:
            pass

    # ======================================================
    # PROCESAR VOZ / CEREBRO
    # ======================================================

    def procesar_voz(self, texto):
        texto_original = (texto or "").strip()
        texto_normal = normalizar(texto_original)
        if texto_original:
            self.penultimo_texto_asr_aceptado = self.ultimo_texto_asr_aceptado
            self.ultimo_texto_asr_aceptado = texto_original
            self.ultimo_texto_asr_ts = time.time()
        self.registrar_actividad()
        self._actualizar_expiracion_modo_conversacion()
        ahora = time.time()

        # SILENCIO: se ignora todo salvo una orden explícita de despertar con
        # wake word fuerte. El filtro de Vosk ya evita biometría/Whisper para
        # el resto, pero repetimos la regla aquí como segunda barrera.
        if self.modo_escucha == "silencio":
            if self._orden_despertar_silencio(texto_normal):
                self.establecer_modo_escucha("estricto", anunciar=True)
            else:
                print("MODO SILENCIO: orden no autorizada para despertar; ignorada.")
            return

        # v2.9.12: una corrección explícita del reconocimiento tiene prioridad
        # sobre cualquier ejercicio pendiente y nunca se evalúa como respuesta.
        wake_inicial_fuerte = self._wake_en_inicio(texto_normal, incluir_ambiguos=False)
        wake_inicial_adaptativo = self._wake_ambiguo_comando_seguro(texto_normal)
        if wake_inicial_fuerte is not None or wake_inicial_adaptativo is not None:
            if wake_inicial_adaptativo is not None and wake_inicial_fuerte is None:
                print(
                    f"WAKE ADAPTATIVO v2.9.13: '{wake_inicial_adaptativo}' aceptado "
                    "por coincidir con una orden breve conocida."
                )
            if self._procesar_ensenanza_alias_asr(texto_original):
                return

        # RESPUESTA A UN EJERCICIO DE LA TUTORA PYTHON. Como en las
        # evaluaciones académicas, se permite una sola respuesta natural sin
        # repetir Beta, pero siempre después de validar la voz autorizada.
        if self.tutor_python_pendiente:
            if self.tutor_python_hasta > 0.0 and ahora > self.tutor_python_hasta:
                self.cancelar_ejercicio_python(anunciar=False)
            else:
                wake_tutor = self._wake_en_inicio(texto_normal, incluir_ambiguos=False)
                if wake_tutor is None:
                    # Durante un ejercicio también aceptamos controles naturales sin
                    # wake word; no deben evaluarse como si fueran una respuesta.
                    if any(frase in texto_normal for frase in [
                        "dame una pista", "quiero una pista", "una pista",
                        "ayudame con una pista",
                    ]):
                        self.dar_pista_tutor_python()
                        return
                    if any(frase in texto_normal for frase in [
                        "muestrame la solucion", "dime la solucion",
                        "quiero ver la solucion", "cual es la solucion",
                        "dame la solucion",
                    ]):
                        self.mostrar_solucion_tutor_python()
                        return
                    if any(frase in texto_normal for frase in [
                        "termina ejercicio", "cancela ejercicio",
                        "termina el ejercicio", "cancela el ejercicio",
                    ]):
                        self.cancelar_ejercicio_python(anunciar=True)
                        return
                    if any(frase in texto_normal for frase in [
                        "listo", "completo", "respuesta completa", "he terminado",
                        "esa es mi respuesta", "esa seria mi respuesta",
                        "esa sería mi respuesta", "termine mi respuesta",
                        "terminé mi respuesta", "eso es todo",
                    ]):
                        self.finalizar_respuesta_tutor_python_buffer(forzar=True)
                        return
                    self.acumular_respuesta_tutor_python(texto_original)
                    return

        # RESPUESTA A UNA EVALUACIÓN ACADÉMICA. Se acepta una sola respuesta
        # natural sin wake word, siempre después de la validación biométrica.
        if self.evaluacion_academica_pendiente and ahora <= self.evaluacion_academica_hasta:
            wake_eval = self._wake_en_inicio(texto_normal, incluir_ambiguos=False)
            if wake_eval is None:
                self.procesar_respuesta_evaluacion(texto_original)
                return
        if self.evaluacion_academica_pendiente and ahora > self.evaluacion_academica_hasta:
            self.cancelar_evaluacion_academica(anunciar=False)

        # RESPUESTA A UNA PREGUNTA CURIOSA. Cuando Beta formula una pregunta
        # explícita, la siguiente respuesta puede llegar sin wake word. La capa
        # de audio ya exigió voz autorizada, por lo que aquí solo capturamos
        # una respuesta natural y cerramos inmediatamente esa ventana.
        if self.pregunta_curiosa_pendiente and ahora <= self.pregunta_curiosa_hasta:
            wake_curioso = self._wake_en_inicio(texto_normal, incluir_ambiguos=False)
            if wake_curioso is None:
                self.procesar_respuesta_curiosa(texto_original)
                return

        if self.pregunta_curiosa_pendiente and ahora > self.pregunta_curiosa_hasta:
            self.cancelar_pregunta_curiosa("tiempo agotado")

        # CONTROL ATLAS: después de preguntar cuál coincidencia abrir, aceptamos
        # una única selección corta sin wake word. La voz ya fue validada.
        if getattr(self, "atlas_opciones_pendientes", None):
            wake_atlas = self._wake_en_inicio(texto_normal, incluir_ambiguos=False)
            if wake_atlas is None and self._atlas_resolver_opcion_pendiente(texto_original):
                return

        # CONTROL ATLAS v3.5.2: una confirmación sensible pendiente acepta
        # únicamente sí/no sin wake word. No se mezcla con conversación general.
        if getattr(self, "atlas_confirmacion_pendiente", None):
            wake_conf = self._wake_en_inicio(texto_normal, incluir_ambiguos=False)
            if wake_conf is None and self._atlas_resolver_confirmacion_pendiente(texto_original):
                return

        # CONVERSACIÓN EXPLÍCITA: solo aquí se aceptan frases sin decir Beta.
        if self.modo_escucha == "conversacion" and ahora <= self.modo_conversacion_hasta:
            if (
                self.memoria.cantidad_voces_autorizadas() > 0
                and not self.hablante_sesion_conversacion
            ):
                print("PRIVACIDAD: sesión conversacional sin propietario; cerrando por seguridad.")
                self.establecer_modo_escucha("estricto", anunciar=False)
                return
            restante = max(0.0, self.modo_conversacion_hasta - ahora)
            print(
                f"MODO CONVERSACIÓN: aceptando frase sin wake word "
                f"({restante:.1f} s restantes)."
            )
            self.renovar_modo_conversacion()
            self.procesar_orden(texto_original)
            return

        # "Beta" sola abre una ventana MUY corta para la siguiente orden. Esta
        # ventana no se vuelve a abrir automáticamente tras las respuestas.
        if self.esperando_orden:
            if ahora <= self.tiempo_limite_orden:
                self.esperando_orden = False
                self.procesar_orden(texto_original)
                return
            self.esperando_orden = False
            self.tiempo_limite_orden = 0.0

        # ESTRICTO: exigimos una activación fuerte al inicio (o "gracias Beta"
        # al final). "meta/metas" sirven para despertar Whisper, pero si Whisper
        # no los confirma como Beta/veta/petra, aquí se descartan.
        wake = self._wake_en_inicio(texto_normal, incluir_ambiguos=False)
        if wake is None:
            wake = self._wake_ambiguo_comando_seguro(texto_normal)
            if wake is not None:
                print(
                    f"WAKE ADAPTATIVO v2.9.13: '{wake}' recuperado como activación "
                    "ante una orden breve conocida."
                )
        if wake is None:
            print("MODO ESTRICTO: transcripción final sin wake word fuerte; ignorada.")
            return

        # "Gracias Beta" es una despedida breve, no una nueva sesión abierta.
        palabras_actuales = texto_normal.split()
        if any(x in texto_normal for x in ["gracias", "muchas gracias", "te agradezco"]):
            if len(palabras_actuales) <= 7:
                self.ultima_frase_inicio = time.perf_counter()
                self.responder("de nada. Me alegra poder ayudarle.", "feliz")
                return

        # Extraemos solo lo que viene después del wake word. Para "Hola Beta"
        # buscamos la posición real de la palabra dentro de la frase normalizada.
        palabras = texto_normal.split()
        try:
            indice = palabras.index(wake)
        except ValueError:
            indice = 0
        orden = " ".join(palabras[indice + 1:]).strip()

        if orden:
            self.procesar_orden(orden)
        else:
            self.esperando_orden = True
            self.tiempo_limite_orden = time.time() + TIEMPO_ORDEN_TRAS_WAKE
            self.ultima_frase_inicio = time.perf_counter()
            print(
                f"WAKE WORD CONFIRMADO: esperando orden durante "
                f"{TIEMPO_ORDEN_TRAS_WAKE} s."
            )
            self.responder("dígame.", "escuchando")

    def procesar_orden(self, comando):
        comando = (comando or "").strip()
        if not comando:
            return

        self.registrar_actividad()
        self.ultima_interaccion_voz = time.time()
        if self.modo_escucha == "conversacion":
            self.renovar_modo_conversacion()
        self.memoria.guardar_conversacion("Señor", comando)
        self.ultimo_mensaje_usuario = comando
        self.actualizar_contexto_turno("Señor", comando)
        self.memoria.registrar_interaccion()
        self.interacciones_desde_curiosidad += 1
        # Capturamos la ventana del usuario antes de responder. La ventana
        # flotante de Beta es topmost, pero no debe convertirse en el objetivo
        # de frases como "minimiza esta ventana".
        try:
            activa = self._atlas_obtener_ventana_activa()
            if activa and normalizar(activa.get("titulo", "")) != "beta":
                self.atlas_ventana_usuario_previa = activa
        except Exception:
            pass
        self.expresion_pensando()
        self.ultima_frase_inicio = time.perf_counter()

        # No agregamos demora artificial antes de enrutar la orden.
        self.root.after(0, lambda: self.ejecutar_comando(comando))

    def _es_consulta_hora(self, texto):
        """Devuelve True solo si `hora` aparece como palabra independiente.

        v3.2.1: evita que frases académicas como "ahora redactemos la respuesta"
        activen accidentalmente la ruta del reloj porque "ahora" contiene
        la subcadena "hora".
        """
        t = normalizar(texto or "")
        palabras = set(re.findall(r"[a-z0-9áéíóúüñ]+", t, flags=re.IGNORECASE))
        if "hora" not in palabras:
            return False
        return not any(p in palabras for p in {"temperatura", "clima", "tiempo"})

    def ejecutar_comando(self, comando):
        original = comando.strip()
        contexto_python_previo = bool(
            self.tutor_python_tema_actual or self._contexto_python_activo()
        )
        original_corregido = self.corregir_terminos_tecnicos_asr(
            original,
            forzar_python=contexto_python_previo,
        )
        if contexto_python_previo:
            original_corregido = self._consulta_repl_contextual(original_corregido)
        if normalizar(original_corregido) != normalizar(original):
            print(
                f"RUTA TÉCNICA v2.9.8: comando normalizado "
                f"'{original}' -> '{original_corregido}'"
            )
        original = original_corregido
        texto = normalizar(original)
        print(f"RUTA DE RESPUESTA iniciada: {texto}")

        # 0) Curiosidad y aprendizaje activo. Son rutas locales de control;
        # nunca necesitan Internet ni deben caer al chat general.
        if any(frase in texto for frase in [
            "activa modo curioso", "activar modo curioso", "se mas curiosa",
            "quiero que seas curiosa", "quiero que me preguntes cosas",
        ]):
            self.modo_curioso = True
            self.memoria.cambiar_estado("modo_curioso", "1")
            try:
                self.var_modo_curioso.set(True)
            except Exception:
                pass
            self.responder(
                "activé el modo curioso. Iré conociéndolo poco a poco y recordaré sus respuestas explícitas.",
                "feliz",
            )
            return

        if any(frase in texto for frase in [
            "desactiva modo curioso", "desactivar modo curioso", "deja de preguntarme cosas",
            "no me hagas preguntas",
        ]):
            self.modo_curioso = False
            self.memoria.cambiar_estado("modo_curioso", "0")
            self.cancelar_pregunta_curiosa("modo curioso desactivado")
            try:
                self.var_modo_curioso.set(False)
            except Exception:
                pass
            self.responder(
                "desactivé el modo curioso. Seguiré recordando lo ya aprendido, pero no iniciaré nuevas preguntas.",
                "normal",
            )
            return

        if (
            texto in {"hazme una pregunta", "preguntame algo"}
            or "preguntame algo para conocerme" in texto
            or "quiero que me conozcas" in texto
            or "conoceme mejor" in texto
        ):
            self.generar_pregunta_curiosa_async(forzada=True)
            return

        if any(frase in texto for frase in [
            "que has aprendido de mi", "que aprendiste de mi", "que sabes de mi por tus preguntas",
        ]):
            self.responder_aprendizajes_curiosos()
            return

        # Beta v3.1.0: Aula Workspace / Modo Estudio. Se enruta antes de la tutora
        # para que "activa modo estudio" nunca caiga al chat general.
        if any(frase in texto for frase in [
            "activa modo estudio", "activar modo estudio", "abre modo estudio",
            "abrir modo estudio", "activa el modo estudio", "abre el aula",
            "abrir el aula", "abre el estudio", "abrir el estudio", "abremos el estudio",
            "abrimos el estudio", "abramos el estudio", "muestrame la pizarra", "mostrar pizarra",
        ]):
            self.activar_modo_estudio(anunciar=False)
            if "python" in texto and any(x in texto for x in [
                "estudiar", "aprender", "practicar", "python"
            ]):
                self.iniciar_sesion_python(self.inferir_tema_python(texto))
            else:
                self.responder(
                    "modo estudio activado. Abrí el aula de Beta. Dígame qué quiere estudiar y mantendré la explicación, los ejemplos y los ejercicios visibles en la pizarra.",
                    "feliz",
                )
            return

        if any(frase in texto for frase in [
            "termina modo estudio", "terminar modo estudio", "cierra modo estudio",
            "cerrar modo estudio", "salir de modo estudio", "cierra el aula",
            "cerrar el aula",
        ]):
            self.cerrar_modo_estudio(anunciar=True)
            return

        if self.modo_estudio_activo and any(frase in texto for frase in [
            "limpia la pizarra", "limpiar pizarra", "borra la pizarra",
        ]):
            self.aula_limpiar_pizarra()
            self.responder("pizarra limpia. Podemos continuar desde aquí.", "normal")
            return

        # Beta v3.1.0: proyectos académicos dentro del Aula.
        if self.modo_estudio_activo and any(frase in texto for frase in [
            "agrega archivos", "agregar archivos", "carga archivos", "cargar archivos",
            "agrega documentos", "carga documentos", "anade archivos", "añade archivos",
        ]):
            try:
                self.root.after(0, self.aula_agregar_archivos_proyecto)
            except Exception:
                pass
            self.responder("abrí el selector para agregar documentos al proyecto.", "normal", tipo_contexto="proyecto")
            return

        if self.modo_estudio_activo and any(frase in texto for frase in [
            "nuevo proyecto", "crea proyecto", "crear proyecto",
        ]):
            nombre = texto
            for pref in ["nuevo proyecto", "crea proyecto", "crear proyecto", "academico", "académico"]:
                nombre = nombre.replace(pref, " ")
            nombre = re.sub(r"\s+", " ", nombre).strip(" ,.-")
            if nombre:
                self.crear_proyecto_estudio(nombre, anunciar=True)
            else:
                try:
                    self.root.after(0, self.aula_nuevo_proyecto)
                except Exception:
                    pass
            return

        if self.modo_estudio_activo and any(frase in texto for frase in [
            "quiero trabajar con", "trabajemos con", "abre proyecto", "abrir proyecto",
            "continua proyecto", "continuemos proyecto", "continuemos el trabajo de",
        ]):
            objetivo = texto
            for pref in [
                "quiero trabajar con", "trabajemos con", "abre proyecto", "abrir proyecto",
                "continua proyecto", "continuemos proyecto", "continuemos el trabajo de",
            ]:
                objetivo = objetivo.replace(pref, " ")
            objetivo = re.sub(r"\s+", " ", objetivo).strip(" ,.-")
            existente = self._proyecto_buscar_nombre_similar(objetivo) if objetivo else ""
            if existente and self._proyecto_abrir_nombre(existente, silencioso=False):
                self._aula_seleccionar_pestana_proyecto()
                self.responder(
                    f"abrí el proyecto {existente}. Puede preguntarme por sus archivos desde el chat del Aula.",
                    "feliz", tipo_contexto="proyecto",
                )
            elif objetivo:
                self.crear_proyecto_estudio(objetivo, anunciar=True)
            else:
                try:
                    self.root.after(0, self.aula_abrir_proyecto)
                except Exception:
                    pass
            return

        # Tutora avanzada de Python v2.9.4.
        if any(frase in texto for frase in [
            "activa tutora python", "activar tutora python",
            "activa tutor python", "activar tutor python",
        ]):
            self.modo_tutor_python = True
            self.memoria.cambiar_estado("modo_tutor_python", "1")
            try:
                self.var_tutor_python.set(True)
            except Exception:
                pass
            self.responder(
                "tutora de Python activada. Puedo enseñarle por temas, proponer ejercicios y revisar código sin ejecutarlo.",
                "feliz",
            )
            return

        if any(frase in texto for frase in [
            "desactiva tutora python", "desactivar tutora python",
            "desactiva tutor python", "desactivar tutor python",
        ]):
            self.modo_tutor_python = False
            self.memoria.cambiar_estado("modo_tutor_python", "0")
            self.cancelar_ejercicio_python(anunciar=False)
            try:
                self.var_tutor_python.set(False)
            except Exception:
                pass
            self.responder(
                "tutora de Python desactivada. Conservaré el progreso para retomarlo después.",
                "normal",
            )
            return

        frases_inicio_python = [
            "quiero estudiar python", "estudiemos python", "ensename python",
            "quiero aprender python", "inicia sesion de python", "inicia sesion python",
            "abre tutor de python", "abre tutora de python",
        ]
        inicio_python_generico = (
            "python" in texto
            and any(frase in texto for frase in [
                "quiero estudiar", "estudiemos", "ensename", "quiero aprender",
                "quiero practicar", "vamos a estudiar",
            ])
        )
        if any(frase in texto for frase in frases_inicio_python) or inicio_python_generico:
            objetivo = texto
            for prefijo in frases_inicio_python + [
                "quiero estudiar", "estudiemos", "ensename",
                "quiero aprender", "quiero practicar", "vamos a estudiar",
                "python", "de python", "en python",
            ]:
                objetivo = objetivo.replace(prefijo, " ")
            item = self.inferir_tema_python(objetivo.strip()) if objetivo.strip() else None
            self.iniciar_sesion_python(item)
            return

        continuacion_python_explicita = any(frase in texto for frase in [
            "retomemos python", "continua con python",
            "continuemos con python", "sigamos con python",
        ])
        continuacion_generica = any(frase in texto for frase in [
            "continua donde quedamos", "continuemos donde quedamos",
            "sigamos donde quedamos",
        ])
        if continuacion_python_explicita or (
            continuacion_generica
            and self.tutor_python_tema_actual
            and (
                self._contexto_python_activo()
                or self.ultimo_tipo_respuesta_terminada in {
                    "tutor_python", "tutor_python_resultado", "tecnico"
                }
            )
        ):
            self.iniciar_o_continuar_tutor_python()
            return

        contexto_tutor_python = bool(
            self.tutor_python_tema_actual or self._contexto_python_activo()
        )

        # v2.9.3: si el Señor pregunta por qué falló la creación de un ejercicio,
        # respondemos sobre el estado real del generador. No enviamos la pregunta al
        # RAG técnico, porque eso podía inducir a Qwen a afirmar erróneamente que los
        # libros "no contienen ejercicios". Beta puede CREAR ejercicios a partir de
        # conceptos locales aunque el PDF no traiga una sección de ejercicios.
        if contexto_tutor_python and "ejercicio" in texto and "por que" in texto and any(
            x in texto for x in ["no puedes", "no puede", "no me puedes", "no pudiste", "fallo", "falla"]
        ):
            detalle = self.tutor_python_ultimo_error_ejercicio
            if detalle:
                print(f"TUTORA PYTHON: diagnóstico último fallo='{detalle}'")
            self.responder(
                "el problema fue temporal al generar la estructura del ejercicio, no porque sus libros "
                "carezcan de ejercicios. Puedo crear preguntas nuevas a partir de los conceptos de su "
                "biblioteca local y, si el generador falla, usaré un ejercicio de respaldo basado en esos mismos apuntes.",
                "normal",
                tipo_contexto="tutor_python",
            )
            return
        solicitud_ejercicio_python = any(frase in texto for frase in [
            "ponme un ejercicio", "pon un ejercicio", "dame un ejercicio",
            "hazme un ejercicio", "propone un ejercicio", "propon un ejercicio",
            "quiero practicar python", "ejercicio de python", "ejercicio sobre python",
            "quiero varios ejercicios", "dame varios ejercicios", "ponme varios ejercicios",
            "ejercicios de python", "ejercicios de fundamentos", "varios ejercicios de fundamentos",
            "siguiente ejercicio", "otro ejercicio",
        ])
        # Whisper a veces conserva "ejercicio" pero deforma el verbo ("unme un",
        # "poneme", etc.). Si ya estamos en una sesión Python, un comando corto que
        # contenga "ejercicio" se interpreta como práctica, salvo cancelar/terminar.
        ejercicio_corto_contextual = (
            contexto_tutor_python
            and ("ejercicio" in texto or "ejercicios" in texto)
            and len(texto.split()) <= 14
            and not any(x in texto for x in [
                "termina", "cancel", "solucion", "solución", "respuesta",
            ])
        )
        if (solicitud_ejercicio_python or ejercicio_corto_contextual) and (
            "python" in texto or contexto_tutor_python
        ):
            item = self.inferir_tema_python(texto)
            self.generar_ejercicio_python_async(item=item)
            return

        if self.tutor_python_pendiente and any(frase in texto for frase in [
            "dame una pista", "quiero una pista", "una pista", "ayudame con una pista",
        ]):
            self.dar_pista_tutor_python()
            return

        if (
            not self.tutor_python_pendiente
            and self.tutor_python_tema_actual
            and any(frase in texto for frase in [
                "dame una pista", "quiero una pista", "una pista", "ayudame con una pista",
            ])
        ):
            self.responder(
                "ese ejercicio ya fue evaluado. Si quiere practicar de nuevo, puedo proponerle otro ejercicio; "
                "si prefiere, también puedo explicarle la respuesta anterior.",
                "normal",
            )
            return

        if self.tutor_python_pendiente and any(frase in texto for frase in [
            "listo", "completo", "respuesta completa", "he terminado",
            "termine", "esa es mi respuesta", "esa seria mi respuesta",
            "termine mi respuesta", "eso es todo",
        ]):
            self.finalizar_respuesta_tutor_python_buffer(forzar=True)
            return

        if self.tutor_python_pendiente and any(frase in texto for frase in [
            "muestrame la solucion", "dime la solucion", "quiero ver la solucion",
            "cual es la solucion", "dame la solucion",
        ]):
            self.mostrar_solucion_tutor_python()
            return

        # Si el Señor dice "completo/listo" justo DESPUÉS de que el temporizador
        # ya corrigió la respuesta, no enviamos ese cierre tardío al chat general.
        # Simplemente confirmamos que el ejercicio ya quedó registrado.
        if (
            not self.tutor_python_pendiente
            and self.tutor_python_tema_actual
            and (time.time() - float(self.tutor_python_ultimo_resultado_ts or 0.0)) <= 45
            and any(frase in texto for frase in [
                "listo", "completo", "respuesta completa", "he terminado",
                "termine", "termine mi respuesta", "esa es mi respuesta",
                "eso es todo",
            ])
        ):
            self.responder(
                "esa respuesta ya quedó registrada, Señor. Cuando quiera podemos continuar con otro ejercicio.",
                "normal",
                tipo_contexto="tutor_python_resultado",
            )
            return

        if (
            not self.tutor_python_pendiente
            and self.tutor_python_tema_actual
            and any(frase in texto for frase in [
                "dame la respuesta anterior", "dime la respuesta anterior",
                "cual era la respuesta anterior", "cuál era la respuesta anterior",
                "explicame la respuesta anterior", "respuesta del ejercicio anterior",
                "solucion del ejercicio anterior", "solución del ejercicio anterior",
            ])
        ):
            self.explicar_ultimo_ejercicio_python()
            return

        if any(frase in texto for frase in [
            "termina ejercicio python", "termina el ejercicio python",
            "cancela ejercicio python", "cancela el ejercicio python",
            "termina ejercicio", "cancela ejercicio",
        ]) and self.tutor_python_pendiente:
            self.cancelar_ejercicio_python(anunciar=True)
            return

        if any(frase in texto for frase in [
            "como voy en python", "mi progreso en python",
            "muestrame mi progreso en python", "que nivel tengo en python",
            "como esta mi progreso en python",
        ]):
            self.responder_progreso_python()
            return

        if any(frase in texto for frase in [
            "revisa mi codigo python", "revisar codigo python",
            "abre revisor de codigo python", "quiero revisar codigo python",
        ]):
            self.ventana_revisar_codigo_python()
            self.responder(
                "abrí el revisor de código Python. Pegue allí el fragmento que quiere analizar; no lo ejecutaré.",
                "normal",
            )
            return

        # Autoevaluaciones dentro de una sesión Python se registran en el tema
        # actual antes de caer al seguimiento académico genérico.
        if (
            self.tutor_python_tema_actual
            and (self._contexto_python_activo() or self.ultimo_tipo_respuesta_terminada in {
                "tutor_python", "tutor_python_resultado", "tecnico"
            })
        ):
            if any(frase in texto for frase in [
                "ya entendi", "lo entendi", "esto lo entendi", "me quedo claro",
                "ya lo comprendi", "lo comprendi", "ahora lo entiendo",
            ]):
                self.registrar_autoevaluacion_python("comprendido")
                return
            if any(frase in texto for frase in [
                "no entendi", "no lo entendi", "esto me cuesta", "me cuesta este tema",
                "no me queda claro", "todavia no lo entiendo", "me cuesta entenderlo",
            ]):
                self.registrar_autoevaluacion_python("dificultad")
                return

        # v2.9.7: una consulta explícita sobre REPL dentro de una sesión Python
        # va directo al RAG técnico para evitar contaminación de un ramo académico
        # anterior o de una transcripción previa mal entendida.
        consulta_repl_explicita = (
            contexto_tutor_python
            and "repl" in texto
            and any(frase in texto for frase in [
                "que es repl", "que significa repl", "explicame repl",
                "explicame que es repl", "para que sirve repl",
                "hablame de repl", "define repl",
            ])
        )
        if consulta_repl_explicita:
            self.ultimo_contexto_academico_ts = 0.0
            if "para que sirve" in texto and ("que es repl" in texto or "explicame que es repl" in texto):
                consulta_repl = "Explícame qué es REPL y para qué sirve en Python."
            elif "para que sirve" in texto:
                consulta_repl = "Explícame para qué sirve REPL en Python."
            else:
                consulta_repl = "Explícame qué es REPL en Python."
            print(
                "RUTA REPL v2.9.8: consulta canónica -> "
                f"'{consulta_repl}'"
            )
            self.consultar_biblioteca_tecnica_async(
                consulta_repl,
                forzar=True,
                profunda_forzada=False,
                tokens_forzados=180,
            )
            return

        # Unidad de aprendizaje adaptativo.
        if any(frase in texto for frase in ["activa aprendizaje adaptativo","activar aprendizaje adaptativo","activa modo aprendizaje","activar modo aprendizaje"]):
            self.modo_aprendizaje_adaptativo=True; self.memoria.cambiar_estado("modo_aprendizaje_adaptativo","1")
            try: self.var_aprendizaje_adaptativo.set(True)
            except Exception: pass
            self.responder("aprendizaje adaptativo activado. Registraré evidencia real de estudio y evaluación.","feliz"); return
        if any(frase in texto for frase in ["desactiva aprendizaje adaptativo","desactivar aprendizaje adaptativo","desactiva modo aprendizaje","desactivar modo aprendizaje"]):
            self.modo_aprendizaje_adaptativo=False; self.memoria.cambiar_estado("modo_aprendizaje_adaptativo","0")
            try: self.var_aprendizaje_adaptativo.set(False)
            except Exception: pass
            self.responder("aprendizaje adaptativo desactivado. Conservaré el progreso ya registrado.","normal"); return
        if any(frase in texto for frase in ["como voy en mis estudios","como voy estudiando","mi progreso academico","muestrame mi progreso","cual es mi progreso","como esta mi progreso"]):
            self.responder_progreso_academico(); return
        if any(frase in texto for frase in ["que deberia repasar","que tengo que repasar","que necesito reforzar","que tema debo reforzar","que me recomiendas repasar"]):
            self.responder_recomendacion_repaso(); return
        if any(frase in texto for frase in ["termina evaluacion","termina la evaluacion","termino evaluacion","termino la evaluacion","finaliza evaluacion","cancela evaluacion"]):
            self.cancelar_evaluacion_academica(anunciar=True); return
        if any(frase in texto for frase in ["ya entendi","lo entendi","esto lo entendi","me quedo claro","ya lo comprendi","lo comprendi","ahora lo entiendo"]):
            self.registrar_autoevaluacion_academica("comprendido"); return
        if any(frase in texto for frase in ["no entendi","no lo entendi","esto me cuesta","me cuesta este tema","no me queda claro","todavia no lo entiendo","me cuesta entenderlo"]):
            self.registrar_autoevaluacion_academica("dificultad"); return
        if any(frase in texto for frase in ["evaluame sobre","evaluame en","ponme a prueba sobre","ponme a prueba en","hazme una pregunta de","hazme una pregunta sobre","preguntame sobre"]):
            objetivo=texto
            for prefijo in ["evaluame sobre","evaluame en","ponme a prueba sobre","ponme a prueba en","hazme una pregunta de","hazme una pregunta sobre","preguntame sobre"]:
                objetivo=objetivo.replace(prefijo," ")
            objetivo=objetivo.strip(); ramo=self.inferir_ramo_academico(objetivo) or objetivo; tema=objetivo or ramo
            self.generar_pregunta_evaluacion_async(ramo,tema); return
        if texto in {"otra pregunta","hazme otra pregunta","otra de evaluacion","otra evaluacion"}:
            ramo=self.ultimo_ramo_evaluacion or self.inferir_ramo_academico(""); tema=self.ultimo_tema_evaluacion or ramo
            if ramo: self.generar_pregunta_evaluacion_async(ramo,tema)
            else: self.evaluacion_manual()
            return

        # 1) Privacidad / modos de escucha. Estas órdenes tienen prioridad
        # porque cambian inmediatamente cuánto audio acepta Beta.
        # Una transcripción parcial como "activa modo" no se manda a Ollama:
        # esperamos la frase completa para evitar dos respuestas superpuestas.
        if (
            texto in {"activa modo", "activar modo", "modo conversacion...", "activa modo..."}
            or (
                texto.startswith(("activa modo", "activar modo"))
                and not any(m in texto for m in ("conversacion", "estricto", "silencio"))
            )
        ):
            print("COMANDO PARCIAL: esperando que termine la orden de modo; no se envía a Ollama.")
            return

        if any(frase in texto for frase in [
            "activa modo conversacion", "activar modo conversacion",
            "modo conversacion", "conversemos", "hablemos sin repetir beta",
        ]):
            self.establecer_modo_escucha(
                "conversacion", anunciar=True, requiere_autenticacion=True
            )
            return

        if any(frase in texto for frase in [
            "termina la conversacion", "termina conversacion",
            "termino la conversacion", "termine la conversacion",
            "terminar la conversacion", "termina modo conversacion",
            "finaliza la conversacion", "finalizo la conversacion",
            "cierra la conversacion", "cierro la conversacion",
            "cierra modo conversacion", "sal del modo conversacion",
            "sal de modo conversacion", "vuelve al modo estricto",
            "regresa al modo estricto", "modo estricto", "activa modo estricto",
        ]):
            self.establecer_modo_escucha("estricto", anunciar=True)
            return

        if any(frase in texto for frase in [
            "modo silencio", "activa modo silencio", "activar modo silencio",
            "silencio", "queda en silencio", "quedate en silencio",
        ]):
            self.establecer_modo_escucha("silencio", anunciar=True)
            return

        if any(frase in texto for frase in [
            "despierta", "reactiva la escucha", "reanuda la escucha",
            "vuelve a escuchar",
        ]):
            self.establecer_modo_escucha("estricto", anunciar=True)
            return

        if any(frase in texto for frase in [
            "que modo de escucha tienes", "cual es tu modo de escucha",
            "en que modo estas",
        ]):
            nombres = {
                "estricto": "modo estricto",
                "conversacion": "modo conversación",
                "silencio": "modo silencio",
            }
            self.responder(
                f"actualmente estoy en {nombres.get(self.modo_escucha, self.modo_escucha)}.",
                "normal",
            )
            return

        # 1) Comandos que el Señor enseñó: máxima prioridad.
        comando_aprendido = self.memoria.buscar_comando(texto)
        if comando_aprendido:
            self.fallos_consecutivos = 0
            self.responder(comando_aprendido[2], "feliz")
            return

        # 2) Enseñar información por voz.
        for prefijo in [
            "aprende que ",
            "recuerda que ",
            "quiero que recuerdes que ",
            "quiero que aprendas que ",
        ]:
            if texto.startswith(prefijo):
                contenido = texto[len(prefijo):].strip()
                if contenido:
                    guardado = self.memoria.guardar_recuerdo(contenido, importancia=2)
                    self.fallos_consecutivos = 0
                    if guardado:
                        self.responder("lo recordaré.", "feliz")
                    else:
                        self.responder("eso ya estaba en mi memoria.", "feliz")
                return

        # Aprendizaje natural: solo frases declarativas claras. No interrumpe la conversación.
        self.aprender_de_frase_natural(original)

        # 3) Nombre / identidad.
        if any(
            frase in texto
            for frase in [
                "como te llamas",
                "cual es tu nombre",
                "dime tu nombre",
                "quien eres",
                "que eres",
                "hablame de ti",
            ]
        ):
            self.fallos_consecutivos = 0
            self.responder(
                "me llamo Beta. Soy su asistente personal local y vivo en este computador.",
                "feliz",
            )
            return

        # 3.4) Saludos, presencia y agradecimientos: respuesta inmediata.
        # También cortan la continuidad académica activa para evitar que un
        # simple "¿estás ahí?" herede por accidente el tema anterior.
        texto_sin_wake = re.sub(
            r"^(beta|veta|meta|metas|petra)\s+", "", texto
        ).strip()
        palabras_breves = texto_sin_wake.split()
        if len(palabras_breves) <= 8 and any(
            frase in texto_sin_wake
            for frase in [
                "hola", "estas ahi", "sigues ahi", "estas alli",
                "me escuchas", "estas disponible", "sigues disponible",
            ]
        ):
            self.ultimo_contexto_academico_ts = 0.0
            self.ultimo_tipo_respuesta_terminada = "general"
            self.fallos_consecutivos = 0
            self.responder("sí, Señor. Aquí estoy y estoy disponible.", "feliz")
            return

        if len(palabras_breves) <= 6 and any(
            texto_sin_wake.startswith(frase)
            for frase in ["gracias", "muchas gracias", "te agradezco"]
        ):
            self.ultimo_tipo_respuesta_terminada = "general"
            self.fallos_consecutivos = 0
            self.responder("de nada, Señor.", "feliz")
            return

        # 3.5) Memoria familiar: respuesta directa y rápida, sin Ollama.
        if self.responder_memoria_familiar(texto):
            self.fallos_consecutivos = 0
            return

        # Beta v3.5.2: ORQUESTADOR DE INTENCIONES PRIMARIO.
        # Debe ejecutarse ANTES de fuentes, RAG y clima. Así una frase como
        # "temperatura del CPU", "abre YouTube" o "recuérdame..." nunca
        # puede ser secuestrada por el contexto académico o meteorológico.
        if self._orquestar_intencion_previa(original):
            return

        # 3.6) Fuentes de libros técnicos o apuntes académicos.
        if self.manejar_comando_fuentes_tecnicas(texto):
            return
        if self.manejar_comando_fuentes_academicas(texto):
            return

        # La consulta académica genérica se decide más abajo, después de
        # clima/web/acciones explícitas. Así una continuación como "explícame más
        # sobre la memoria" puede heredar el ramo activo antes de abrir una búsqueda
        # global por todas las asignaturas.

        # 4) Pronóstico de mañana / día siguiente.
        # Esta ruta debe evaluarse antes del clima actual para que una frase como
        # "dime la temperatura de mañana" no termine devolviendo el tiempo de hoy.
        palabras_manana = [
            "manana",
            "dia de manana",
            "dia siguiente",
            "siguiente dia",
            "proximo dia",
            "pronostico de manana",
            "tiempo de manana",
        ]
        palabras_meteo = [
            "clima",
            "temperatura",
            "meteorologico",
            "meteorologica",
            "tiempo",
            "pronostico",
        ]
        if (
            any(frase in texto for frase in palabras_manana)
            and any(palabra in texto for palabra in palabras_meteo)
        ):
            self.fallos_consecutivos = 0
            self.consultar_pronostico_manana_async()
            return

        # 4.1) Clima / temperatura actual.
        if any(
            palabra in texto
            for palabra in [
                "clima",
                "temperatura",
                "meteorologico",
                "meteorologica",
                "como esta el tiempo",
                "dime el tiempo",
                "que tiempo hace",
            ]
        ):
            self.fallos_consecutivos = 0
            self.consultar_clima_async()
            return

        # 5) Pendientes y objetivos guardados.
        if any(frase in texto for frase in [
            "que tengo pendiente", "que teniamos pendiente", "que tenemos pendiente",
            "cuales son mis pendientes", "dime mis pendientes", "que me falta hacer",
        ]):
            self.responder_pendientes()
            return

        if texto.startswith(("ya termine ", "ya complete ", "ya hice ")):
            consulta = re.sub(r"^(ya termine|ya complete|ya hice)\s+", "", texto).strip()
            completado = self.memoria.completar_pendiente(consulta)
            if completado:
                self.responder("marqué ese pendiente como completado.", "feliz")
            else:
                self.responder("no encontré un pendiente relacionado para marcarlo como completado.", "confundida")
            return

        if any(frase in texto for frase in [
            "cuales son mis objetivos", "que objetivos tengo", "cual es mi objetivo",
            "que metas tengo", "cuales son mis metas",
        ]):
            self.responder_objetivos_directos()
            return

        if any(frase in texto for frase in [
            "que estoy aprendiendo", "que estoy estudiando", "que estoy practicando",
            "que he estado aprendiendo", "que estoy aprendiendo ahora",
        ]):
            self.responder_aprendizajes_directos()
            return

        # 6) Consultas explícitas de recuerdos.
        for prefijo in [
            "que sabes de ",
            "que sabes sobre ",
            "que recuerdas de ",
            "que recuerdas sobre ",
        ]:
            if texto.startswith(prefijo):
                consulta = texto[len(prefijo):].strip()
                recuerdos = self.memoria.buscar_recuerdos(consulta, 5)
                if recuerdos:
                    contenido = "; ".join(r[1].strip().rstrip(".") for r in recuerdos)
                    self.responder("recuerdo que " + contenido + ".", "feliz")
                else:
                    self.responder("no encontré un recuerdo relacionado con eso.", "confundida")
                return

        if texto in {"que recuerdas", "que has aprendido", "que sabes"}:
            recuerdos = self.memoria.ultimos_recuerdos(5)
            if not recuerdos:
                self.responder("todavía tengo pocos recuerdos.", "confundida")
            else:
                contenido = "; ".join(r[1] for r in recuerdos[:4])
                self.responder("entre otras cosas, recuerdo que " + contenido + ".", "feliz")
            return

        if texto.startswith("olvida "):
            eliminado = self.memoria.olvidar(texto.replace("olvida ", "", 1).strip())
            if eliminado:
                self.responder("he eliminado ese recuerdo.", "normal")
            else:
                self.responder("no encontré ese recuerdo.", "confundida")
            return

        # Comando de recuperación manual por si alguna consulta externa quedó atascada.
        if (
            any(frase in texto for frase in [
                "cancela la consulta", "cancela lo anterior", "reinicia la respuesta",
                "deja de pensar", "dejas de pensar", "deje de pensar", "cancela respuesta",
                "para de pensar", "pare de pensar", "deten la respuesta",
            ])
            or ("pensar" in texto and any(v in texto for v in ["deja", "dejas", "para", "pare", "deten"]))
        ):
            self.proceso_id += 1
            self.procesando = False
            self.procesando_desde = 0.0
            self.procesando_tipo = ""
            self.responder("cancelé el procesamiento anterior y ya estoy disponible.", "normal")
            return

        # Control de Atlas queda después del orquestador: solo recibe órdenes
        # que realmente pertenecen a ventanas, aplicaciones, archivos o carpetas.
        if self._atlas_manejar_comando(original):
            return

        # 5.8) Spotify: abrir, buscar y controlar reproducción. Las órdenes
        # "reproduce música de X" sin plataforma explícita usan Spotify.
        orden_spotify = self.extraer_orden_spotify(original)
        if orden_spotify:
            accion_spotify, consulta_spotify = orden_spotify
            if accion_spotify == "abrir":
                self.abrir_spotify_inicio()
            elif accion_spotify == "buscar":
                self.buscar_en_spotify(consulta_spotify)
            elif accion_spotify == "reproducir":
                self.reproducir_spotify_async(consulta_spotify)
            elif accion_spotify == "reproducir_playlist":
                self.reproducir_playlist_spotify_async(consulta_spotify)
            elif accion_spotify == "abrir_playlist":
                self.abrir_playlist_spotify_async(consulta_spotify)
            elif accion_spotify == "listar_playlists":
                self.spotify_listar_playlists_async()
            elif accion_spotify == "reanudar":
                self.spotify_control_async("reanudar")
            elif accion_spotify == "pausar":
                self.spotify_control_async("pausar")
            elif accion_spotify == "siguiente":
                self.spotify_control_async("siguiente")
            elif accion_spotify == "anterior":
                self.spotify_control_async("anterior")
            elif accion_spotify == "preferencias":
                self.spotify_preferencias_async()
            elif accion_spotify == "reproducir_preferencias":
                self.reproducir_preferencias_spotify_async()
            return

        # 5.9) YouTube: abrir el sitio, buscar o reproducir el primer resultado.
        # Esta ruta va antes de Google y Ollama para evitar que una frase como
        # "busca en YouTube Luli Pampín" termine convertida en una búsqueda web
        # genérica o en una conversación con el modelo local.
        orden_youtube = self.extraer_orden_youtube(original)
        if orden_youtube:
            consulta_youtube, reproducir_youtube, solo_abrir_youtube = orden_youtube
            if solo_abrir_youtube:
                self.abrir_youtube_inicio()
            elif reproducir_youtube:
                self.reproducir_youtube_async(consulta_youtube)
            else:
                self.buscar_en_youtube(consulta_youtube)
            return

        # 6) Investigación web: Beta busca información actual y la conversa
        # utilizando Qwen local. Esto es distinto de abrir Google visualmente.
        consulta_investigacion = self.extraer_investigacion_web(original)
        if consulta_investigacion:
            self.investigar_internet_async(consulta_investigacion)
            return

        # Abrir una fuente de la última investigación.
        if self.manejar_comando_fuentes(texto):
            return

        # 6.5) Acciones locales seguras / navegación visual en Internet.
        # Una orden como "abre Google Chrome y busca diseños de muebles de madera"
        # abre directamente los resultados en pantalla. El contenido buscado se
        # codifica como URL; nunca se ejecuta como comando del sistema.
        busqueda_web = self.extraer_busqueda_web(original)
        if busqueda_web:
            consulta, modo_imagenes = busqueda_web
            self.buscar_en_chrome(consulta, modo_imagenes=modo_imagenes)
            return

        if "chrome" in texto and any(v in texto for v in ["abre", "abrir", "inicia"]):
            self.abrir_chrome()
            return

        if "calculadora" in texto and any(v in texto for v in ["abre", "abrir", "inicia"]):
            try:
                subprocess.Popen("calc.exe")
                self.responder("abriendo la calculadora.", "feliz")
            except Exception:
                self.responder("no pude abrir la calculadora.", "molesta")
            return

        if (
            ("bloc de notas" in texto or "notepad" in texto)
            and any(v in texto for v in ["abre", "abrir", "inicia"])
        ):
            try:
                subprocess.Popen("notepad.exe")
                self.responder("abriendo el bloc de notas.", "feliz")
            except Exception:
                self.responder("no pude abrirlo.", "molesta")
            return

        if "explorador" in texto and any(v in texto for v in ["abre", "abrir", "inicia"]):
            try:
                subprocess.Popen("explorer.exe")
                self.responder("abriendo el explorador.", "feliz")
            except Exception:
                self.responder("no pude abrir el explorador.", "molesta")
            return

        if any(frase in texto for frase in ["abre inicio", "menu inicio", "abrir inicio"]):
            self.abrir_inicio()
            return

        if texto.startswith("crea carpeta ") or texto.startswith("crear carpeta "):
            nombre = re.sub(
                r"^(crea|crear)\s+carpeta\s+",
                "",
                original,
                flags=re.IGNORECASE,
            )
            self.crear_carpeta(nombre)
            return

        # 7) Hora local del computador.
        # v3.2.1: `hora` debe ser una palabra independiente; "ahora" no es
        # una consulta horaria y debe continuar hacia el Workspace/Constructor.
        if self._es_consulta_hora(texto):
            self.responder(f"son las {time.strftime('%H:%M')}.", "normal")
            return

        # 8) Si parece una acción desconocida, NO dejamos que el modelo invente
        # comandos de Windows. Se muestra confusión.
        if any(
            texto.startswith(prefijo)
            for prefijo in [
                "abre ",
                "borra ",
                "elimina ",
                "mueve ",
                "copia ",
                "renombra ",
                "ejecuta ",
                "inicia ",
                "apaga ",
                "reinicia ",
                "programa un recordatorio",
                "guarda un recordatorio",
                "anota un recordatorio",
            ]
        ):
            self.no_entendi(texto, "no sé realizar esa acción todavía.")
            return

        # Beta v3.1.0: en la pestaña Proyecto / Chat, las preguntas no
        # capturadas por acciones explícitas se responden con los archivos del proyecto.
        if (
            self.modo_estudio_activo
            and self.proyecto_estudio_actual
            and self.aula_modo_principal == "proyecto"
        ):
            self.fallos_consecutivos = 0
            self.consultar_proyecto_estudio_async(original, desde_voz=True)
            return

        # 8.7) Seguimiento de una respuesta que combinó varias bibliotecas.
        if self.es_seguimiento_biblioteca_inteligente(original):
            self.fallos_consecutivos = 0
            self.conversar_contexto_inteligente_async(original)
            return

        # 8.8) Seguimiento técnico: si la respuesta anterior vino de un libro
        # técnico, mantenemos ese contexto antes de evaluar el RAG académico.
        if self.es_seguimiento_tecnico(original):
            self.fallos_consecutivos = 0
            self.conversar_contexto_tecnico_async(original)
            return

        # 8.9) Seguimiento robusto de una explicación basada en la biblioteca académica.
        if self.es_seguimiento_academico(original):
            self.fallos_consecutivos = 0
            self.conversar_contexto_academico_async(original)
            return

        # 8.10) Biblioteca inteligente: decide automáticamente entre libros
        # técnicos, apuntes académicos o una combinación de ambos.
        decision_biblioteca = self.decidir_ruta_biblioteca(original)
        ruta_biblioteca = decision_biblioteca.get("ruta", "qwen")
        if ruta_biblioteca == "tecnica":
            self.fallos_consecutivos = 0
            self.consultar_biblioteca_tecnica_async(original)
            return
        if ruta_biblioteca == "academica":
            self.fallos_consecutivos = 0
            self.consultar_biblioteca_async(original, decision=decision_biblioteca)
            return
        if ruta_biblioteca == "mixta":
            self.fallos_consecutivos = 0
            self.consultar_biblioteca_mixta_async(original, decision_biblioteca)
            return

        # Compatibilidad: una solicitud local explícita siempre se respeta, incluso
        # si por alguna razón el enrutador no pudo cargar el índice en ese instante.
        if self.parece_consulta_tecnica_programacion(original):
            self.fallos_consecutivos = 0
            self.consultar_biblioteca_tecnica_async(original)
            return
        if self.parece_consulta_academica(original) and any(
            x in normalizar(original) for x in [
                "mis apuntes", "mi material", "biblioteca academica", "segun el modulo"
            ]
        ):
            self.fallos_consecutivos = 0
            self.consultar_biblioteca_async(original)
            return

        # 9) Si venimos de una investigación reciente y el Señor hace una
        # pregunta de seguimiento, Qwen recibe ese contexto sin volver a buscar.
        if self.es_seguimiento_web(original):
            self.fallos_consecutivos = 0
            self.conversar_web_contexto_async(original)
            return

        # 10) Todo lo demás pasa al modelo local para conversación natural.
        self.fallos_consecutivos = 0
        self.conversar_ollama_async(original)

    def no_entendi(self, texto, mensaje):
        if texto == self.ultimo_no_entendido:
            self.fallos_consecutivos += 1
        else:
            self.ultimo_no_entendido = texto
            self.fallos_consecutivos = 1

        if self.fallos_consecutivos < 2:
            self.responder(mensaje, "confundida")
        else:
            self.responder("sigo sin entender esa petición.", "molesta")

    # ======================================================
    # CONTROL DE ATLAS v3.5.2
    # ======================================================

    def _atlas_quitar_wake(self, texto):
        t = normalizar(texto or "")
        t = re.sub(r"^(?:beta|veta|meta|metas|petra)\s+", "", t).strip()
        t = re.sub(r"^(?:por favor\s+)?(?:me\s+)?(?:puedes|podrias|podrias por favor)\s+", "", t).strip()
        # Continuadores conversacionales no cambian la intención operativa.
        t = re.sub(r"^(?:ahora|entonces|bien)\s+", "", t).strip()
        return t

    def _atlas_nombre_amigable_app(self, clave):
        nombres = {
            "spotify": "Spotify", "word": "Word", "excel": "Excel",
            "steam": "Steam", "explorador": "Explorador", "chrome": "Chrome",
            "notepad": "Bloc de notas", "calculadora": "Calculadora",
        }
        return nombres.get((clave or "").lower(), clave or "la ventana")

    def _atlas_normalizar_orden_operativa(self, texto):
        """Normaliza solo el pequeño vocabulario de control de Atlas.

        v3.5.2: esta capa es deliberadamente contextual. No modifica el texto
        general de la conversación ni alimenta a Ollama; únicamente ayuda al
        enrutador local a recuperar deformaciones frecuentes de Vosk/Whisper.
        """
        t = normalizar(texto or "")
        if not t:
            return ""

        # Casos reales observados en Atlas. Se aplican antes del análisis por
        # tokens porque Whisper puede fusionar verbo + aplicación.
        frases = [
            (r"\bmini\s*miss\s*award\b", "minimiza word"),
            (r"\bminimissaward\b", "minimiza word"),
            (r"\bmaximis\s+award\b", "maximiza word"),
            (r"\bmaximisa\s+word\b", "maximiza word"),
            (r"\bmaximisa\s+war\b", "maximiza word"),
            (r"\bserrar\s+word\b", "cierra word"),
            (r"\bsierra\s+word\b", "cierra word"),
            # Caso real de Whisper: "Beta, abre worth" -> "Veda Avery World".
            # Solo se corrige dentro del enrutador operativo de Atlas.
            (r"\b(?:veda\s+)?avery\s+world\b", "abre word"),
        ]
        for patron, reemplazo in frases:
            t = re.sub(patron, reemplazo, t)

        tokens = t.split()
        salida = []
        for tok in tokens:
            # Verbos operativos: toleramos deformaciones fonéticas conservando
            # prefijos distintivos para no tocar conversación normal.
            if tok in {"abres", "avres", "avre", "avery", "habre", "habres", "abreme"} or tok.startswith(("abr", "avr")) and difflib.SequenceMatcher(None, tok, "abre").ratio() >= 0.55:
                tok = "abre"
            elif tok.startswith("minim") and difflib.SequenceMatcher(None, tok, "minimiza").ratio() >= 0.55:
                tok = "minimiza"
            elif tok.startswith("maxim") and difflib.SequenceMatcher(None, tok, "maximiza").ratio() >= 0.55:
                tok = "maximiza"
            elif tok in {"sierra", "serrar", "serra", "cierrame"} or tok.startswith("cierr"):
                tok = "cierra"
            elif tok.startswith("restaur"):
                tok = "restaura"
            salida.append(tok)
        t = " ".join(salida)

        # Variantes de modo verbal frecuentes en órdenes de volumen. Se limitan
        # a frases que contienen "volumen" para no alterar conversación normal.
        if "volumen" in t:
            t = re.sub(r"\bsuba\b", "sube", t)
            t = re.sub(r"\bbaje\b", "baja", t)
            t = re.sub(r"\baumente\b", "aumenta", t)
            t = re.sub(r"\bdisminuya\b", "disminuye", t)

        # Alias de aplicaciones solo si la frase ya parece una orden operativa.
        contexto_control = bool(re.search(r"\b(?:abre|abrir|inicia|iniciar|pon|minimiza|maximiza|restaura|cierra)\b", t))
        if contexto_control:
            alias_frase = [
                ("spotify", ["espotifai", "es potifai", "potifai", "potifay", "potify", "esputifai", "es putifai", "espontifice", "es pontifice"]),
                ("word", ["worth", "work", "war", "world", "award", "a word", "a war"]),
                ("steam", ["estima", "estin", "stim"]),
            ]
            for canon, variantes in alias_frase:
                for variante in variantes:
                    if re.search(r"(?<!\w)" + re.escape(variante) + r"(?!\w)", t):
                        t = re.sub(r"(?<!\w)" + re.escape(variante) + r"(?!\w)", canon, t)
                        break
        return re.sub(r"\s+", " ", t).strip()

    def _atlas_normalizar_nombre_carpeta(self, nombre):
        """Recupera alias únicamente dentro del contexto de navegación."""
        n = normalizar(nombre or "").strip()
        clave = self._atlas_alias_ubicacion(n)
        return clave or n

    def _atlas_clave_nombre_carpeta(self, nombre):
        """Clave semántica para comparar nombres REALES con formas naturales.

        No modifica rutas ni inventa nombres. Solo permite reconocer que, por
        ejemplo, ``Primer Semestre``, ``1er Semestre`` y ``Semestre 1`` se
        refieren al mismo nombre lógico. La ruta física existente siempre gana.
        """
        n = normalizar(nombre or "").strip()
        n = re.sub(r"[_\-]+", " ", n)
        n = re.sub(r"\s+", " ", n).strip()
        ordinales = {
            "primer": "1", "primero": "1", "primera": "1", "1er": "1", "1ro": "1", "1ra": "1",
            "segundo": "2", "segunda": "2", "2do": "2", "2da": "2",
            "tercer": "3", "tercero": "3", "tercera": "3", "3ro": "3", "3ra": "3",
            "cuarto": "4", "cuarta": "4", "4to": "4", "4ta": "4",
            "quinto": "5", "quinta": "5", "5to": "5", "5ta": "5",
            "sexto": "6", "sexta": "6", "6to": "6", "6ta": "6",
            "septimo": "7", "septima": "7", "7mo": "7", "7ma": "7",
            "octavo": "8", "octava": "8", "8vo": "8", "8va": "8",
            "noveno": "9", "novena": "9", "9no": "9", "9na": "9",
            "decimo": "10", "decima": "10", "10mo": "10", "10ma": "10",
        }
        tokens = [ordinales.get(tok, tok) for tok in n.split()]
        # Normalizamos ``semestre 1`` y ``1 semestre`` a la misma forma.
        if "semestre" in tokens:
            nums = [x for x in tokens if x.isdigit()]
            otros = [x for x in tokens if x != "semestre" and not x.isdigit()]
            if nums:
                return "semestre " + nums[0] + ((" " + " ".join(otros)) if otros else "")
        return " ".join(tokens)

    def _atlas_nombres_carpeta_equivalentes(self, a, b):
        return bool(a and b and self._atlas_clave_nombre_carpeta(a) == self._atlas_clave_nombre_carpeta(b))

    def _atlas_raiz_confiable_para_ruta(self, ruta):
        """Devuelve la raíz confiable que contiene ``ruta`` sin inventar nada."""
        try:
            p = Path(ruta).resolve()
        except Exception:
            return None
        for info in (getattr(self, "atlas_ubicaciones_confiables", {}) or {}).values():
            try:
                raiz = Path(str(info.get("ruta") or "")).resolve()
                if not raiz.exists() or not raiz.is_dir():
                    continue
                if p == raiz or raiz in p.parents:
                    return raiz
            except Exception:
                continue
        return None

    def _atlas_buscar_hijos_directos(self, raiz, nombre):
        """Busca un nombre únicamente entre hijos reales de una carpeta real."""
        try:
            base = Path(raiz)
            if not base.exists() or not base.is_dir():
                return []
            buscado = normalizar(nombre or "").strip()
            exactos, parciales = [], []
            for p in base.iterdir():
                if not p.is_dir():
                    continue
                n = normalizar(p.name)
                if n == buscado or self._atlas_nombres_carpeta_equivalentes(p.name, buscado):
                    exactos.append(p)
                elif buscado and buscado in n:
                    parciales.append(p)
            return exactos or parciales
        except Exception:
            return []

    def _atlas_cargar_ubicaciones_confiables(self):
        """Carga un pequeño registro local de rutas conocidas de Atlas.

        Las ubicaciones predeterminadas son deliberadamente explícitas. No se
        usan para inferir datos personales; solo evitan búsquedas globales
        inseguras cuando el Señor nombra una carpeta conocida.
        """
        base = {
            "ipp": {
                "ruta": r"D:\IPP",
                "alias": ["ipp", "i pe pe", "ipepe", "y pepe", "y pe pe", "y pe", "i pepe", "ypepe"],
            },
            "beta": {
                "ruta": str(Path(BASE_DIR)),
                "alias": ["beta", "carpeta beta", "proyecto beta"],
            },
        }
        ruta_cfg = Path(BASE_DIR) / "ubicaciones_atlas.json"
        try:
            if ruta_cfg.exists():
                datos = json.loads(ruta_cfg.read_text(encoding="utf-8"))
                if isinstance(datos, dict):
                    for clave, valor in datos.items():
                        if isinstance(valor, dict) and valor.get("ruta"):
                            base[normalizar(clave)] = {
                                "ruta": str(valor.get("ruta")),
                                "alias": list(valor.get("alias") or [clave]),
                            }
        except Exception as error:
            print("CONTROL ATLAS: no pude leer ubicaciones_atlas.json:", error)
        return base

    def _atlas_alias_ubicacion(self, texto):
        n = normalizar(texto or "").strip()
        n = re.sub(r"^(?:la\s+)?carpeta\s+", "", n).strip()
        for clave, info in (getattr(self, "atlas_ubicaciones_confiables", {}) or {}).items():
            candidatos = [clave] + list(info.get("alias") or [])
            for alias in candidatos:
                a = normalizar(alias).strip()
                if n == a:
                    return clave
        return ""

    def _atlas_ruta_confiable(self, nombre):
        clave = self._atlas_alias_ubicacion(nombre)
        if not clave:
            return None
        info = (getattr(self, "atlas_ubicaciones_confiables", {}) or {}).get(clave) or {}
        ruta = Path(str(info.get("ruta") or ""))
        if str(ruta):
            return ruta
        return None

    def _atlas_separar_nombre_y_ubicacion(self, texto):
        """Separa el nombre de carpeta de calificadores de ubicación.

        Ej.: ``beta que se encuentra en el disco a`` -> (``beta``, ``A``)
        y ``ipp del escritorio`` -> (``ipp``, ``escritorio``).
        """
        t = normalizar(texto or "").strip()
        scope = ""
        # Disco/unidad explícita.
        m = re.search(r"\s+(?:que\s+se\s+encuentra\s+|que\s+esta\s+|ubicad[ao]\s+)?(?:en\s+)?(?:el\s+)?(?:disco|unidad)\s+([a-z])\b.*$", t)
        if m:
            scope = m.group(1).upper()
            t = t[:m.start()].strip()
        else:
            # Ubicaciones humanas frecuentes.
            for etiqueta, patron in [
                ("escritorio", r"\s+(?:en|del|de)\s+(?:el\s+)?escritorio\b.*$"),
                ("documentos", r"\s+(?:en|del|de)\s+(?:mis\s+)?documentos\b.*$"),
            ]:
                m = re.search(patron, t)
                if m:
                    scope = etiqueta
                    t = t[:m.start()].strip()
                    break
        t = re.sub(r"^(?:la\s+)?carpeta\s+", "", t).strip()
        return t, scope

    def _atlas_ruta_por_scope(self, nombre, scope):
        nombre = self._atlas_normalizar_nombre_carpeta(nombre)
        scope = (scope or "").strip()
        if not scope:
            return None
        if len(scope) == 1 and scope.isalpha():
            base = Path(scope.upper() + ":\\")
        elif scope == "escritorio":
            base = Path(obtener_escritorio())
        elif scope == "documentos":
            candidatos = [Path.home() / "Documents", Path.home() / "Documentos"]
            base = next((x for x in candidatos if x.exists()), candidatos[0])
        else:
            return None
        destino = base / nombre
        return destino

    def _atlas_ventana_explorador_por_ruta(self, ruta):
        """Localiza la ventana de Explorer que muestra exactamente ``ruta``."""
        if os.name != "nt":
            return None
        objetivo = os.path.normcase(os.path.normpath(str(Path(ruta))))
        script = (
            "$s=New-Object -ComObject Shell.Application; "
            "$s.Windows() | ForEach-Object { try { "
            "$p=$_.Document.Folder.Self.Path; "
            "if($p){ [PSCustomObject]@{HWND=[int64]$_.HWND;Path=$p;Name=$_.LocationName} } "
            "} catch {} } | ConvertTo-Json -Compress"
        )
        try:
            flags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
            r = subprocess.run(["powershell", "-NoProfile", "-Command", script], capture_output=True,
                               text=True, timeout=4, creationflags=flags)
            raw = (r.stdout or "").strip()
            if not raw:
                return None
            datos = json.loads(raw)
            if isinstance(datos, dict):
                datos = [datos]
            for item in datos or []:
                p = item.get("Path")
                if p and os.path.normcase(os.path.normpath(str(p))) == objetivo:
                    return {"hwnd": int(item.get("HWND") or 0), "titulo": item.get("Name") or Path(p).name,
                            "pid": 0, "proceso": "explorer.exe", "ruta": Path(p)}
        except Exception as error:
            print("CONTROL ATLAS: no pude localizar ventana Explorer por ruta:", error)
        return None

    def _atlas_controlar_carpeta_ventana(self, accion, nombre):
        limpio, scope = self._atlas_separar_nombre_y_ubicacion(nombre)
        ruta = self._atlas_ruta_confiable(limpio)
        if scope:
            explicita = self._atlas_ruta_por_scope(limpio, scope)
            if explicita and explicita.exists():
                ruta = explicita
        if not ruta and self.atlas_carpeta_actual:
            actual = Path(self.atlas_carpeta_actual)
            if self._atlas_nombres_carpeta_equivalentes(actual.name, limpio):
                ruta = actual
        if not ruta or not Path(ruta).exists():
            self.responder(f"no encontré una ubicación confiable para la carpeta {limpio}.", "confundida")
            return True
        ventana = self._atlas_ventana_explorador_por_ruta(ruta)
        if not ventana:
            self.responder(f"la carpeta {Path(ruta).name} existe, pero no encontré su ventana abierta.", "confundida")
            return True
        previa = self.atlas_ventana_usuario_previa
        try:
            self.atlas_ventana_usuario_previa = ventana
            return self._atlas_controlar_ventana(accion, "")
        finally:
            self.atlas_ventana_usuario_previa = previa

    def _atlas_extraer_porcentaje(self, texto):
        """Extrae un nivel absoluto 0..100 después de a/al/en.

        Acepta tanto dígitos como números hablados frecuentes: ``a un 50``,
        ``a cincuenta``, ``en treinta y cinco``. Devuelve None si la frase no
        expresa un destino absoluto, para conservar los cambios relativos.
        """
        t = normalizar(texto or "")
        m = re.search(r"\b(?:a|al|en)\s+(?:un\s+|el\s+)?(\d{1,3})\b", t)
        if m:
            n = int(m.group(1))
            return n if 0 <= n <= 100 else None

        unidades = {
            "cero":0, "uno":1, "una":1, "dos":2, "tres":3, "cuatro":4,
            "cinco":5, "seis":6, "siete":7, "ocho":8, "nueve":9,
        }
        especiales = {
            "diez":10, "once":11, "doce":12, "trece":13, "catorce":14,
            "quince":15, "dieciseis":16, "diecisiete":17, "dieciocho":18,
            "diecinueve":19, "veinte":20, "veintiuno":21, "veintidos":22,
            "veintitres":23, "veinticuatro":24, "veinticinco":25,
            "veintiseis":26, "veintisiete":27, "veintiocho":28, "veintinueve":29,
            "cien":100, "ciento":100,
        }
        decenas = {"treinta":30, "cuarenta":40, "cincuenta":50, "sesenta":60,
                   "setenta":70, "ochenta":80, "noventa":90}
        m = re.search(r"\b(?:a|al|en)\s+(.+)$", t)
        if not m:
            return None
        toks = m.group(1).split()[:5]
        while toks and toks[0] in {"un", "una", "el"}:
            toks.pop(0)
        if not toks:
            return None
        if toks[0] in especiales:
            return especiales[toks[0]]
        if toks[0] in decenas:
            n = decenas[toks[0]]
            if len(toks) >= 3 and toks[1] == "y" and toks[2] in unidades:
                n += unidades[toks[2]]
            return n
        if toks[0] in unidades:
            return unidades[toks[0]]
        return None

    def _atlas_detectar_app(self, texto):
        t = self._atlas_normalizar_orden_operativa(texto)
        alias = [
            ("spotify", ["spotify"]),
            ("word", ["word", "winword", "microsoft word"]),
            ("excel", ["excel", "microsoft excel"]),
            ("steam", ["steam"]),
            ("explorador", ["explorador", "explorador de archivos", "explorer"]),
            ("chrome", ["chrome", "google chrome"]),
            ("notepad", ["bloc de notas", "notepad"]),
            ("calculadora", ["calculadora", "calculator"]),
        ]
        for clave, nombres in alias:
            if any(re.search(r"(?<!\w)" + re.escape(n) + r"(?!\w)", t) for n in nombres):
                return clave
        return ""

    def _atlas_obtener_ventana_activa(self):
        if os.name != "nt":
            return None
        try:
            user32 = ctypes.windll.user32
            hwnd = int(user32.GetForegroundWindow())
            if not hwnd:
                return None
            largo = int(user32.GetWindowTextLengthW(hwnd))
            buf = ctypes.create_unicode_buffer(max(1, largo + 1))
            user32.GetWindowTextW(hwnd, buf, len(buf))
            pid = ctypes.c_ulong(0)
            user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
            proceso = ""
            try:
                import psutil
                proceso = psutil.Process(pid.value).name()
            except Exception:
                pass
            return {"hwnd": hwnd, "titulo": buf.value.strip(), "pid": int(pid.value), "proceso": proceso}
        except Exception:
            return None

    def _atlas_enumerar_ventanas(self):
        if os.name != "nt":
            return []
        ventanas = []
        try:
            user32 = ctypes.windll.user32
            callback_t = ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_void_p, ctypes.c_void_p)

            def callback(hwnd, _):
                try:
                    if not user32.IsWindowVisible(hwnd):
                        return True
                    largo = int(user32.GetWindowTextLengthW(hwnd))
                    if largo <= 0:
                        return True
                    buf = ctypes.create_unicode_buffer(largo + 1)
                    user32.GetWindowTextW(hwnd, buf, largo + 1)
                    titulo = buf.value.strip()
                    if not titulo:
                        return True
                    pid = ctypes.c_ulong(0)
                    user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
                    proceso = ""
                    try:
                        import psutil
                        proceso = psutil.Process(pid.value).name()
                    except Exception:
                        pass
                    ventanas.append({"hwnd": int(hwnd), "titulo": titulo, "pid": int(pid.value), "proceso": proceso})
                except Exception:
                    pass
                return True

            user32.EnumWindows(callback_t(callback), 0)
        except Exception as error:
            print("CONTROL ATLAS: no pude enumerar ventanas:", error)
        return ventanas

    def _atlas_ventanas_de_app(self, app):
        """Devuelve ventanas de una aplicación priorizando el proceso real.

        v3.5.2 evita elegir una ventana solo porque el título contiene una
        palabra parecida. Word/Spotify/etc. primero deben coincidir por proceso;
        el título queda como respaldo para aplicaciones UWP o casos sin psutil.
        """
        app = (app or "").lower()
        procesos = {
            "spotify": ["spotify.exe"],
            "word": ["winword.exe"],
            "excel": ["excel.exe"],
            "steam": ["steam.exe", "steamwebhelper.exe"],
            "explorador": ["explorer.exe"],
            "chrome": ["chrome.exe"],
            "notepad": ["notepad.exe"],
            "calculadora": ["calculatorapp.exe", "calculator.exe"],
        }.get(app, [])
        titulos = {
            "spotify": ["spotify"],
            "word": ["word"],
            "excel": ["excel"],
            "steam": ["steam"],
            "explorador": ["explorador de archivos", "file explorer"],
            "chrome": ["google chrome", "chrome"],
            "notepad": ["bloc de notas", "notepad"],
            "calculadora": ["calculadora", "calculator"],
        }.get(app, [app])
        por_proceso = []
        por_titulo = []
        for v in self._atlas_enumerar_ventanas():
            proc = normalizar(v.get("proceso") or "")
            titulo = normalizar(v.get("titulo") or "")
            if any(proc == normalizar(p) for p in procesos if p):
                por_proceso.append(v)
            elif any(re.search(r"(?<!\w)" + re.escape(normalizar(k)) + r"(?!\w)", titulo) for k in titulos if k):
                por_titulo.append(v)
        # Si conocemos al menos una ventana por el ejecutable, descartamos por
        # completo coincidencias débiles del título. Esto impide que VS Code,
        # una canción de Spotify o un documento cuyo título diga "Word" gane
        # por estar activo.
        return por_proceso if por_proceso else por_titulo

    def _atlas_controlar_ventana(self, accion, app=""):
        if os.name != "nt":
            self.responder("el control de ventanas solo está disponible en Atlas con Windows.", "confundida")
            return True

        objetivo = None
        if app:
            if app == "explorador" and getattr(self, "atlas_ultima_ruta_explorador", None):
                objetivo = self._atlas_ventana_explorador_por_ruta(self.atlas_ultima_ruta_explorador)
            if objetivo is None:
                coincidencias = self._atlas_ventanas_de_app(app)
                if coincidencias:
                    activa = self.atlas_ventana_usuario_previa or self._atlas_obtener_ventana_activa()
                    if activa:
                        objetivo = next((v for v in coincidencias if v["hwnd"] == activa.get("hwnd")), None)
                    objetivo = objetivo or coincidencias[0]
        else:
            objetivo = self.atlas_ventana_usuario_previa or self._atlas_obtener_ventana_activa()

        if not objetivo or not objetivo.get("hwnd"):
            nombre = self._atlas_nombre_amigable_app(app) if app else "esa ventana"
            self.responder(f"no encontré {nombre} abierto.", "confundida")
            return True

        try:
            hwnd = int(objetivo["hwnd"])
            user32 = ctypes.windll.user32
            if accion == "minimizar":
                user32.ShowWindow(hwnd, 6)
                time.sleep(0.05)
                ok = bool(user32.IsIconic(hwnd))
                verbo = "minimizada"
            elif accion == "maximizar":
                user32.ShowWindow(hwnd, 3)
                time.sleep(0.05)
                ok = bool(user32.IsZoomed(hwnd))
                verbo = "maximizada"
            elif accion == "restaurar":
                user32.ShowWindow(hwnd, 9)
                try:
                    user32.SetForegroundWindow(hwnd)
                except Exception:
                    pass
                time.sleep(0.05)
                ok = bool(user32.IsWindow(hwnd)) and not bool(user32.IsIconic(hwnd))
                verbo = "restaurada"
            elif accion == "cerrar":
                # WM_CLOSE es intencional: Word/Excel conservan su diálogo nativo
                # de guardado. Confirmamos que Windows aceptó el mensaje, pero no
                # afirmamos que la ventana ya desapareció si hay cambios pendientes.
                ok = bool(user32.PostMessageW(hwnd, 0x0010, 0, 0))
                verbo = "cerrando"
            else:
                return False
            if not ok:
                raise RuntimeError("Windows no confirmó la acción")
            self.atlas_ultima_ventana = objetivo
            if app:
                self.atlas_ultima_aplicacion = app
            nombre = self._atlas_nombre_amigable_app(app) if app else (objetivo.get("titulo") or "Ventana")
            if accion == "cerrar":
                self.responder(f"cerrando {nombre}; si hay cambios sin guardar, la aplicación pedirá confirmación.", "normal")
            else:
                self.responder(f"{nombre} {verbo}.", "normal")
            print(f"CONTROL ATLAS v3.5.2: ventana {accion} hwnd={hwnd} titulo={objetivo.get('titulo','')!r}")
        except Exception as error:
            print("CONTROL ATLAS: error controlando ventana:", error)
            self.responder("no pude realizar esa acción sobre la ventana.", "molesta")
        return True

    def _atlas_ruta_app_registro(self, exe):
        if os.name != "nt":
            return None
        try:
            import winreg
            for raiz in (winreg.HKEY_CURRENT_USER, winreg.HKEY_LOCAL_MACHINE):
                for prefijo in (r"Software\Microsoft\Windows\CurrentVersion\App Paths",
                                r"Software\WOW6432Node\Microsoft\Windows\CurrentVersion\App Paths"):
                    try:
                        with winreg.OpenKey(raiz, prefijo + "\\" + exe) as key:
                            valor, _ = winreg.QueryValueEx(key, None)
                            p = Path(str(valor).strip('"'))
                            if p.exists():
                                return p
                    except OSError:
                        continue
        except Exception:
            pass
        return None

    def _atlas_abrir_aplicacion(self, app):
        app = (app or "").lower()
        nombre = self._atlas_nombre_amigable_app(app)
        if os.name != "nt":
            self.responder("la apertura de aplicaciones de Atlas requiere Windows.", "confundida")
            return True
        try:
            if app == "spotify":
                # En modo Control Atlas nunca caemos a la web si existe/esperamos
                # la aplicación local. El URI spotify: lo registra la app instalada.
                try:
                    os.startfile("spotify:")
                except Exception:
                    local = Path(os.environ.get("APPDATA", "")) / "Spotify" / "Spotify.exe"
                    if not local.exists():
                        raise FileNotFoundError("Spotify local no encontrado")
                    subprocess.Popen([str(local)])
            elif app == "explorador":
                subprocess.Popen(["explorer.exe"])
            elif app == "notepad":
                subprocess.Popen(["notepad.exe"])
            elif app == "calculadora":
                subprocess.Popen(["calc.exe"])
            elif app == "chrome":
                ruta = self.obtener_ruta_chrome()
                if not ruta:
                    raise FileNotFoundError("Chrome no encontrado")
                subprocess.Popen([ruta])
            elif app in {"word", "excel"}:
                exe = "WINWORD.EXE" if app == "word" else "EXCEL.EXE"
                ruta = self._atlas_ruta_app_registro(exe)
                if not ruta:
                    ruta_which = shutil.which(exe)
                    ruta = Path(ruta_which) if ruta_which else None
                if not ruta:
                    raise FileNotFoundError(f"{nombre} no encontrado")
                subprocess.Popen([str(ruta)])
            elif app == "steam":
                steam = None
                try:
                    import winreg
                    for raiz, clave in [
                        (winreg.HKEY_CURRENT_USER, r"Software\Valve\Steam"),
                        (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\WOW6432Node\Valve\Steam"),
                    ]:
                        try:
                            with winreg.OpenKey(raiz, clave) as k:
                                for campo in ("SteamExe", "InstallPath"):
                                    try:
                                        valor, _ = winreg.QueryValueEx(k, campo)
                                        candidato = Path(valor) if campo == "SteamExe" else Path(valor) / "steam.exe"
                                        if candidato.exists():
                                            steam = candidato
                                            break
                                    except OSError:
                                        continue
                            if steam:
                                break
                        except OSError:
                            continue
                except Exception:
                    pass
                if not steam:
                    for candidato in [
                        Path(os.environ.get("ProgramFiles(x86)", "")) / "Steam" / "steam.exe",
                        Path(os.environ.get("ProgramFiles", "")) / "Steam" / "steam.exe",
                    ]:
                        if candidato.exists():
                            steam = candidato
                            break
                if not steam:
                    raise FileNotFoundError("Steam local no encontrado")
                subprocess.Popen([str(steam)])
            else:
                return False
            self.atlas_ultima_aplicacion = app
            self.responder(f"abriendo {nombre}.", "feliz")
            print(f"CONTROL ATLAS v3.5.2: aplicación abierta={app}")
        except Exception as error:
            print(f"CONTROL ATLAS: no pude abrir {app}:", error)
            self.responder(f"no pude encontrar o abrir {nombre} en Atlas.", "molesta")
        return True

    def _atlas_ruta_explorador_activa(self):
        if os.name != "nt":
            return None
        ventana = self.atlas_ventana_usuario_previa or self._atlas_obtener_ventana_activa()
        if not ventana or not ventana.get("hwnd"):
            return None
        hwnd = int(ventana["hwnd"])
        script = (
            "$s=New-Object -ComObject Shell.Application; "
            f"$w=$s.Windows() | Where-Object {{ [int64]$_.HWND -eq {hwnd} }} | Select-Object -First 1; "
            "if($w){$w.Document.Folder.Self.Path}"
        )
        try:
            flags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
            r = subprocess.run(["powershell", "-NoProfile", "-Command", script],
                               capture_output=True, text=True, timeout=3, creationflags=flags)
            valor = (r.stdout or "").strip().splitlines()
            if valor:
                p = Path(valor[-1].strip())
                if p.exists() and p.is_dir():
                    return p
        except Exception:
            pass
        return None

    def _atlas_raices_busqueda(self):
        """Raíces seguras para búsquedas ordinarias.

        v3.5.2 deja de recorrer ``Path.home()`` y la raíz de A: por defecto.
        Eso evita falsos positivos dentro de .m2, .vscode, caches y repositorios.
        """
        raices = []
        activa = self._atlas_ruta_explorador_activa()
        if activa:
            self.atlas_carpeta_actual = activa
        for p in [self.atlas_carpeta_actual, obtener_escritorio(), Path.home() / "Documents",
                  Path.home() / "Documentos", Path.home() / "OneDrive"]:
            if p and Path(p).exists():
                pp = Path(p)
                if pp not in raices:
                    raices.append(pp)
        return raices

    def _atlas_buscar_elementos(self, nombre, tipo="cualquiera", extensiones=None):
        buscado = normalizar(nombre or "").strip()
        if not buscado:
            return []
        extensiones = {e.lower() for e in (extensiones or [])}
        if tipo == "carpeta":
            confiable = self._atlas_ruta_confiable(buscado)
            if confiable and confiable.exists():
                return [confiable]
        omitir = {"appdata", "$recycle.bin", "system volume information", ".git", ".m2", ".vscode",
                  ".cache", ".gradle", ".npm", "node_modules", "windows", "program files", "program files (x86)"}
        exactos, parciales = [], []
        vistos = set()
        max_nodos = 7000
        nodos = 0

        def aceptar(p):
            if tipo == "carpeta" and not p.is_dir():
                return False
            if tipo == "archivo" and not p.is_file():
                return False
            if extensiones and p.is_file() and p.suffix.lower() not in extensiones:
                return False
            return True

        # Primero hijos directos de la carpeta contextual: la conversación tiene
        # prioridad sobre búsquedas globales.
        raices = self._atlas_raices_busqueda()
        # v3.5.2: si estamos dentro de una subcarpeta de una ubicación
        # confiable (por ejemplo D:\IPP\1er Semestre), una carpeta hermana
        # como "Segundo Semestre" se busca también en su padre inmediato.
        # Esto solo se aplica a CARPETAS y nunca habilita una búsqueda global.
        if tipo == "carpeta" and self.atlas_carpeta_actual:
            try:
                actual_ctx = Path(self.atlas_carpeta_actual)
                raiz_conf = self._atlas_raiz_confiable_para_ruta(actual_ctx)
                padre = actual_ctx.parent
                if raiz_conf and padre.exists() and padre.is_dir() and (padre == raiz_conf or raiz_conf in padre.parents):
                    if padre not in raices:
                        raices.insert(1 if raices else 0, padre)
            except Exception:
                pass
        for raiz in raices:
            try:
                for p in raiz.iterdir():
                    if not aceptar(p):
                        continue
                    n = normalizar(p.stem if p.is_file() else p.name)
                    if n == buscado or (p.is_dir() and self._atlas_nombres_carpeta_equivalentes(p.name, buscado)):
                        exactos.append(p)
                    elif buscado in n:
                        parciales.append(p)
            except Exception:
                pass
            if exactos:
                return list(dict.fromkeys(exactos))[:12]
            # Solo la primera raíz (contextual) recibe prioridad de coincidencias
            # parciales directas.
            if parciales:
                return list(dict.fromkeys(parciales))[:12]

        for raiz in raices:
            cola = [(raiz, 0)]
            while cola and nodos < max_nodos:
                actual, profundidad = cola.pop(0)
                try:
                    hijos = list(actual.iterdir())
                except Exception:
                    continue
                for p in hijos:
                    nodos += 1
                    if nodos >= max_nodos:
                        break
                    try:
                        if str(p).lower() in vistos:
                            continue
                        vistos.add(str(p).lower())
                        n = normalizar(p.stem if p.is_file() else p.name)
                        if aceptar(p):
                            if n == buscado or (p.is_dir() and self._atlas_nombres_carpeta_equivalentes(p.name, buscado)):
                                exactos.append(p)
                            elif buscado in n or difflib.SequenceMatcher(None, buscado, n).ratio() >= 0.86:
                                parciales.append(p)
                        oculto_tecnico = p.is_dir() and (p.name.startswith(".") or normalizar(p.name) in omitir)
                        if p.is_dir() and profundidad < 4 and not oculto_tecnico:
                            cola.append((p, profundidad + 1))
                    except Exception:
                        continue
            if exactos:
                break
        return list(dict.fromkeys(exactos or parciales))[:12]


    def _atlas_nombre_carpeta_valido(self, nombre):
        """Evita que fragmentos incompletos disparen búsquedas arbitrarias."""
        limpio, _scope = self._atlas_separar_nombre_y_ubicacion(nombre)
        n = self._atlas_normalizar_nombre_carpeta(limpio)
        n = normalizar(n or "").strip(" .")
        if not n:
            return False
        stop = {
            "de", "del", "la", "el", "una", "un", "carpeta", "archivo",
            "documento", "esto", "eso", "aqui", "ahi",
        }
        if n in stop:
            return False
        # Un solo carácter suele ser un residuo de ASR, no un nombre fiable.
        if len(n) < 2 and not n.isdigit():
            return False
        return True

    def _atlas_resolver_carpeta_real(self, nombre):
        """Devuelve únicamente rutas de carpetas que existen realmente.

        Respeta ubicación confiable, alcance explícito y después contexto/raíces
        seguras. Nunca inventa una ruta ni consulta a Ollama.
        """
        # Los helpers internos pueden pasar una ruta ya verificada. Si existe
        # físicamente, se acepta directamente; jamás se construye una ruta a
        # partir de texto libre en este punto.
        try:
            directo = Path(str(nombre))
            if directo.exists() and directo.is_dir():
                return [directo]
        except Exception:
            pass
        limpio, scope = self._atlas_separar_nombre_y_ubicacion(nombre)
        limpio = self._atlas_normalizar_nombre_carpeta(limpio)
        n = normalizar(limpio or "").strip()

        if n in {"esta", "actual", "esta carpeta", "carpeta actual", "aqui"}:
            activa = self._atlas_ruta_explorador_activa() or self.atlas_carpeta_actual
            p = Path(activa) if activa else None
            return [p] if p and p.exists() and p.is_dir() else []

        if not self._atlas_nombre_carpeta_valido(limpio):
            return []

        confiable = self._atlas_ruta_confiable(limpio)
        if confiable and confiable.exists() and confiable.is_dir() and not scope:
            return [Path(confiable)]

        if scope:
            destino = self._atlas_ruta_por_scope(limpio, scope)
            if destino and destino.exists() and destino.is_dir():
                return [Path(destino)]
            return []

        # Si el contexto actual ya es la carpeta nombrada, no volvemos a buscar.
        actual = self.atlas_carpeta_actual
        if actual:
            pactual = Path(actual)
            if pactual.exists() and pactual.is_dir() and (normalizar(pactual.name) == n or self._atlas_nombres_carpeta_equivalentes(pactual.name, limpio)):
                return [pactual]

        return [Path(p) for p in self._atlas_buscar_elementos(limpio, tipo="carpeta") if Path(p).exists() and Path(p).is_dir()]

    def _atlas_ubicar_carpeta_por_nombre(self, nombre):
        """Informa rutas verificadas sin abrir ni inventar ubicaciones."""
        if not self._atlas_nombre_carpeta_valido(nombre):
            self.responder("necesito el nombre de la carpeta que quiere ubicar.", "confundida")
            return True
        rutas = self._atlas_resolver_carpeta_real(nombre)
        if not rutas:
            limpio, _ = self._atlas_separar_nombre_y_ubicacion(nombre)
            self.responder(f"no encontré una carpeta real llamada {limpio} en el contexto y ubicaciones seguras.", "confundida")
            print(f"CONTROL ATLAS v3.5.2: ubicación no encontrada para {limpio!r}; sin fallback a Ollama.")
            return True
        if len(rutas) == 1:
            p = rutas[0]
            self.atlas_ultima_ruta_referida = p
            self.responder(f"la carpeta {p.name} está en {p}.", "normal")
            print(f"CONTROL ATLAS v3.5.2: ubicación verificada={p}")
            return True
        detalles = "; ".join(f"{i}, {p}" for i, p in enumerate(rutas[:6], 1))
        self.responder(f"encontré varias carpetas reales con ese nombre: {detalles}. Indique una ubicación más específica.", "confundida")
        print(f"CONTROL ATLAS v3.5.2: múltiples ubicaciones verificadas={rutas[:6]}")
        return True

    def _atlas_listar_contenido_carpeta(self, nombre):
        """Lista contenido real del sistema de archivos; nunca usa generación."""
        if not self._atlas_nombre_carpeta_valido(nombre):
            self.responder("necesito saber qué carpeta quiere revisar.", "confundida")
            return True
        rutas = self._atlas_resolver_carpeta_real(nombre)
        if not rutas:
            limpio, _ = self._atlas_separar_nombre_y_ubicacion(nombre)
            self.responder(f"no encontré una carpeta real llamada {limpio} para revisar su contenido.", "confundida")
            print(f"CONTROL ATLAS v3.5.2: contenido no disponible; carpeta inexistente {limpio!r}.")
            return True
        if len(rutas) > 1:
            detalles = "; ".join(f"{i}, {p}" for i, p in enumerate(rutas[:6], 1))
            self.responder(f"encontré varias carpetas reales con ese nombre: {detalles}. Indique cuál quiere revisar.", "confundida")
            return True

        ruta = rutas[0]
        try:
            hijos = sorted(list(ruta.iterdir()), key=lambda p: (not p.is_dir(), normalizar(p.name)))
        except Exception as error:
            print(f"CONTROL ATLAS v3.5.2: no pude leer {ruta}: {error}")
            self.responder(f"encontré {ruta.name}, pero Windows no me permitió leer su contenido.", "molesta")
            return True

        carpetas = [p.name for p in hijos if p.is_dir()]
        archivos = [p.name for p in hijos if p.is_file()]
        self.atlas_ultima_ruta_referida = ruta
        # Mostrar/revisar explícitamente una carpeta cambia el CONTEXTO
        # conversacional de navegación, aunque Windows no abra otra ventana.
        # Así, después de "muéstrame el contenido de IPP", "abre Segundo
        # Semestre" se resuelve dentro de D:\IPP y no dentro del 1er semestre.
        self.atlas_carpeta_actual = ruta

        if not hijos:
            self.responder(f"la carpeta {ruta.name} está vacía.", "normal")
            print(f"CONTROL ATLAS v3.5.2: contenido verificado {ruta}: vacío")
            return True

        partes = [f"en {ruta.name} encontré {len(carpetas)} carpeta{'s' if len(carpetas) != 1 else ''} y {len(archivos)} archivo{'s' if len(archivos) != 1 else ''}"]
        if carpetas:
            muestra = ", ".join(carpetas[:8])
            if len(carpetas) > 8:
                muestra += f", y {len(carpetas)-8} más"
            partes.append("carpetas: " + muestra)
        if archivos:
            muestra = ", ".join(archivos[:8])
            if len(archivos) > 8:
                muestra += f", y {len(archivos)-8} más"
            partes.append("archivos: " + muestra)
        self.responder(". ".join(partes) + ".", "normal")
        print(f"CONTROL ATLAS v3.5.2: contenido verificado={ruta} carpetas={len(carpetas)} archivos={len(archivos)}")
        return True

    def _atlas_abrir_ruta(self, ruta, tipo=""):
        try:
            p = Path(ruta)
            if not p.exists():
                raise FileNotFoundError(str(p))
            os.startfile(str(p))
            if p.is_dir():
                anterior = self.atlas_carpeta_actual
                if anterior and Path(anterior) != p:
                    self.atlas_historial_carpetas.append(Path(anterior))
                    self.atlas_historial_carpetas = self.atlas_historial_carpetas[-20:]
                self.atlas_carpeta_actual = p
                self.atlas_ultima_ruta_explorador = p
                self.atlas_ultima_aplicacion = "explorador"
                self.responder(f"abriendo {p.name or str(p)}.", "feliz")
            else:
                self.atlas_ultimo_archivo = p
                self.responder(f"abriendo {p.name}.", "feliz")
            print(f"CONTROL ATLAS v3.5.2: ruta abierta={p}")
        except Exception as error:
            print("CONTROL ATLAS: no pude abrir ruta:", error)
            self.responder("no pude abrir ese elemento.", "molesta")
        return True

    def _atlas_ofrecer_coincidencias(self, rutas, tipo):
        rutas = [Path(p) for p in rutas]
        if not rutas:
            return False
        if len(rutas) == 1:
            return self._atlas_abrir_ruta(rutas[0], tipo)
        self.atlas_opciones_pendientes = rutas[:6]
        self.atlas_tipo_opciones_pendientes = tipo
        self.atlas_opciones_hasta = time.time() + 25.0
        partes = []
        for i, p in enumerate(self.atlas_opciones_pendientes, 1):
            # Dos niveles de contexto suelen ser más útiles que solo el padre
            # inmediato (p. ej. "cl" / "edu"). No se inventan rutas.
            padres = [x.name for x in list(p.parents)[:2] if x.name]
            contexto = " / ".join(reversed(padres)) if padres else str(p.parent)
            partes.append(f"{i}, {p.name}, en {contexto}")
        self.responder("encontré varias coincidencias: " + "; ".join(partes) + ". Dígame el número que quiere abrir.", "confundida")
        return True

    def _atlas_resolver_opcion_pendiente(self, texto):
        if not self.atlas_opciones_pendientes:
            return False
        limite = float(getattr(self, "atlas_opciones_hasta", 0.0) or 0.0)
        if limite and time.time() > limite:
            self.atlas_opciones_pendientes = []
            self.atlas_tipo_opciones_pendientes = ""
            self.atlas_opciones_hasta = 0.0
            return False
        t = self._atlas_quitar_wake(texto)
        numeros = {"1":1, "uno":1, "primera":1, "primero":1, "2":2, "dos":2, "segunda":2, "segundo":2,
                   "3":3, "tres":3, "tercera":3, "tercero":3, "4":4, "cuatro":4, "cuarta":4,
                   "5":5, "cinco":5, "quinta":5, "6":6, "seis":6, "sexta":6}
        elegido = None
        for token, numero in numeros.items():
            if re.search(r"(?<!\w)" + re.escape(token) + r"(?!\w)", t):
                elegido = numero
                break
        if elegido and 1 <= elegido <= len(self.atlas_opciones_pendientes):
            ruta = self.atlas_opciones_pendientes[elegido - 1]
            tipo = self.atlas_tipo_opciones_pendientes
            self.atlas_opciones_pendientes = []
            self.atlas_tipo_opciones_pendientes = ""
            self.atlas_opciones_hasta = 0.0
            return self._atlas_abrir_ruta(ruta, tipo)
        if any(x in t for x in ["cancela", "ninguna", "ninguno", "dejalo"]):
            self.atlas_opciones_pendientes = []
            self.atlas_tipo_opciones_pendientes = ""
            self.atlas_opciones_hasta = 0.0
            self.responder("cancelado.", "normal")
            return True
        return False

    def _atlas_extraer_nombre(self, original, tipo):
        t = self._atlas_quitar_wake(original)
        if tipo == "carpeta":
            patrones = [
                r"^(?:abre|abrir|entra a|entra en|ve a|ir a)\s+(?:la\s+)?carpeta\s+(.+)$",
                r"^(?:abre|abrir|entra a|entra en|ve a|ir a)\s+(.+)$",
            ]
        else:
            patrones = [
                r"^(?:abre|abrir|busca|buscar|encuentra|localiza)\s+(?:el\s+)?(?:archivo|documento)\s+(.+)$",
                r"^(?:abre|abrir|busca|buscar|encuentra|localiza)\s+(?:el\s+)?(?:word|excel|pdf)\s+(?:llamado|llamada|de)?\s*(.+)$",
            ]
        for patron in patrones:
            m = re.match(patron, t)
            if m:
                nombre = m.group(1).strip()
                # Conservamos el calificador para que el resolvedor pueda distinguir
                # "Beta en el disco A" de un nombre literal larguísimo.
                return nombre
        return ""

    def _atlas_abrir_carpeta_por_nombre(self, nombre):
        limpio, scope = self._atlas_separar_nombre_y_ubicacion(nombre)
        limpio = self._atlas_normalizar_nombre_carpeta(limpio)

        if not self._atlas_nombre_carpeta_valido(limpio):
            self.responder("necesito el nombre exacto de la carpeta que quiere abrir.", "confundida")
            print(f"CONTROL ATLAS v3.5.2: búsqueda de carpeta bloqueada por nombre incompleto: {nombre!r}")
            return True

        # 1) Una ubicación confiable gana siempre frente a búsquedas globales.
        confiable = self._atlas_ruta_confiable(limpio)
        if confiable and confiable.exists() and not scope:
            print(f"CONTROL ATLAS v3.5.2: ubicación confiable {limpio} -> {confiable}")
            return self._atlas_abrir_ruta(confiable, "carpeta")

        # 2) Si el Señor nombró una unidad/Escritorio/Documentos, respetamos ese
        # alcance exacto y no buscamos en otras ubicaciones.
        if scope:
            destino = self._atlas_ruta_por_scope(limpio, scope)
            if destino and destino.exists() and destino.is_dir():
                return self._atlas_abrir_ruta(destino, "carpeta")
            self.responder(f"no encontré la carpeta {limpio} en la ubicación indicada.", "confundida")
            return True

        # 3) Solo después usamos las raíces seguras/contextuales.
        coincidencias = self._atlas_buscar_elementos(limpio, tipo="carpeta")
        if not coincidencias:
            actual = self.atlas_carpeta_actual
            sugerencias = []
            try:
                if actual and Path(actual).exists() and Path(actual).is_dir():
                    sugerencias = [p.name for p in Path(actual).iterdir() if p.is_dir()][:8]
            except Exception:
                sugerencias = []
            if sugerencias:
                self.responder(
                    f"no encontré una carpeta llamada {limpio} dentro del contexto actual {Path(actual).name}. "
                    f"Las carpetas reales que veo allí incluyen: {', '.join(sugerencias)}.",
                    "confundida",
                )
            else:
                self.responder(f"no encontré una carpeta llamada {limpio} en las ubicaciones seguras que revisé.", "confundida")
            print(f"CONTROL ATLAS v3.5.2: carpeta no encontrada={limpio!r}; sin fallback a Ollama.")
            return True
        return self._atlas_ofrecer_coincidencias(coincidencias, "carpeta")

    def _atlas_abrir_archivo_por_nombre(self, nombre, tipo_archivo=""):
        extensiones = None
        if tipo_archivo == "word":
            extensiones = {".doc", ".docx", ".docm"}
        elif tipo_archivo == "excel":
            extensiones = {".xls", ".xlsx", ".xlsm", ".xlsb"}
        elif tipo_archivo == "pdf":
            extensiones = {".pdf"}
        coincidencias = self._atlas_buscar_elementos(nombre, tipo="archivo", extensiones=extensiones)
        if not coincidencias:
            self.responder(f"no encontré un archivo que coincida con {nombre}.", "confundida")
            return True
        return self._atlas_ofrecer_coincidencias(coincidencias, "archivo")

    def _atlas_volver_carpeta(self):
        if self.atlas_historial_carpetas:
            destino = self.atlas_historial_carpetas.pop()
            # Evita volver a agregar el origen al historial durante esta apertura.
            actual = self.atlas_carpeta_actual
            self.atlas_carpeta_actual = None
            resultado = self._atlas_abrir_ruta(destino, "carpeta")
            if actual and self.atlas_historial_carpetas and self.atlas_historial_carpetas[-1] == actual:
                self.atlas_historial_carpetas.pop()
            return resultado
        activa = self._atlas_ruta_explorador_activa()
        if activa and activa.parent != activa:
            self.atlas_carpeta_actual = activa
            return self._atlas_abrir_ruta(activa.parent, "carpeta")
        self.responder("no tengo una carpeta anterior en el contexto actual.", "confundida")
        return True

    def _atlas_crear_carpeta_contextual(self, nombre):
        limpio = re.sub(r'[<>:"/\\|?*]', "", (nombre or "")).strip(" .")
        if not limpio:
            self.responder("necesito un nombre válido para la carpeta.", "confundida")
            return True
        base = self._atlas_ruta_explorador_activa() or self.atlas_carpeta_actual or obtener_escritorio()
        destino = Path(base) / limpio
        try:
            if destino.exists():
                self.responder(f"la carpeta {limpio} ya existe en {Path(base).name or str(base)}.", "confundida")
                return True
            destino.mkdir(parents=False)
            self.atlas_carpeta_actual = Path(base)
            self.responder(f"carpeta {limpio} creada.", "feliz")
            print(f"CONTROL ATLAS v3.5.2: carpeta creada={destino}")
        except Exception as error:
            print("CONTROL ATLAS: no pude crear carpeta:", error)
            self.responder("no pude crear esa carpeta.", "molesta")
        return True

    # ======================================================
    # CONTROL DE ARCHIVOS SEGURO v3.5.2
    # ======================================================

    def _atlas_base_operacion_archivos(self):
        """Carpeta real sobre la que operan crear/renombrar/copiar/mover.

        La ruta activa del Explorador tiene prioridad. Si no puede verificarse,
        se usa el contexto operativo ya verificado y finalmente el Escritorio.
        """
        activa = self._atlas_ruta_explorador_activa()
        if activa and Path(activa).exists() and Path(activa).is_dir():
            self.atlas_carpeta_actual = Path(activa)
            return Path(activa)
        if self.atlas_carpeta_actual and Path(self.atlas_carpeta_actual).exists():
            return Path(self.atlas_carpeta_actual)
        return Path(obtener_escritorio())

    def _atlas_nombre_windows_seguro(self, nombre, extension=""):
        nombre = (nombre or "").strip().strip('"').strip("'")
        nombre = re.sub(r'[<>:"/\\|?*]', "", nombre).strip(" .")
        if not nombre:
            return ""
        reservados = {"CON","PRN","AUX","NUL",*(f"COM{i}" for i in range(1,10)),*(f"LPT{i}" for i in range(1,10))}
        raiz = nombre.split(".",1)[0].upper()
        if raiz in reservados:
            return ""
        if extension and not nombre.lower().endswith(extension.lower()):
            nombre += extension
        return nombre[:180]

    def _atlas_es_ruta_protegida(self, ruta):
        try:
            p = Path(ruta).resolve()
        except Exception:
            return True
        protegidas = []
        try:
            beta_root = Path(BASE_DIR).resolve()
            # Beta no administra destructivamente su propia instalación.
            if p == beta_root or beta_root in p.parents:
                return True
            protegidas.append(beta_root)
        except Exception:
            pass
        for info in (getattr(self, "atlas_ubicaciones_confiables", {}) or {}).values():
            try:
                q = Path(str(info.get("ruta") or "")).resolve()
                if q.exists():
                    protegidas.append(q)
            except Exception:
                pass
        # Para otras ubicaciones confiables (por ejemplo D:\IPP) solo se
        # protege la raíz; sus subcarpetas sí pueden administrarse con las
        # confirmaciones correspondientes.
        return any(p == q for q in protegidas)

    def _atlas_elemento_contextual(self, referencia, tipo="cualquiera"):
        r = normalizar(referencia or "").strip()
        base = self._atlas_base_operacion_archivos()
        if r in {"esta carpeta","la carpeta","carpeta actual","esta","actual"}:
            return base if base.exists() and base.is_dir() else None
        if r in {"este archivo","el archivo","archivo actual","ultimo archivo","ultimo"}:
            p = Path(self.atlas_ultimo_archivo) if self.atlas_ultimo_archivo else None
            return p if p and p.exists() and p.is_file() else None
        # Ruta literal existente.
        try:
            p = Path(referencia)
            if p.exists() and (tipo == "cualquiera" or (tipo == "archivo" and p.is_file()) or (tipo == "carpeta" and p.is_dir())):
                return p
        except Exception:
            pass
        # Primero hijos directos del contexto: evita búsquedas globales para
        # operaciones que podrían modificar datos.
        candidatos=[]
        try:
            for p in base.iterdir():
                if tipo == "archivo" and not p.is_file():
                    continue
                if tipo == "carpeta" and not p.is_dir():
                    continue
                buscado = normalizar(referencia or "")
                n = normalizar(p.stem if p.is_file() else p.name)
                n_completo = normalizar(p.name)
                if n == buscado or n_completo == buscado or (p.is_dir() and self._atlas_nombres_carpeta_equivalentes(p.name, referencia)):
                    candidatos.append(p)
        except Exception:
            pass
        return candidatos[0] if len(candidatos) == 1 else None

    def _atlas_destino_carpeta(self, referencia):
        r = normalizar(referencia or "").strip()
        if r in {"aqui","aqui mismo","esta carpeta","carpeta actual"}:
            return self._atlas_base_operacion_archivos()
        confiable = self._atlas_ruta_confiable(referencia)
        if confiable and Path(confiable).exists() and Path(confiable).is_dir():
            return Path(confiable)
        p = self._atlas_elemento_contextual(referencia, "carpeta")
        return Path(p) if p and Path(p).is_dir() else None

    def _atlas_solicitar_confirmacion(self, accion, datos, mensaje):
        self.atlas_confirmacion_pendiente = {"accion": accion, "datos": datos}
        self.atlas_confirmacion_hasta = time.time() + 30.0
        self.responder(mensaje + " ¿Confirma?", "confundida")
        print(f"CONTROL ATLAS v3.5.2: confirmación requerida accion={accion}")
        return True

    def _atlas_resolver_confirmacion_pendiente(self, texto):
        pendiente = getattr(self, "atlas_confirmacion_pendiente", None)
        if not pendiente:
            return False
        if time.time() > float(getattr(self, "atlas_confirmacion_hasta", 0.0) or 0.0):
            self.atlas_confirmacion_pendiente = None
            self.atlas_confirmacion_hasta = 0.0
            return False
        t = self._atlas_quitar_wake(texto)
        if t in {"no","cancela","cancelar","dejalo","déjalo"}:
            self.atlas_confirmacion_pendiente = None
            self.atlas_confirmacion_hasta = 0.0
            self.responder("cancelado. No hice cambios.", "normal")
            return True
        if t not in {"si","sí","confirmo","confirma","de acuerdo","hazlo","adelante","acepto"}:
            return False
        self.atlas_confirmacion_pendiente = None
        self.atlas_confirmacion_hasta = 0.0
        return self._atlas_ejecutar_operacion_confirmada(pendiente.get("accion"), pendiente.get("datos") or {})

    def _atlas_crear_word_vacio(self, destino):
        try:
            from docx import Document
            doc = Document()
            doc.save(str(destino))
            return True, ""
        except Exception as error:
            return False, str(error)

    def _atlas_crear_excel_vacio(self, destino):
        """Crea XLSX real usando Excel instalado, sin pywin32."""
        if os.name != "nt":
            return False, "Excel COM solo está disponible en Windows."
        ruta = str(destino).replace("'", "''")
        script = (
            "$ErrorActionPreference='Stop'; "
            "$excel=New-Object -ComObject Excel.Application; "
            "$excel.DisplayAlerts=$false; "
            "try{$wb=$excel.Workbooks.Add(); $wb.SaveAs('" + ruta + "',51); $wb.Close($false)} "
            "finally{$excel.Quit(); [System.Runtime.Interopservices.Marshal]::ReleaseComObject($excel)|Out-Null}"
        )
        try:
            flags=getattr(subprocess,"CREATE_NO_WINDOW",0)
            r=subprocess.run(["powershell","-NoProfile","-Command",script],capture_output=True,text=True,timeout=20,creationflags=flags)
            return (r.returncode == 0 and Path(destino).exists()), ((r.stderr or r.stdout or "").strip())
        except Exception as error:
            return False, str(error)

    def _atlas_crear_documento(self, tipo, nombre):
        ext = ".docx" if tipo == "word" else ".xlsx"
        predeterminado = "Documento Word" if tipo == "word" else "Libro Excel"
        seguro = self._atlas_nombre_windows_seguro(nombre or predeterminado, ext)
        if not seguro:
            self.responder("necesito un nombre válido para el archivo.", "confundida")
            return True
        base = self._atlas_base_operacion_archivos()
        destino = base / seguro
        if destino.exists():
            return self._atlas_solicitar_confirmacion(
                "sobrescribir_documento", {"tipo": tipo, "destino": str(destino)},
                f"ya existe {destino.name}. Para crear el nuevo archivo tendría que sobrescribirlo."
            )
        return self._atlas_materializar_documento(tipo, destino)

    def _atlas_materializar_documento(self, tipo, destino):
        destino = Path(destino)
        ok, error = self._atlas_crear_word_vacio(destino) if tipo == "word" else self._atlas_crear_excel_vacio(destino)
        if not ok or not destino.exists():
            print(f"CONTROL ATLAS v3.5.2: no pude crear {tipo}: {error}")
            self.responder(f"no pude crear el archivo {tipo}.", "molesta")
            return True
        self.atlas_ultimo_archivo = destino
        self.atlas_ultima_ruta_referida = destino
        try:
            os.startfile(str(destino))
            self.responder(f"creé y abrí {destino.name}.", "feliz")
        except Exception:
            self.responder(f"creé {destino.name}, pero no pude abrirlo automáticamente.", "normal")
        print(f"CONTROL ATLAS v3.5.2: documento creado={destino}")
        return True

    def _atlas_renombrar(self, referencia, nuevo_nombre, tipo="cualquiera"):
        origen = self._atlas_elemento_contextual(referencia, tipo)
        if not origen:
            self.responder("no pude identificar un único elemento real para renombrar.", "confundida")
            return True
        origen = Path(origen)
        ext = origen.suffix if origen.is_file() else ""
        seguro = self._atlas_nombre_windows_seguro(nuevo_nombre, ext if origen.is_file() else "")
        if not seguro:
            self.responder("el nuevo nombre no es válido.", "confundida")
            return True
        destino = origen.with_name(seguro)
        if destino.exists() and destino != origen:
            self.responder(f"ya existe {destino.name}. No lo sobrescribí.", "confundida")
            return True
        try:
            origen.rename(destino)
            if self.atlas_carpeta_actual and Path(self.atlas_carpeta_actual) == origen:
                self.atlas_carpeta_actual = destino
            if self.atlas_ultimo_archivo and Path(self.atlas_ultimo_archivo) == origen:
                self.atlas_ultimo_archivo = destino
            self.atlas_ultima_ruta_referida = destino
            self.responder(f"renombré {origen.name} como {destino.name}.", "feliz")
            print(f"CONTROL ATLAS v3.5.2: renombrado {origen} -> {destino}")
        except Exception as error:
            print("CONTROL ATLAS v3.5.2: error renombrando:", error)
            self.responder("no pude renombrar ese elemento.", "molesta")
        return True

    def _atlas_copiar(self, referencia, destino_ref, tipo="cualquiera"):
        origen = self._atlas_elemento_contextual(referencia, tipo)
        destino_dir = self._atlas_destino_carpeta(destino_ref)
        if not origen or not destino_dir:
            self.responder("no pude verificar el origen o la carpeta de destino.", "confundida")
            return True
        origen, destino_dir = Path(origen), Path(destino_dir)
        destino = destino_dir / origen.name
        try:
            origen_r, destino_dir_r, destino_r = origen.resolve(), destino_dir.resolve(), destino.resolve()
            if origen_r == destino_r or (origen.is_dir() and (destino_dir_r == origen_r or origen_r in destino_dir_r.parents)):
                self.responder("no copiaré una carpeta dentro de sí misma ni sobre el mismo origen.", "confundida")
                return True
        except Exception:
            pass
        if destino.exists():
            return self._atlas_solicitar_confirmacion(
                "copiar_sobrescribir", {"origen": str(origen), "destino": str(destino)},
                f"{destino.name} ya existe en {destino_dir.name}; copiarlo reemplazaría contenido existente."
            )
        return self._atlas_ejecutar_copia(origen, destino)

    def _atlas_ejecutar_copia(self, origen, destino):
        try:
            origen, destino = Path(origen), Path(destino)
            if origen.is_dir():
                shutil.copytree(origen, destino)
            else:
                shutil.copy2(origen, destino)
            if not destino.exists():
                raise IOError("el destino no apareció tras la copia")
            self.atlas_ultima_ruta_referida = destino
            self.responder(f"copié {origen.name} en {destino.parent.name or destino.parent}.", "feliz")
            print(f"CONTROL ATLAS v3.5.2: copia verificada {origen} -> {destino}")
        except Exception as error:
            print("CONTROL ATLAS v3.5.2: error copiando:", error)
            self.responder("no pude completar la copia.", "molesta")
        return True

    def _atlas_mover(self, referencia, destino_ref, tipo="cualquiera"):
        origen = self._atlas_elemento_contextual(referencia, tipo)
        destino_dir = self._atlas_destino_carpeta(destino_ref)
        if not origen or not destino_dir:
            self.responder("no pude verificar el origen o la carpeta de destino.", "confundida")
            return True
        origen, destino_dir = Path(origen), Path(destino_dir)
        if self._atlas_es_ruta_protegida(origen):
            self.responder("esa ubicación está protegida y no la moveré.", "molesta")
            return True
        destino = destino_dir / origen.name
        try:
            origen_r, destino_dir_r, destino_r = origen.resolve(), destino_dir.resolve(), destino.resolve()
            if origen_r == destino_r or (origen.is_dir() and (destino_dir_r == origen_r or origen_r in destino_dir_r.parents)):
                self.responder("no moveré una carpeta dentro de sí misma ni al mismo lugar.", "confundida")
                return True
        except Exception:
            pass
        msg = f"voy a mover {origen.name} a {destino_dir}."
        if destino.exists():
            msg += " Allí ya existe un elemento con el mismo nombre y podría reemplazarse."
        return self._atlas_solicitar_confirmacion("mover", {"origen": str(origen), "destino": str(destino)}, msg)

    def _atlas_enviar_papelera(self, ruta):
        if os.name != "nt":
            return False, "La Papelera de reciclaje requiere Windows."
        ruta = str(Path(ruta)).replace("'", "''")
        es_dir = Path(ruta.replace("''", "'")).is_dir()
        metodo = "DeleteDirectory" if es_dir else "DeleteFile"
        script = (
            "Add-Type -AssemblyName Microsoft.VisualBasic; "
            f"[Microsoft.VisualBasic.FileIO.FileSystem]::{metodo}('{ruta}',"
            "[Microsoft.VisualBasic.FileIO.UIOption]::OnlyErrorDialogs,"
            "[Microsoft.VisualBasic.FileIO.RecycleOption]::SendToRecycleBin)"
        )
        try:
            flags=getattr(subprocess,"CREATE_NO_WINDOW",0)
            r=subprocess.run(["powershell","-NoProfile","-Command",script],capture_output=True,text=True,timeout=20,creationflags=flags)
            return r.returncode == 0, (r.stderr or r.stdout or "").strip()
        except Exception as error:
            return False, str(error)

    def _atlas_eliminar(self, referencia, tipo="cualquiera"):
        origen = self._atlas_elemento_contextual(referencia, tipo)
        if not origen:
            self.responder("no pude identificar un único elemento real para eliminar.", "confundida")
            return True
        origen = Path(origen)
        if self._atlas_es_ruta_protegida(origen):
            self.responder("esa ubicación está protegida y no la eliminaré.", "molesta")
            return True
        return self._atlas_solicitar_confirmacion(
            "eliminar", {"origen": str(origen)},
            f"voy a enviar {origen.name} a la Papelera de reciclaje."
        )

    def _atlas_nombre_unico(self, destino):
        destino=Path(destino)
        if not destino.exists():
            return destino
        base, ext = destino.stem, destino.suffix
        for i in range(1,1000):
            candidato=destino.with_name(f"{base} ({i}){ext}")
            if not candidato.exists():
                return candidato
        return destino.with_name(f"{base} copia{ext}")

    def _atlas_plan_organizacion(self, ruta):
        ruta=Path(ruta)
        categorias={
            "PDF": {".pdf"}, "Word": {".doc", ".docx"}, "Excel": {".xls", ".xlsx", ".xlsm", ".csv"},
            "Presentaciones": {".ppt", ".pptx"}, "Imagenes": {".jpg", ".jpeg", ".png", ".gif", ".webp", ".bmp", ".heic"},
            "Comprimidos": {".zip", ".7z", ".rar", ".tar", ".gz"}, "Texto": {".txt", ".md", ".rtf"},
        }
        plan=[]; conteo={}
        try:
            archivos=[p for p in ruta.iterdir() if p.is_file() and not p.name.startswith(".") and p.name.lower() != "desktop.ini"]
        except Exception:
            return [],{}
        for p in archivos:
            cat="Otros"
            for nombre, exts in categorias.items():
                if p.suffix.lower() in exts:
                    cat=nombre; break
            plan.append((p, ruta/cat/p.name))
            conteo[cat]=conteo.get(cat,0)+1
        return plan, conteo

    def _atlas_mover_lote_tipo(self, tipo_nombre, destino_ref):
        grupos={
            "pdf": {".pdf"}, "word": {".doc", ".docx"}, "excel": {".xls", ".xlsx", ".xlsm", ".csv"},
            "imagenes": {".jpg", ".jpeg", ".png", ".gif", ".webp", ".bmp", ".heic"},
        }
        clave=normalizar(tipo_nombre or "").strip()
        if clave in {"imagen","imagenes","fotos"}: clave="imagenes"
        exts=grupos.get(clave)
        destino=self._atlas_destino_carpeta(destino_ref)
        base=self._atlas_base_operacion_archivos()
        if not exts or not destino:
            self.responder("no pude verificar el tipo de archivos o la carpeta de destino.", "confundida")
            return True
        archivos=[]
        try:
            archivos=[p for p in base.iterdir() if p.is_file() and p.suffix.lower() in exts]
        except Exception:
            archivos=[]
        if not archivos:
            self.responder(f"no encontré archivos {clave} en {base.name or base}.", "normal")
            return True
        return self._atlas_solicitar_confirmacion(
            "mover_lote", {"archivos":[str(p) for p in archivos], "destino":str(destino)},
            f"encontré {len(archivos)} archivos {clave}. Los moveré a {Path(destino).name or destino}."
        )

    def _atlas_organizar_carpeta_actual(self):
        ruta=self._atlas_base_operacion_archivos()
        plan, conteo=self._atlas_plan_organizacion(ruta)
        if not plan:
            self.responder("no encontré archivos que necesiten organización en esta carpeta.", "normal")
            return True
        resumen=", ".join(f"{v} {k}" for k,v in sorted(conteo.items()))
        return self._atlas_solicitar_confirmacion(
            "organizar", {"ruta": str(ruta)},
            f"encontré {len(plan)} archivos: {resumen}. Los organizaré en subcarpetas por tipo."
        )

    def _atlas_ejecutar_operacion_confirmada(self, accion, datos):
        try:
            if accion == "sobrescribir_documento":
                destino=Path(datos["destino"]); tipo=datos["tipo"]
                if self._atlas_es_ruta_protegida(destino):
                    self.responder("ese destino está protegido y no lo sobrescribiré.", "molesta"); return True
                if destino.exists():
                    if destino.is_dir():
                        self.responder("el destino es una carpeta; no puedo sobrescribirla con un documento.", "molesta"); return True
                    destino.unlink()
                return self._atlas_materializar_documento(tipo, destino)
            if accion == "copiar_sobrescribir":
                origen, destino=Path(datos["origen"]),Path(datos["destino"])
                if self._atlas_es_ruta_protegida(destino):
                    self.responder("el destino está protegido y no lo sobrescribiré.", "molesta"); return True
                if destino.exists():
                    if destino.is_dir(): shutil.rmtree(destino)
                    else: destino.unlink()
                return self._atlas_ejecutar_copia(origen,destino)
            if accion == "mover":
                origen, destino=Path(datos["origen"]),Path(datos["destino"])
                if not origen.exists():
                    self.responder("el origen ya no existe; no moví nada.", "confundida"); return True
                if destino.exists():
                    if self._atlas_es_ruta_protegida(destino):
                        self.responder("el destino existente está protegido; no moví nada.", "molesta"); return True
                    if destino.is_dir(): shutil.rmtree(destino)
                    else: destino.unlink()
                shutil.move(str(origen),str(destino))
                if not destino.exists(): raise IOError("movimiento no verificado")
                self.atlas_ultima_ruta_referida=destino
                self.responder(f"moví {origen.name} a {destino.parent.name or destino.parent}.", "feliz")
                print(f"CONTROL ATLAS v3.5.2: movimiento verificado {origen} -> {destino}")
                return True
            if accion == "eliminar":
                origen=Path(datos["origen"])
                if not origen.exists():
                    self.responder("el elemento ya no existe; no eliminé nada.", "normal"); return True
                if self._atlas_es_ruta_protegida(origen):
                    self.responder("esa ubicación está protegida y no la eliminaré.", "molesta"); return True
                ok,error=self._atlas_enviar_papelera(origen)
                if ok and not origen.exists():
                    self.responder(f"envié {origen.name} a la Papelera de reciclaje.", "normal")
                    print(f"CONTROL ATLAS v3.5.2: eliminación verificada papelera={origen}")
                elif ok:
                    self.responder("Windows aceptó la operación, pero todavía veo el elemento; no puedo confirmar que se eliminó.", "confundida")
                else:
                    print("CONTROL ATLAS v3.5.2: error papelera:",error)
                    self.responder("no pude enviar ese elemento a la Papelera de reciclaje.", "molesta")
                return True
            if accion == "mover_lote":
                destino_dir=Path(datos["destino"]); movidos=0
                destino_dir.mkdir(parents=False,exist_ok=True)
                for item in datos.get("archivos",[]):
                    origen=Path(item)
                    if not origen.exists() or not origen.is_file():
                        continue
                    destino=self._atlas_nombre_unico(destino_dir/origen.name)
                    shutil.move(str(origen),str(destino)); movidos+=1
                self.responder(f"moví {movidos} archivos a {destino_dir.name or destino_dir}.", "feliz")
                print(f"CONTROL ATLAS v3.5.2: movimiento por lote verificado destino={destino_dir} movidos={movidos}")
                return True
            if accion == "organizar":
                ruta=Path(datos["ruta"]); plan,_=self._atlas_plan_organizacion(ruta)
                movidos=0
                for origen,destino in plan:
                    if not origen.exists(): continue
                    destino.parent.mkdir(exist_ok=True)
                    destino=self._atlas_nombre_unico(destino)
                    shutil.move(str(origen),str(destino)); movidos+=1
                self.responder(f"organicé {movidos} archivos en {ruta.name or ruta}.", "feliz")
                print(f"CONTROL ATLAS v3.5.2: organización verificada ruta={ruta} movidos={movidos}")
                return True
        except Exception as error:
            print(f"CONTROL ATLAS v3.5.2: operación confirmada falló accion={accion}:",error)
            self.responder("no pude completar la operación; no la daré por realizada.", "molesta")
            return True
        self.responder("la operación pendiente ya no es válida.", "confundida")
        return True

    def _atlas_cpu_modelo(self):
        modelo = platform.processor().strip()
        if os.name == "nt":
            try:
                import winreg
                with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, r"HARDWARE\DESCRIPTION\System\CentralProcessor\0") as k:
                    modelo, _ = winreg.QueryValueEx(k, "ProcessorNameString")
            except Exception:
                pass
        return re.sub(r"\s+", " ", modelo).strip() or "procesador no identificado"

    def _atlas_gpu_nvidia(self):
        exe = shutil.which("nvidia-smi")
        if not exe:
            candidatos = [Path(os.environ.get("ProgramW6432", "")) / "NVIDIA Corporation" / "NVSMI" / "nvidia-smi.exe"]
            exe = next((str(p) for p in candidatos if p.exists()), None)
        if not exe:
            return None
        try:
            flags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
            r = subprocess.run([exe, "--query-gpu=name,utilization.gpu,memory.used,memory.total,temperature.gpu",
                                "--format=csv,noheader,nounits"], capture_output=True, text=True, timeout=4, creationflags=flags)
            linea = (r.stdout or "").strip().splitlines()[0]
            partes = [x.strip() for x in linea.split(",")]
            if len(partes) >= 5:
                return {"nombre":partes[0], "uso":float(partes[1]), "mem_usada":float(partes[2]),
                        "mem_total":float(partes[3]), "temperatura":float(partes[4])}
        except Exception:
            pass
        return None

    def _atlas_snapshot_sistema(self):
        try:
            import psutil
        except Exception as error:
            return {"error": "psutil", "detalle": str(error)}
        d = {}
        d["cpu_modelo"] = self._atlas_cpu_modelo()
        # Una sola ventana de muestreo para total y núcleos. En v3.4.0 el
        # segundo cpu_percent(interval=None, percpu=True) podía devolver ceros
        # inmediatamente después del muestreo global.
        por_nucleo = list(psutil.cpu_percent(interval=0.35, percpu=True))
        d["cpu_por_nucleo"] = por_nucleo
        d["cpu"] = float(sum(por_nucleo) / len(por_nucleo)) if por_nucleo else 0.0
        d["nucleos"] = psutil.cpu_count(logical=False) or 0
        d["hilos"] = psutil.cpu_count(logical=True) or 0
        freq = psutil.cpu_freq()
        d["freq_actual"] = float(freq.current) if freq else None
        d["freq_max"] = float(freq.max) if freq and freq.max else None
        vm = psutil.virtual_memory()
        d["ram_total"] = int(vm.total); d["ram_usada"] = int(vm.used); d["ram_disp"] = int(vm.available); d["ram_pct"] = float(vm.percent)
        d["procesos"] = len(psutil.pids())
        top=[]
        for p in psutil.process_iter(["name", "memory_info"]):
            try:
                rss = p.info["memory_info"].rss if p.info.get("memory_info") else 0
                if rss > 0:
                    top.append((rss, p.info.get("name") or "proceso"))
            except Exception:
                pass
        d["top_ram"] = sorted(top, reverse=True)[:5]
        unidad = os.environ.get("SystemDrive", "C:") + "\\" if os.name == "nt" else "/"
        try:
            du = psutil.disk_usage(unidad)
            d["disco_unidad"] = unidad; d["disco_total"] = du.total; d["disco_usado"] = du.used; d["disco_libre"] = du.free; d["disco_pct"] = float(du.percent)
        except Exception:
            pass
        io1 = psutil.net_io_counters()
        dio1 = psutil.disk_io_counters()
        t0 = time.perf_counter(); time.sleep(0.45); io2 = psutil.net_io_counters(); dio2 = psutil.disk_io_counters(); dt=max(0.01,time.perf_counter()-t0)
        d["red_bajada"] = max(0.0, (io2.bytes_recv-io1.bytes_recv)/dt)
        d["red_subida"] = max(0.0, (io2.bytes_sent-io1.bytes_sent)/dt)
        if dio1 and dio2:
            d["disco_lectura"] = max(0.0, (dio2.read_bytes-dio1.read_bytes)/dt)
            d["disco_escritura"] = max(0.0, (dio2.write_bytes-dio1.write_bytes)/dt)
        d["red_recibido"] = int(io2.bytes_recv); d["red_enviado"] = int(io2.bytes_sent)
        activas=[]
        stats_if = psutil.net_if_stats()
        for nombre, st in stats_if.items():
            if st.isup and not any(x in normalizar(nombre) for x in ["loopback", "bluetooth"]):
                activas.append(nombre)

        # Elegimos primero la IP que Windows realmente usaría para salir a
        # Internet. Así evitamos reportar adaptadores APIPA 169.254.x.x cuando
        # hay otra interfaz con la ruta predeterminada. No se envían datos por
        # este socket UDP; connect() solo resuelve la ruta local.
        ip = ""
        interfaz_activa = ""
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            try:
                sock.connect(("1.1.1.1", 80))
                ip = str(sock.getsockname()[0] or "")
            finally:
                sock.close()
        except Exception:
            ip = ""
        try:
            addrs_por_if = psutil.net_if_addrs()
            if ip:
                for nombre, addrs in addrs_por_if.items():
                    if any(getattr(a, "family", None) == socket.AF_INET and str(a.address) == ip for a in addrs):
                        interfaz_activa = nombre
                        break
            if not ip:
                # Respaldo: preferimos IPv4 privada válida y dejamos APIPA para
                # el final porque normalmente indica ausencia de DHCP.
                candidatos = []
                for nombre in activas:
                    for a in addrs_por_if.get(nombre, []):
                        addr = str(getattr(a, "address", "") or "")
                        if getattr(a, "family", None) != socket.AF_INET or addr.startswith("127."):
                            continue
                        prioridad = 0 if addr.startswith("169.254.") else 10
                        candidatos.append((prioridad, nombre, addr))
                if candidatos:
                    _, interfaz_activa, ip = sorted(candidatos, reverse=True)[0]
        except Exception:
            pass
        d["interfaces"] = activas
        d["interfaz_activa"] = interfaz_activa
        nombre_red = interfaz_activa or (activas[0] if activas else "")
        nred = normalizar(nombre_red)
        d["tipo_red"] = "Wi-Fi" if any(x in nred for x in ["wifi", "wi fi", "wlan", "inalambr"] ) else ("Ethernet" if nombre_red else "sin conexión activa")
        d["ip_local"] = ip
        d["latencia_ms"] = None
        try:
            flags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
            comando_ping = ["ping", "-n", "1", "-w", "1200", "1.1.1.1"] if os.name == "nt" else ["ping", "-c", "1", "-W", "1", "1.1.1.1"]
            pr = subprocess.run(comando_ping, capture_output=True, text=True, timeout=2.0, creationflags=flags)
            salida_ping = (pr.stdout or "") + " " + (pr.stderr or "")
            m = re.search(r"(?:time|tiempo)[=<]\s*([0-9]+(?:[.,][0-9]+)?)\s*ms", salida_ping, re.IGNORECASE)
            if m:
                d["latencia_ms"] = float(m.group(1).replace(",", "."))
        except Exception:
            pass
        d["gpu"] = self._atlas_gpu_nvidia()
        # psutil no ofrece sensores de temperatura fiables en Windows. Nunca
        # convertimos zonas térmicas ACPI genéricas en "temperatura CPU".
        d["cpu_temp"] = None
        try:
            if hasattr(psutil, "sensors_temperatures"):
                temps = psutil.sensors_temperatures(fahrenheit=False) or {}
                for grupo in temps.values():
                    for s in grupo:
                        etiqueta = normalizar(getattr(s, "label", "") or "")
                        if "cpu" in etiqueta or "package" in etiqueta:
                            d["cpu_temp"] = float(s.current); raise StopIteration
        except StopIteration:
            pass
        except Exception:
            pass
        return d

    @staticmethod
    def _atlas_gb(bytes_):
        return float(bytes_ or 0) / (1024 ** 3)

    @staticmethod
    def _atlas_tasa(valor):
        valor=float(valor or 0)
        if valor >= 1024**2:
            return f"{valor/(1024**2):.1f} MB/s"
        if valor >= 1024:
            return f"{valor/1024:.0f} KB/s"
        return f"{valor:.0f} B/s"

    def _atlas_estado_sistema_async(self, seccion="resumen"):
        self.procesando = True
        self.procesando_desde = time.time()
        self.procesando_tipo = "estado_atlas"
        proceso_local = self.proceso_id = self.proceso_id + 1

        def trabajo():
            datos = self._atlas_snapshot_sistema()
            if proceso_local != self.proceso_id:
                return
            if datos.get("error") == "psutil":
                respuesta = "no puedo leer todavía el estado de Atlas porque falta el componente psutil."
            elif seccion == "cpu":
                temp = f" Temperatura {datos['cpu_temp']:.0f} °C." if datos.get("cpu_temp") is not None else " El sensor de temperatura del CPU no está disponible."
                freq = f" Frecuencia actual {datos['freq_actual']/1000:.2f} GHz." if datos.get("freq_actual") else ""
                carga_max = max(datos.get("cpu_por_nucleo") or [0])
                respuesta = f"{datos['cpu_modelo']}. CPU {datos['cpu']:.0f}%. {datos['nucleos']} núcleos y {datos['hilos']} hilos; núcleo más cargado {carga_max:.0f}%.{freq}{temp}"
            elif seccion == "ram":
                top = ", ".join(f"{n} {self._atlas_gb(b):.1f} GB" for b,n in datos.get("top_ram",[])[:3])
                respuesta = (f"RAM {datos['ram_pct']:.0f}%: {self._atlas_gb(datos['ram_usada']):.1f} de "
                             f"{self._atlas_gb(datos['ram_total']):.1f} GB en uso; {self._atlas_gb(datos['ram_disp']):.1f} GB disponibles."
                             + (f" Los procesos que más usan son {top}." if top else ""))
            elif seccion == "disco":
                actividad = ""
                if "disco_lectura" in datos:
                    actividad = f" Actividad actual: lectura {self._atlas_tasa(datos.get('disco_lectura'))}, escritura {self._atlas_tasa(datos.get('disco_escritura'))}."
                respuesta = (f"Disco {datos.get('disco_unidad','')}: {datos.get('disco_pct',0):.0f}% usado; "
                             f"{self._atlas_gb(datos.get('disco_libre',0)):.1f} GB libres de {self._atlas_gb(datos.get('disco_total',0)):.1f} GB." + actividad)
            elif seccion == "red":
                respuesta = (f"Red {datos.get('tipo_red','')}: conectada" if datos.get('interfaces') else "Red: no detecto una interfaz activa")
                if datos.get("interfaces"):
                    respuesta += (f". Tráfico actual: descarga {self._atlas_tasa(datos.get('red_bajada'))} y subida {self._atlas_tasa(datos.get('red_subida'))}."
                                  + (f" IP local {datos['ip_local']}." if datos.get('ip_local') else "")
                                  + (f" Latencia {datos['latencia_ms']:.0f} ms." if datos.get('latencia_ms') is not None else ""))
            elif seccion == "gpu":
                gpu=datos.get("gpu")
                if gpu:
                    respuesta=(f"GPU {gpu['nombre']}: {gpu['uso']:.0f}% de uso, {gpu['mem_usada']:.0f} de {gpu['mem_total']:.0f} MB de memoria y {gpu['temperatura']:.0f} °C.")
                else:
                    respuesta="no tengo un sensor de GPU accesible actualmente; no voy a inventar esos valores."
            else:
                gpu=datos.get("gpu")
                gpu_txt=f" GPU {gpu['uso']:.0f}% a {gpu['temperatura']:.0f} °C." if gpu else " GPU: sensor no disponible."
                temp_txt=f" CPU a {datos['cpu_temp']:.0f} °C." if datos.get("cpu_temp") is not None else " Temperatura CPU: sensor no disponible."
                respuesta=(f"Atlas: CPU {datos['cpu']:.0f}%, RAM {datos['ram_pct']:.0f}%, disco {datos.get('disco_pct',0):.0f}%."
                           f"{gpu_txt}{temp_txt} Red {datos.get('tipo_red','')}, descarga {self._atlas_tasa(datos.get('red_bajada'))}, subida {self._atlas_tasa(datos.get('red_subida'))}. "
                           f"{datos['nucleos']} núcleos, {datos['hilos']} hilos y {datos['procesos']} procesos activos.")
            def terminar():
                if proceso_local != self.proceso_id:
                    return
                self.procesando=False; self.procesando_desde=0.0; self.procesando_tipo=""
                self.responder(respuesta, "normal")
                print("CONTROL ATLAS v3.5.2: estado real del sistema consultado.")
            self.root.after(0, terminar)
        threading.Thread(target=trabajo, daemon=True).start()
        return True

    def _atlas_manejar_aclaracion(self, original):
        if not self.atlas_aclaracion_pendiente:
            return False
        t=self._atlas_quitar_wake(original)
        pendiente=self.atlas_aclaracion_pendiente
        if any(x in t for x in ["minimiza", "minimizar", "solo minimiza"]):
            self.atlas_aclaracion_pendiente=None
            return self._atlas_controlar_ventana("minimizar", pendiente.get("app", ""))
        if any(x in t for x in ["cierra", "cerrar", "cierralo", "cierrala"]):
            self.atlas_aclaracion_pendiente=None
            return self._atlas_controlar_ventana("cerrar", pendiente.get("app", ""))
        if any(x in t for x in ["cancela", "dejalo", "ninguna"]):
            self.atlas_aclaracion_pendiente=None
            self.responder("cancelado.", "normal")
            return True
        return False

    def _atlas_manejar_comando(self, original):
        t = self._atlas_normalizar_orden_operativa(self._atlas_quitar_wake(original))
        if not t:
            return False
        if self._atlas_resolver_opcion_pendiente(original):
            return True
        if self._atlas_resolver_confirmacion_pendiente(original):
            return True
        if self._atlas_manejar_aclaracion(original):
            return True

        # Estado real del computador. El enrutador tolera ruido ASR antes de
        # "estado" (p. ej. "betatimer estado de la internet") para impedir que
        # una consulta del sistema termine en la biblioteca académica/Ollama.
        if any(x in t for x in ["estado de mi computador", "estado del computador", "estado de atlas",
                                "como esta mi computador", "como esta atlas", "estado del pc", "estado del equipo"]):
            return self._atlas_estado_sistema_async("resumen")
        if any(x in t for x in ["estado del procesador", "estado de cpu", "como esta el procesador", "uso del procesador", "uso de cpu"]) \
                or ("estado" in t and any(k in t for k in ["procesador", " cpu"])):
            return self._atlas_estado_sistema_async("cpu")
        if any(x in t for x in ["memoria ram", "estado de ram", "uso de ram", "cuanta ram"]) \
                or ("estado" in t and "ram" in t):
            return self._atlas_estado_sistema_async("ram")
        if any(x in t for x in ["estado del disco", "espacio en disco", "espacio del disco", "estado del ssd", "cuanto espacio"]) \
                or ("estado" in t and any(k in t for k in ["disco", "ssd"])):
            return self._atlas_estado_sistema_async("disco")
        if any(x in t for x in ["estado de internet", "estado de la internet", "estado de la red", "como esta internet", "uso de red", "velocidad de red"]) \
                or ("estado" in t and any(k in t for k in ["internet", " red"])):
            return self._atlas_estado_sistema_async("red")
        if any(x in t for x in ["estado de la gpu", "uso de gpu", "temperatura de gpu", "estado de gpu"]) \
                or ("estado" in t and "gpu" in t):
            return self._atlas_estado_sistema_async("gpu")

        # Navegación contextual. Una ubicación confiable nombrada de forma
        # explícita se ejecuta localmente y actualiza el contexto REAL; nunca
        # se responde mediante Ollama con un "ya estoy" ficticio.
        m_volver_raiz = re.match(r"^(?:vuelve|volver|regresa|regresar)\s+a\s+(?:la\s+carpeta\s+)?(.+)$", t)
        if m_volver_raiz:
            objetivo_raiz = m_volver_raiz.group(1).strip()
            ruta_raiz = self._atlas_ruta_confiable(objetivo_raiz)
            if ruta_raiz and Path(ruta_raiz).exists() and Path(ruta_raiz).is_dir():
                return self._atlas_abrir_ruta(ruta_raiz, "carpeta")
        if any(x in t for x in ["vuelve a la carpeta anterior", "volver a la carpeta anterior", "carpeta anterior", "vuelve atras"]):
            return self._atlas_volver_carpeta()
        if t in {"abre esa carpeta", "abrir esa carpeta", "entra a esa carpeta"}:
            if self.atlas_carpeta_actual:
                return self._atlas_abrir_ruta(self.atlas_carpeta_actual, "carpeta")
            self.responder("todavía no tengo una carpeta concreta en el contexto.", "confundida")
            return True
        # Creación real de documentos Office en la carpeta contextual.
        m = re.match(r"^(?:crea|crear)\s+(?:un|una)?\s*(?:documento\s+)?word(?:\s+(?:llamado|llamada))?\s*(.*)$", t)
        if m:
            return self._atlas_crear_documento("word", m.group(1).strip())
        m = re.match(r"^(?:crea|crear)\s+(?:un|una)?\s*(?:archivo\s+)?excel(?:\s+(?:llamado|llamada))?\s*(.*)$", t)
        if m:
            return self._atlas_crear_documento("excel", m.group(1).strip())

        # Renombrado seguro: no sobrescribe destinos existentes.
        m = re.match(r"^renombra\s+(esta carpeta|la carpeta|este archivo|el archivo)\s+(?:a|como)\s+(.+)$", t)
        if m:
            tipo_ref = "carpeta" if "carpeta" in m.group(1) else "archivo"
            return self._atlas_renombrar(m.group(1), m.group(2).strip(), tipo_ref)
        m = re.match(r"^renombra\s+(.+?)\s+(?:a|como)\s+(.+)$", t)
        if m:
            return self._atlas_renombrar(m.group(1).strip(), m.group(2).strip())

        # Copiar es directo solo cuando no pisa nada; cualquier sobrescritura
        # requiere confirmación. Mover siempre requiere confirmación.
        m = re.match(r"^copia\s+(.+?)\s+(?:a|en)\s+(?:la\s+)?(?:carpeta\s+)?(.+)$", t)
        if m:
            return self._atlas_copiar(m.group(1).strip(), m.group(2).strip())
        m_lote = re.match(r"^mueve\s+(?:los|las)\s+(pdf|word|excel|imagenes|imagen|fotos)\s+(?:a|en)\s+(?:la\s+)?(?:carpeta\s+)?(.+)$", t)
        if m_lote:
            return self._atlas_mover_lote_tipo(m_lote.group(1), m_lote.group(2).strip())
        m = re.match(r"^mueve\s+(.+?)\s+(?:a|en)\s+(?:la\s+)?(?:carpeta\s+)?(.+)$", t)
        if m:
            return self._atlas_mover(m.group(1).strip(), m.group(2).strip())

        # Eliminación siempre a Papelera y siempre con confirmación.
        m = re.match(r"^(?:elimina|eliminar|borra|borrar)\s+(.+)$", t)
        if m:
            ref=m.group(1).strip()
            ref=re.sub(r"^(?:la|el)\s+", "", ref).strip()
            return self._atlas_eliminar(ref)

        if re.fullmatch(r"(?:organiza|ordenar|ordena)\s+(?:esta|la)\s+carpeta", t) or re.fullmatch(r"separa\s+(?:los\s+)?word\s+de\s+(?:los\s+)?excel", t):
            return self._atlas_organizar_carpeta_actual()

        m = re.match(r"^(?:crea|crear)\s+(?:una\s+)?carpeta\s+(?:llamada\s+)?(.+)$", t)
        if m:
            return self._atlas_crear_carpeta_contextual(m.group(1).strip())

        # v3.5.2: orden explícita con raíz conocida + acción + hijo.
        # Ej.: "en la carpeta IPP ubica la carpeta segundo semestre".
        # Se analiza estructuralmente y jamás se envía a Ollama.
        m_raiz_accion = re.match(
            r"^(?:en|dentro\s+de)\s+(?:la\s+)?carpeta\s+(.+?)\s+"
            r"(ubica|localiza|encuentra|busca|abre|entra|muestra|muestrame|mostrame|revisa|lista)\s+"
            r"(?:el\s+contenido\s+(?:de|del)\s+)?(?:la\s+)?(?:carpeta\s+)?(.+)$",
            t,
        )
        if m_raiz_accion:
            raiz_nombre, accion_raiz, hijo_nombre = [x.strip() for x in m_raiz_accion.groups()]
            raiz = self._atlas_ruta_confiable(raiz_nombre)
            if raiz and Path(raiz).exists() and Path(raiz).is_dir():
                candidatos = self._atlas_buscar_hijos_directos(raiz, hijo_nombre)
                if len(candidatos) == 1:
                    hijo = candidatos[0]
                    if accion_raiz in {"ubica", "localiza", "encuentra", "busca"}:
                        self.atlas_ultima_ruta_referida = hijo
                        self.responder(f"la carpeta {hijo.name} está en {hijo}.", "normal")
                        print(f"CONTROL ATLAS v3.5.2: ubicación contextual verificada={hijo}")
                        return True
                    if accion_raiz in {"muestra", "muestrame", "mostrame", "revisa", "lista"}:
                        return self._atlas_listar_contenido_carpeta(str(hijo))
                    return self._atlas_abrir_ruta(hijo, "carpeta")
                if len(candidatos) > 1:
                    return self._atlas_ofrecer_coincidencias(candidatos, "carpeta")
                self.responder(f"no encontré una subcarpeta real llamada {hijo_nombre} dentro de {Path(raiz).name}.", "confundida")
                print(f"CONTROL ATLAS v3.5.2: hijo contextual no encontrado={hijo_nombre!r} raiz={raiz}")
                return True

        # v3.5.2: frases naturales con una raíz conocida y una subcarpeta.
        # Ej.: "en la carpeta IPP quiero que abras la carpeta primer semestre".
        # Si Whisper deforma "abras" como "hagas", solo ejecutamos cuando la
        # subcarpeta EXISTE realmente dentro de la ubicación confiable nombrada.
        if "carpeta" in t:
            claves_mencionadas = [
                clave for clave in (getattr(self, "atlas_ubicaciones_confiables", {}) or {})
                if re.search(r"(?<!\w)" + re.escape(clave) + r"(?!\w)", t)
            ]
            if claves_mencionadas and any(x in t for x in ["quiero que", "abre", "abrir", "hagas", "haz", "entra"]):
                # Tomamos el ÚLTIMO nombre introducido por "carpeta". Así
                # "en la carpeta IPP quiero que abras la carpeta Primer Semestre"
                # separa correctamente raíz=IPP e hijo=Primer Semestre aunque
                # normalizar() haya eliminado la coma.
                m_sub = [x.strip() for x in t.split("carpeta ")[1:] if x.strip()]
                if m_sub:
                    objetivo_sub = m_sub[-1].strip()
                    objetivo_sub = re.sub(r"\s+(?:por favor|ahora)$", "", objetivo_sub).strip()
                    # Si el último nombre vuelve a ser la propia raíz, no lo tratamos como hijo.
                    if self._atlas_alias_ubicacion(objetivo_sub) not in claves_mencionadas:
                        raiz = self._atlas_ruta_confiable(claves_mencionadas[0])
                        if raiz and Path(raiz).exists():
                            candidatos = []
                            try:
                                for p in Path(raiz).iterdir():
                                    if p.is_dir() and self._atlas_nombres_carpeta_equivalentes(p.name, objetivo_sub):
                                        candidatos.append(p)
                            except Exception:
                                candidatos = []
                            if len(candidatos) == 1:
                                return self._atlas_abrir_ruta(candidatos[0], "carpeta")
                            if len(candidatos) > 1:
                                return self._atlas_ofrecer_coincidencias(candidatos, "carpeta")
                            # Es claramente una orden de carpetas, pero no hay ruta real.
                            self.responder(f"no encontré una subcarpeta real llamada {objetivo_sub} dentro de {Path(raiz).name}.", "confundida")
                            print(f"CONTROL ATLAS v3.5.2: subcarpeta contextual inexistente={objetivo_sub!r} raiz={raiz}")
                            return True

        # Consultas verificables del Explorador. Estas intenciones jamás
        # pasan a Ollama porque deben responder únicamente con el disco real.
        m = re.match(r"^(?:ubica|ubicar|localiza|localizar|encuentra|encontrar|busca|buscar)\s+(?:la\s+)?carpeta\s+(.+)$", t)
        if m:
            return self._atlas_ubicar_carpeta_por_nombre(m.group(1).strip())

        patrones_contenido = [
            r"^(?:revisa|revisar|muestra|mostrar|muestrame|mostrame|lista|listar|listame)\s+(?:el\s+)?contenido\s+(?:de|del)\s+(?:la\s+)?(?:carpeta\s+)?(.+)$",
            r"^(?:revisa|revisar|muestra|mostrar|muestrame|mostrame|lista|listar|listame)\s+(?:la\s+)?carpeta\s+(.+)$",
            r"^(?:que\s+hay|que\s+tiene|dime\s+que\s+hay)\s+(?:en|dentro\s+de)\s+(?:la\s+)?(?:carpeta\s+)?(.+)$",
        ]
        for patron in patrones_contenido:
            m = re.match(patron, t)
            if m:
                return self._atlas_listar_contenido_carpeta(m.group(1).strip())

        # Abrir/buscar archivos con tipo conocido.
        if any(v in t for v in ["abre ", "abrir ", "busca ", "buscar ", "encuentra ", "localiza "]):
            for tipo_archivo, palabra in [("word", "word"), ("excel", "excel"), ("pdf", "pdf")]:
                if palabra in t and not (t in {f"abre {palabra}", f"abrir {palabra}"}):
                    nombre=self._atlas_extraer_nombre(original, "archivo")
                    if nombre:
                        return self._atlas_abrir_archivo_por_nombre(nombre, tipo_archivo)
            if any(x in t for x in ["archivo ", "documento "]):
                nombre=self._atlas_extraer_nombre(original, "archivo")
                if nombre:
                    return self._atlas_abrir_archivo_por_nombre(nombre)

        # Carpeta explícita o navegación tipo "entra a programación".
        if any(x in t for x in ["carpeta ", "entra a ", "entra en "]):
            nombre=self._atlas_extraer_nombre(original, "carpeta")
            if nombre and nombre not in {"esa carpeta", "la carpeta"}:
                return self._atlas_abrir_carpeta_por_nombre(nombre)

        # Control de una ventana de carpeta por identidad de ruta real.
        m_carpeta_ventana = re.match(
            r"^(minimiza|maximiza|restaura|cierra)\s+(?:la\s+)?carpeta\s+(.+)$", t
        )
        if m_carpeta_ventana:
            accion_map = {"minimiza":"minimizar", "maximiza":"maximizar", "restaura":"restaurar", "cierra":"cerrar"}
            return self._atlas_controlar_carpeta_ventana(accion_map[m_carpeta_ventana.group(1)], m_carpeta_ventana.group(2))

        # Una ubicación confiable también puede nombrarse como objetivo de
        # ventana sin decir la palabra "carpeta": "cierra IPP", "minimiza y pepe".
        m_ubicacion_ventana = re.match(r"^(minimiza|maximiza|restaura|cierra)\s+(.+)$", t)
        if m_ubicacion_ventana:
            objetivo_ubicacion = m_ubicacion_ventana.group(2).strip()
            clave_ubicacion = self._atlas_alias_ubicacion(objetivo_ubicacion)
            # "Beta" por sí solo puede referirse al asistente, por lo que solo
            # se trata como carpeta cuando el usuario dice explícitamente
            # "la carpeta Beta" (ruta atendida arriba). IPP sí es inequívoco.
            if clave_ubicacion and clave_ubicacion != "beta":
                accion_map = {"minimiza":"minimizar", "maximiza":"maximizar", "restaura":"restaurar", "cierra":"cerrar"}
                return self._atlas_controlar_carpeta_ventana(
                    accion_map[m_ubicacion_ventana.group(1)], objetivo_ubicacion
                )

        app = self._atlas_detectar_app(t)

        # Volumen de Spotify. v3.5.2 distingue valor absoluto de cambio
        # relativo y acepta porcentajes hablados/dictados de varias formas.
        spotify_relevante = (app == "spotify" or self.atlas_ultima_aplicacion == "spotify" or self._spotify_contexto_vigente())
        if "volumen" in t and spotify_relevante:
            nivel = self._atlas_extraer_porcentaje(t)
            if nivel is not None:
                self.spotify_volumen_fijar_async(nivel)
                return True
            if any(x in t for x in ["sube", "subir", "suba", "aumenta", "aumentar", "aumente"]):
                self.spotify_volumen_async(+10)
                return True
            if any(x in t for x in ["baja", "bajar", "baje", "disminuye", "disminuir", "disminuya"]):
                self.spotify_volumen_async(-10)
                return True
            # Cortafuegos: si hay contexto Spotify y se mencionó volumen pero la
            # transcripción no permitió resolver la acción, jamás cae a Ollama
            # para que el modelo afirme un cambio que no ejecutó.
            self.responder("entendí una orden de volumen, pero no quedó suficientemente clara. Repita si quiere subir, bajar o fijar un porcentaje.", "confundida")
            print(f"CONTROL ATLAS v3.5.2: orden de volumen bloqueada por ambigüedad: {t!r}")
            return True

        # "Abre segundo semestre" / "abre IPP": si no es una aplicación
        # conocida, Beta busca primero una carpeta REAL. Cuando hay un contexto
        # de Explorer, sus hijos tienen prioridad. Si no existe, no inventa ruta.
        m_contexto = re.match(r"^(?:abre|abrir)\s+(?:la\s+|el\s+)?(.+)$", t)
        if m_contexto and not app:
            objetivo = m_contexto.group(1).strip()
            objetivo = self._atlas_normalizar_nombre_carpeta(objetivo)
            if objetivo in {"esta ventana", "esa ventana", "esto", "esa carpeta", "esta carpeta"}:
                if objetivo in {"esta ventana", "esa ventana", "esto"}:
                    return self._atlas_controlar_ventana("restaurar", "")
            elif objetivo and not any(x in objetivo for x in ["archivo ", "documento "]):
                return self._atlas_abrir_carpeta_por_nombre(objetivo)


        # Lenguaje ambiguo: no decidimos por el usuario si significa cerrar o
        # simplemente quitar de la vista.
        if app and any(x in t for x in ["quita " + app + " de la pantalla", "saca " + app + " de la pantalla"]):
            self.atlas_aclaracion_pendiente={"tipo":"ventana", "app":app}
            self.responder(f"¿quiere minimizar o cerrar {self._atlas_nombre_amigable_app(app)}?", "confundida")
            return True

        # Apertura de aplicaciones.
        if app and any(v in t for v in ["abre", "abrir", "inicia", "iniciar", "pon"]):
            # "abre el Word llamado X" se resolvió arriba como archivo.
            return self._atlas_abrir_aplicacion(app)

        # Acciones sobre ventanas; soporta pronombres y ASR fonético.
        accion=""
        if re.search(r"\b(?:minimiza|minimizar|minimizalo|minimizala|minimice)\b", t): accion="minimizar"
        elif re.search(r"\b(?:maximiza|maximizar|maximizalo|maximizala|maximice)\b", t): accion="maximizar"
        elif re.search(r"\b(?:restaura|restaurar|restauralo|restaurala)\b", t): accion="restaurar"
        elif re.search(r"\b(?:cierra|cerrar|cierralo|cierrala|cierrame)\b", t) or (app and t.startswith("ya termine con")): accion="cerrar"
        if accion:
            pronombre_contextual = bool(re.search(r"\b(?:minimizalo|minimizala|maximizalo|maximizala|restauralo|restaurala|cierralo|cierrala)\b", t))
            referencia_activa = any(x in t for x in ["esta ventana", "esa ventana", "esto", "esta aplicacion", "la ventana"])

            # Quitamos palabras funcionales para saber si el usuario mencionó un
            # objetivo que no pudimos identificar. v3.4.0 trataba cualquier app
            # desconocida como "ventana activa", lo que llegó a maximizar VS Code
            # cuando se había dicho Spotify.
            residuo = t
            residuo = re.sub(r"\b(?:minimiza|minimizar|minimizalo|minimizala|minimice|maximiza|maximizar|maximizalo|maximizala|maximice|restaura|restaurar|restauralo|restaurala|cierra|cerrar|cierralo|cierrala|cierrame)\b", " ", residuo)
            residuo = re.sub(r"\b(?:esta|esa|la|el|ventana|aplicacion|por favor|esto)\b", " ", residuo)
            residuo = re.sub(r"\s+", " ", residuo).strip()

            if not app and pronombre_contextual and self.atlas_ultima_aplicacion:
                app = self.atlas_ultima_aplicacion
            elif not app and not referencia_activa and not residuo and self.atlas_ultima_aplicacion:
                # "Beta, minimiza" tras abrir/controlar Spotify usa contexto.
                app = self.atlas_ultima_aplicacion

            if app:
                return self._atlas_controlar_ventana(accion, app)
            if referencia_activa or not residuo:
                return self._atlas_controlar_ventana(accion, "")

            # Cortafuegos: una orden de ventana reconocida nunca cae a Ollama.
            # Si no entendimos el objetivo, pedimos repetir en vez de ejecutar
            # sobre otra ventana o afirmar una acción ficticia.
            self.responder(f"entendí que quiere {accion} una ventana, pero no reconocí cuál. Repita el nombre de la aplicación.", "confundida")
            print(f"CONTROL ATLAS v3.5.2: acción bloqueada por objetivo ambiguo: {t!r}")
            return True

        # Cualquier deformación que todavía conserve un verbo exclusivo de
        # ventanas queda encerrada aquí y no llega al modelo conversacional.
        if re.search(r"\b(?:minimiz\w*|maximiz\w*|cerr\w*|cierr\w*|restaur\w*)\b", t):
            self.responder("entendí una orden de ventana, pero la transcripción no fue suficientemente clara. Repítala indicando la aplicación.", "confundida")
            print(f"CONTROL ATLAS v3.5.2: cortafuegos evitó fallback a Ollama: {t!r}")
            return True

        # Contexto corto de Spotify: "pausa" o "continúa" después de haberlo
        # usado. La API existente sigue siendo la que ejecuta el reproductor.
        if self._spotify_contexto_vigente():
            if t in {"pausa", "pausalo", "pausala"}:
                self.spotify_control_async("pausar"); return True
            if t in {"continua", "reanuda", "sigue", "reproduce"}:
                self.spotify_control_async("reanudar"); return True

        # Un nombre de carpeta aislado tampoco se entrega a Ollama. Es una
        # referencia operativa incompleta y se aclara localmente.
        m_carpeta_sola = re.match(r"^(?:la\s+)?carpeta\s+(.+)$", t)
        if m_carpeta_sola:
            objetivo_solo = m_carpeta_sola.group(1).strip()
            rutas_solo = self._atlas_resolver_carpeta_real(objetivo_solo)
            if len(rutas_solo) == 1:
                self.atlas_ultima_ruta_referida = rutas_solo[0]
                self.responder(f"encontré la carpeta {rutas_solo[0].name}. ¿Quiere que la abra, la ubique o revise su contenido?", "confundida")
            else:
                self.responder("entendí el nombre de una carpeta, pero necesito saber si quiere abrirla, ubicarla o revisar su contenido.", "confundida")
            print(f"CONTROL ATLAS v3.5.2: referencia de carpeta sin acción bloqueada: {t!r}")
            return True

        # Cortafuegos final del Explorador: si la frase claramente pretende
        # ubicar/revisar/listar una carpeta pero quedó deformada, pedimos repetir
        # en vez de permitir que Ollama invente rutas o contenidos.
        if "carpeta" in t and (
            re.search(r"\b(?:ubic\w*|localiz\w*|revis\w*|mostr\w*|muestr\w*|list\w*|contenid\w*|abr\w*|entr\w*|hag\w*|quiero)\b", t)
        ):
            self.responder("entendí una orden sobre una carpeta, pero no quedó suficientemente clara o no pude verificar una ruta real. Repita el nombre de la carpeta.", "confundida")
            print(f"CONTROL ATLAS v3.5.2: consulta de carpeta bloqueada antes de Ollama: {t!r}")
            return True

        # v3.5.2: una orden de administración de archivos jamás llega a Ollama.
        # Si quedó mal transcrita, se aclara localmente en vez de simular cambios.
        if re.search(r"\b(?:renombr\w*|copi\w*|muev\w*|mov\w*|elimin\w*|borr\w*|organiz\w*|orden\w*|sobrescrib\w*)\b", t) and any(x in t for x in ["archivo","carpeta","word","excel","pdf","documento"]):
            self.responder("entendí una orden para administrar archivos, pero no quedó suficientemente clara. Repítala indicando el elemento y el destino si corresponde.", "confundida")
            print(f"CONTROL ATLAS v3.5.2: administración bloqueada antes de Ollama: {t!r}")
            return True

        return False

    # ======================================================
    # ORQUESTADOR DE INTENCIONES / RECORDATORIOS v3.5.2
    # ======================================================

    @staticmethod
    def _orq_mes_numero(nombre):
        meses = {
            "enero":1, "febrero":2, "marzo":3, "abril":4, "mayo":5, "junio":6,
            "julio":7, "agosto":8, "septiembre":9, "setiembre":9,
            "octubre":10, "noviembre":11, "diciembre":12,
        }
        return meses.get(normalizar(nombre or ""), 0)

    @staticmethod
    def _orq_fecha_espanol(dt):
        dias = ["lunes", "martes", "miércoles", "jueves", "viernes", "sábado", "domingo"]
        meses = ["", "enero", "febrero", "marzo", "abril", "mayo", "junio",
                 "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre"]
        return f"{dias[dt.weekday()]} {dt.day} de {meses[dt.month]} de {dt.year}"

    def _orq_es_consulta_fecha(self, texto):
        t = normalizar(texto or "")
        if any(x in t for x in [
            "que fecha es hoy", "que dia es hoy", "cual es la fecha de hoy",
            "en que fecha estamos", "en que dia estamos", "fecha de hoy",
        ]):
            return True
        # Recupera deformaciones de Whisper como "que fechas oye" sin hacer
        # fuzzy matching global a cualquier frase.
        if "fecha" in t or "fechas" in t or ("dia" in t and "hoy" in t):
            objetivo = "que fecha es hoy"
            if difflib.SequenceMatcher(None, t, objetivo).ratio() >= 0.68:
                return True
        return False

    def _orq_es_ayuda_beta(self, texto):
        t = normalizar(texto or "")
        return any(x in t for x in [
            "que puedes hacer", "que puede hacer beta", "que sabes hacer",
            "todas tus funciones", "guia con todas tus funciones",
            "guia de tus funciones", "funciones de beta", "capacidades de beta",
            "dame una guia de beta", "dime tus funciones",
        ])

    def _orq_capacidades_reales(self):
        """Registro explícito de capacidades instaladas.

        Esta lista es la fuente de verdad de la ayuda de Beta. No se genera con
        Ollama ni con RAG, por lo que no puede prometer funciones inexistentes.
        """
        return [
            "controlar ventanas y aplicaciones de Atlas",
            "abrir y navegar carpetas reales y verificar su contenido",
            "crear y administrar archivos con confirmación en operaciones sensibles",
            "consultar CPU, RAM, disco, red y GPU sin inventar sensores",
            "controlar Spotify",
            "abrir Google y YouTube y realizar búsquedas reales",
            "guardar, consultar, reprogramar y cancelar recordatorios persistentes",
            "informar fecha, hora y clima",
            "trabajar en modo estudio con documentos, tareas y exportación a Word",
        ]

    def _orq_responder_ayuda_beta(self):
        capacidades=self._orq_capacidades_reales()
        texto="; ".join(capacidades)
        self.responder(
            "puedo " + texto + ". No afirmo que ejecuté una acción local si el módulo correspondiente no la confirmó.",
            "normal",
        )
        return True

    def _orq_es_web(self, texto):
        t = normalizar(texto or "")
        youtube = any(x in t for x in ["youtube", "yutube", "yutu", "you tube"])
        google = any(x in t for x in ["google", "chrome", "navegador", "internet"])
        accion = any(x in t for x in ["abre", "abrir", "busca", "buscar", "buscame", "encuentra", "ve a", "entra a"])
        return accion and (youtube or google)

    def _orq_extraer_busqueda_final(self, texto):
        t = normalizar(texto or "")
        partes = re.split(r"\b(?:busca|buscar|buscame|encuentra)\b", t)
        if len(partes) < 2:
            return ""
        q = partes[-1].strip(" ,.-")
        q = re.sub(r"^(?:en\s+)?(?:google|chrome|internet|youtube|yutube|yutu)\s+(?:y\s+)?", "", q).strip()
        q = re.sub(r"^(?:videos?|resultados?)\s+(?:relacionados?\s+con|sobre|de)\s+", "", q).strip()
        q = re.sub(r"^(?:relacionado|relacionados|relacionada|relacionadas)\s+con\s+", "", q).strip()
        return q

    def _orq_manejar_web(self, original):
        t = normalizar(original or "")
        es_youtube = any(x in t for x in ["youtube", "yutube", "yutu", "you tube"])
        if es_youtube:
            # Si hay una orden explícita de búsqueda, tomamos la ÚLTIMA
            # cláusula de búsqueda. Esto evita consultas contaminadas como
            # "abre Google y busca YouTube y busca videos...".
            if re.search(r"\b(?:busca|buscar|buscame|encuentra)\b", t):
                consulta = self._orq_extraer_busqueda_final(original)
                if consulta:
                    self.buscar_en_youtube(consulta)
                    return True
            orden = self.extraer_orden_youtube(original)
            if orden:
                consulta, reproducir, solo_abrir = orden
                if solo_abrir:
                    self.abrir_youtube_inicio()
                elif reproducir:
                    self.reproducir_youtube_async(consulta)
                else:
                    self.buscar_en_youtube(consulta)
                return True
            self.abrir_youtube_inicio()
            return True

        # Google/Chrome. "abre Google" abre el sitio; "abre Chrome" abre
        # solamente la aplicación. Con una consulta se abren resultados reales.
        consulta = self._orq_extraer_busqueda_final(original)
        if consulta:
            self.buscar_en_chrome(consulta, modo_imagenes=False)
        elif "google chrome" in t or ("chrome" in t and "google" not in t):
            self.abrir_chrome()
        else:
            self.abrir_url_en_chrome("https://www.google.com/")
            self.responder("abriendo Google.", "feliz")
        return True

    def _recordatorios_conexion(self):
        return sqlite3.connect(BASE_DATOS, timeout=15)

    def _recordatorios_inicializar_db(self):
        try:
            with self._recordatorios_conexion() as con:
                con.execute(
                    """
                    CREATE TABLE IF NOT EXISTS recordatorios_beta (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        creado_en TEXT NOT NULL,
                        aviso_en TEXT NOT NULL,
                        texto TEXT NOT NULL,
                        evento_en TEXT DEFAULT '',
                        estado TEXT NOT NULL DEFAULT 'pendiente',
                        avisado_en TEXT DEFAULT ''
                    )
                    """
                )
                con.execute(
                    "CREATE INDEX IF NOT EXISTS idx_recordatorios_beta_aviso "
                    "ON recordatorios_beta(estado, aviso_en)"
                )
                con.commit()
        except Exception as error:
            print("RECORDATORIOS v3.5.2: no pude inicializar SQLite:", error)

    def _recordatorios_extraer_fechas(self, texto):
        t = normalizar(texto or "")
        patron = re.compile(
            r"(?:el\s+)?(?:dia\s+)?(\d{1,2})\s+de\s+"
            r"(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|setiembre|octubre|noviembre|diciembre)"
            r"(?:\s+de\s+(\d{4}))?"
        )
        ahora = datetime.now()
        encontrados=[]
        for m in patron.finditer(t):
            dia=int(m.group(1)); mes=self._orq_mes_numero(m.group(2)); anio=int(m.group(3) or ahora.year)
            try:
                dt=datetime(anio,mes,dia)
            except Exception:
                continue
            if not m.group(3) and dt.date() < ahora.date() and (ahora.date()-dt.date()).days > 2:
                try: dt=dt.replace(year=anio+1)
                except Exception: pass
            encontrados.append((m,dt))
        if not encontrados:
            # Fechas relativas frecuentes para recordatorios naturales.
            if "pasado manana" in t:
                dt=ahora + timedelta(days=2); m=re.search(r"pasado\s+manana", t)
                encontrados.append((m, dt.replace(hour=0,minute=0,second=0,microsecond=0)))
            elif "manana" in t:
                dt=ahora + timedelta(days=1); m=re.search(r"manana", t)
                encontrados.append((m, dt.replace(hour=0,minute=0,second=0,microsecond=0)))
            elif re.search(r"\bhoy\b", t):
                m=re.search(r"\bhoy\b", t); encontrados.append((m, ahora.replace(hour=0,minute=0,second=0,microsecond=0)))
        return encontrados

    def _recordatorios_extraer_hora(self, texto):
        t=normalizar(texto or "")
        m=re.search(r"(?:a\s+las?|a\s+la)\s+(\d{1,2})(?::(\d{2}))?\s*(?:horas?)?(?:\s+de\s+la\s+(manana|tarde|noche))?", t)
        if not m:
            return None
        h=int(m.group(1)); mi=int(m.group(2) or 0); tramo=m.group(3) or ""
        if tramo in {"tarde","noche"} and h < 12: h += 12
        if tramo == "manana" and h == 12: h=0
        if 0 <= h <= 23 and 0 <= mi <= 59:
            return h,mi
        return None

    def _recordatorios_guardar(self, aviso_dt, texto, evento_dt=None):
        try:
            with self._recordatorios_conexion() as con:
                cur=con.execute(
                    "INSERT INTO recordatorios_beta(creado_en,aviso_en,texto,evento_en,estado,avisado_en) VALUES(?,?,?,?,?,?)",
                    (datetime.now().isoformat(timespec="seconds"), aviso_dt.isoformat(timespec="minutes"),
                     str(texto).strip(), evento_dt.isoformat(timespec="minutes") if evento_dt else "", "pendiente", "")
                )
                con.commit(); return int(cur.lastrowid)
        except Exception as error:
            print("RECORDATORIOS v3.5.2: error guardando:", error)
            return 0

    def _recordatorios_listar(self, fecha=None):
        try:
            with self._recordatorios_conexion() as con:
                con.row_factory=sqlite3.Row
                if fecha:
                    pref=fecha.strftime("%Y-%m-%d")+"%"
                    rows=con.execute(
                        "SELECT * FROM recordatorios_beta WHERE estado='pendiente' AND aviso_en LIKE ? ORDER BY aviso_en", (pref,)
                    ).fetchall()
                else:
                    rows=con.execute(
                        "SELECT * FROM recordatorios_beta WHERE estado='pendiente' ORDER BY aviso_en LIMIT 12"
                    ).fetchall()
            return [dict(r) for r in rows]
        except Exception as error:
            print("RECORDATORIOS v3.5.2: error listando:", error); return []

    def _recordatorios_filtrar_dia(self, rows, dia):
        salida=[]
        for r in rows or []:
            try:
                if datetime.fromisoformat(str(r.get("aviso_en") or "")).day == int(dia):
                    salida.append(r)
            except Exception:
                continue
        return salida

    def _recordatorios_actualizar_aviso(self, rid, nuevo_dt):
        try:
            with self._recordatorios_conexion() as con:
                con.execute(
                    "UPDATE recordatorios_beta SET aviso_en=?, estado='pendiente', avisado_en='' WHERE id=?",
                    (nuevo_dt.isoformat(timespec="minutes"), int(rid)),
                )
                con.commit()
            return True
        except Exception as error:
            print("RECORDATORIOS v3.5.2: error reprogramando:", error)
            return False

    def _recordatorios_vigilar(self):
        try:
            if not self.recordatorio_alerta_activa:
                ahora=datetime.now()
                with self._recordatorios_conexion() as con:
                    con.row_factory=sqlite3.Row
                    row=con.execute(
                        "SELECT * FROM recordatorios_beta WHERE estado='pendiente' AND aviso_en<=? ORDER BY aviso_en LIMIT 1",
                        (ahora.isoformat(timespec="minutes"),)
                    ).fetchone()
                    if row and not self.hablando and not self.procesando:
                        con.execute(
                            "UPDATE recordatorios_beta SET estado='avisado', avisado_en=? WHERE id=?",
                            (ahora.isoformat(timespec="seconds"), int(row['id']))
                        ); con.commit()
                        self.recordatorio_alerta_activa=True
                        self.responder("recordatorio: " + str(row['texto']), "sorpresa")
                        self.recordatorio_alerta_activa=False
                        print(f"RECORDATORIOS v3.5.2: aviso emitido id={row['id']}")
        except Exception as error:
            print("RECORDATORIOS v3.5.2: error vigilando:", error)
        finally:
            try: self.root.after(30000, self._recordatorios_vigilar)
            except Exception: pass

    def _orq_es_recordatorio(self, texto):
        t=normalizar(texto or "")
        marcas=[
            "recuerdame", "recordatorio", "avisame", "me avises", "me recuerdes",
            "que tienes que recordarme", "que me tienes que recordar", "quien me tiene que recordar",
            "que tengo que recordar", "que debo recordar", "mis recordatorios",
            "que recordatorios", "calendario", "agenda",
        ]
        return any(x in t for x in marcas)

    def _orq_texto_recordatorio(self, original, fechas):
        t=normalizar(original or "")
        if len(fechas) >= 2:
            m1,d1=fechas[0]; m2,d2=fechas[1]
            entre=t[m1.end():m2.start()]
            entre=re.sub(r"^[, ]*(?:que\s+)?", "", entre).strip()
            entre=re.sub(r"(?:el\s+)?(?:dia\s+)?$", "", entre).strip()
            despues=t[m2.end():].strip(" ,.-")
            partes=[x for x in [entre, despues] if x]
            detalle=" ".join(partes).strip()
            fecha_evt=f"{d2.day} de {['','enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'][d2.month]}"
            return (f"el {fecha_evt} {detalle}".strip(), d2)
        m,d=fechas[0]
        despues=t[m.end():].strip(" ,.-")
        return (despues or f"recordatorio programado para {self._orq_fecha_espanol(d)}", d)

    def _orq_manejar_recordatorio(self, original):
        t=normalizar(original or "")
        fechas=self._recordatorios_extraer_fechas(original)

        # Consultar recordatorios, con o sin fecha concreta.
        if any(x in t for x in [
            "que tienes que recordarme", "que me tienes que recordar", "quien me tiene que recordar",
            "que tengo que recordar", "que debo recordar", "mis recordatorios", "que recordatorios"
        ]):
            fecha=fechas[0][1] if fechas else None
            rows=self._recordatorios_listar(fecha)
            # Whisper puede conservar solamente "día 16" y omitir el mes.
            # En una consulta de recordatorios es seguro filtrar los pendientes
            # por número de día; no se crea ni modifica nada.
            if not fecha:
                m_dia=re.search(r"\bdia\s+(\d{1,2})\b", t)
                if m_dia:
                    rows=self._recordatorios_filtrar_dia(self._recordatorios_listar(), int(m_dia.group(1)))
            if not rows:
                self.responder("no tengo recordatorios pendientes" + (" para esa fecha." if fecha else "."), "normal")
                return True
            partes=[]
            for r in rows[:5]:
                try: dt=datetime.fromisoformat(r['aviso_en']); cuando=f"{dt.day:02d}-{dt.month:02d}-{dt.year} a las {dt:%H:%M}"
                except Exception: cuando=r['aviso_en']
                partes.append(f"{cuando}: {r['texto']}")
            self.responder("tengo " + str(len(rows)) + " recordatorio" + ("s" if len(rows)!=1 else "") + ": " + "; ".join(partes) + ".", "normal")
            return True

        if any(x in t for x in ["cambia el recordatorio", "reprograma el recordatorio", "mueve el recordatorio"]):
            hora_nueva=self._recordatorios_extraer_hora(original)
            if not hora_nueva:
                self.responder("entendí que quiere cambiar un recordatorio, pero me falta la nueva hora.", "confundida")
                return True
            candidatos=self._recordatorios_listar(fechas[0][1] if fechas else None)
            if not fechas:
                m_dia=re.search(r"\bdia\s+(\d{1,2})\b", t)
                if m_dia:
                    candidatos=self._recordatorios_filtrar_dia(self._recordatorios_listar(), int(m_dia.group(1)))
            if len(candidatos) != 1:
                self.responder(
                    "necesito que indique con más precisión cuál recordatorio desea cambiar." if candidatos else
                    "no encontré un recordatorio pendiente que coincida.",
                    "confundida",
                )
                return True
            r=candidatos[0]
            try:
                actual=datetime.fromisoformat(r['aviso_en'])
                nuevo=actual.replace(hour=hora_nueva[0], minute=hora_nueva[1])
            except Exception:
                self.responder("no pude interpretar la fecha de ese recordatorio.", "molesta")
                return True
            if self._recordatorios_actualizar_aviso(r['id'], nuevo):
                self.responder(f"recordatorio reprogramado para {self._orq_fecha_espanol(nuevo)} a las {nuevo:%H:%M}.", "feliz")
            else:
                self.responder("no pude reprogramar ese recordatorio.", "molesta")
            return True

        if any(x in t for x in ["cancela el recordatorio", "elimina el recordatorio", "borra el recordatorio"]):
            criterio=re.sub(r".*?(?:recordatorio)\s*(?:de|del|sobre)?\s*", "", t).strip()
            try:
                with self._recordatorios_conexion() as con:
                    con.row_factory=sqlite3.Row
                    if fechas:
                        pref=fechas[0][1].strftime("%Y-%m-%d") + "%"
                        rows=con.execute("SELECT * FROM recordatorios_beta WHERE estado='pendiente' AND aviso_en LIKE ? ORDER BY aviso_en", (pref,)).fetchall()
                    elif re.search(r"\bdia\s+(\d{1,2})\b", t):
                        todos=con.execute("SELECT * FROM recordatorios_beta WHERE estado='pendiente' ORDER BY aviso_en").fetchall()
                        dia=int(re.search(r"\bdia\s+(\d{1,2})\b", t).group(1))
                        rows=[r for r in todos if datetime.fromisoformat(r['aviso_en']).day == dia]
                    elif criterio:
                        rows=con.execute("SELECT * FROM recordatorios_beta WHERE estado='pendiente' AND lower(texto) LIKE ? ORDER BY aviso_en", (f"%{criterio}%",)).fetchall()
                    else:
                        rows=con.execute("SELECT * FROM recordatorios_beta WHERE estado='pendiente' ORDER BY aviso_en").fetchall()
                    if len(rows)==1:
                        con.execute("UPDATE recordatorios_beta SET estado='cancelado' WHERE id=?", (int(rows[0]['id']),)); con.commit()
                        self.responder("recordatorio cancelado.", "normal")
                    elif len(rows)>1:
                        self.responder("encontré varios recordatorios coincidentes. Indique con más detalle cuál desea cancelar.", "confundida")
                    else:
                        self.responder("no encontré un recordatorio pendiente que coincida.", "confundida")
                return True
            except Exception as error:
                print("RECORDATORIOS v3.5.2: error cancelando:", error)
                self.responder("no pude cancelar ese recordatorio.", "molesta"); return True

        if not fechas:
            self.responder("entendí que quiere crear un recordatorio, pero me falta una fecha concreta.", "confundida")
            return True

        # Si hay dos fechas, la primera es el día de aviso y la segunda el evento.
        aviso_base=fechas[0][1]
        hora=self._recordatorios_extraer_hora(original)
        evento_dt=None
        if len(fechas)>=2:
            texto_recordatorio, evento_base=self._orq_texto_recordatorio(original, fechas)
            evento_hora=hora or (9,0)
            evento_dt=evento_base.replace(hour=evento_hora[0], minute=evento_hora[1])
            # Si no se especificó hora para AVISO, usamos las 09:00 y lo decimos.
            aviso_dt=aviso_base.replace(hour=9, minute=0)
        else:
            texto_recordatorio, evento_base=self._orq_texto_recordatorio(original, fechas)
            h,mi=hora or (9,0)
            aviso_dt=aviso_base.replace(hour=h, minute=mi)
            evento_dt=evento_base.replace(hour=h, minute=mi) if "calendario" in t or "agenda" in t else None

        rid=self._recordatorios_guardar(aviso_dt, texto_recordatorio, evento_dt)
        if not rid:
            self.responder("no pude guardar el recordatorio.", "molesta"); return True
        cuando=self._orq_fecha_espanol(aviso_dt) + f" a las {aviso_dt:%H:%M}"
        if "calendario" in t or "agenda" in t:
            self.responder(f"guardé el evento en la agenda local de Beta y programé el aviso para {cuando}. No estoy afirmando que lo haya insertado en un calendario externo.", "feliz")
        else:
            self.responder(f"recordatorio guardado para {cuando}.", "feliz")
        print(f"RECORDATORIOS v3.5.2: guardado id={rid} aviso={aviso_dt.isoformat(timespec='minutes')}")
        return True

    def _orq_normalizar_hardware_contextual(self, texto):
        """Normaliza deformaciones SOLO cuando la frase ya habla de hardware/temperatura."""
        t=normalizar(texto or "")
        if not any(x in t for x in ["temperatura", "uso", "estado", "cpu", "gpu", "procesador", "computador", "atlas"]):
            return t
        # Casos reales observados en Atlas para CPU. No se aplican a conversación general.
        cpu_patrones=[
            r"\bce\s+pe\s+u\b", r"\bse\s+pe\s+u\b", r"\bse\s+ve\s+un\b",
            r"\bse\s+un\b", r"\bni\s+se\s+pew\b", r"\bse\s+pew\b",
            r"\bcipiu\b", r"\bpp\b",
        ]
        for p in cpu_patrones:
            t=re.sub(p, "cpu", t)
        gpu_patrones=[r"\bge\s+pe\s+u\b", r"\bg\s+p\s+u\b"]
        for p in gpu_patrones:
            t=re.sub(p, "gpu", t)
        return re.sub(r"\s+", " ", t).strip()

    def _orq_manejar_temperatura_hardware(self, texto):
        t=self._orq_normalizar_hardware_contextual(texto)
        if "temperatura" not in t:
            return False
        if any(x in t for x in ["gpu", "tarjeta grafica", "grafica"]):
            return self._atlas_estado_sistema_async("gpu")
        if any(x in t for x in ["cpu", "procesador", "microprocesador"]):
            return self._atlas_estado_sistema_async("cpu")
        if any(x in t for x in ["computador", "pc", "equipo", "atlas"]):
            return self._atlas_estado_sistema_async("resumen")
        return False

    def _orq_temperatura_ambigua(self, texto):
        t=self._orq_normalizar_hardware_contextual(texto)
        if "temperatura" not in t:
            return False
        # Señales meteorológicas explícitas: se dejan continuar al módulo clima.
        if any(x in t for x in [
            "clima", "ambiente", "ambiental", "afuera", "exterior",
            "como esta el tiempo", "que tiempo hace", "pronostico",
        ]):
            return False
        if re.search(r"\btemperatura\s+en\s+", t):
            return False
        # Una pregunta genérica de temperatura puede seguir significando clima.
        if t in {"temperatura", "dime la temperatura", "que temperatura hace", "cual es la temperatura"}:
            return False
        # Si el usuario dijo "temperatura del/de la/de mi ..." y no pudimos
        # identificar CPU/GPU/PC, es más seguro preguntar que devolver el clima.
        return bool(re.search(r"\btemperatura\s+(?:del|de la|de mi|de este|de esta)\b", t))

    def _orquestar_intencion_previa(self, original):
        t=normalizar(original or "")
        if not t:
            return False

        # 1) Tareas persistentes: nunca pasan por memoria inteligente ni RAG.
        if self._orq_es_recordatorio(t):
            self.orquestador_ultima_intencion="recordatorio"
            print("ORQUESTADOR v3.5.2: intención=recordatorio")
            return self._orq_manejar_recordatorio(original)

        # 2) Navegación web real antes del Explorador de archivos.
        if self._orq_es_web(t):
            self.orquestador_ultima_intencion="web"
            print("ORQUESTADOR v3.5.2: intención=web")
            return self._orq_manejar_web(original)

        # 3) Fecha/hora son utilidades locales; no consultan libros.
        if self._orq_es_consulta_fecha(t):
            self.orquestador_ultima_intencion="fecha"
            ahora=datetime.now()
            self.responder(f"hoy es {self._orq_fecha_espanol(ahora)}.", "normal")
            print("ORQUESTADOR v3.5.2: intención=fecha")
            return True
        if self._es_consulta_hora(t):
            self.orquestador_ultima_intencion="hora"
            self.responder(f"son las {time.strftime('%H:%M')}.", "normal")
            print("ORQUESTADOR v3.5.2: intención=hora")
            return True

        # 4) Hardware tiene precedencia ABSOLUTA sobre clima cuando se nombra
        # CPU/GPU/PC, incluso con deformaciones fonéticas observadas en Atlas.
        if "temperatura" in t and self._orq_manejar_temperatura_hardware(t):
            self.orquestador_ultima_intencion="hardware"
            print("ORQUESTADOR v3.5.2: intención=hardware")
            return True
        if self._orq_temperatura_ambigua(t):
            self.orquestador_ultima_intencion="aclaracion_temperatura"
            self.responder("¿se refiere a la temperatura del computador o a la temperatura ambiente?", "confundida")
            print("ORQUESTADOR v3.5.2: intención=aclaracion_temperatura")
            return True

        # 5) Ayuda sobre Beta se genera desde capacidades reales, no desde libros.
        if self._orq_es_ayuda_beta(t):
            self.orquestador_ultima_intencion="ayuda_beta"
            print("ORQUESTADOR v3.5.2: intención=ayuda_beta")
            return self._orq_responder_ayuda_beta()

        return False

